import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";

export async function test_api_guest_join_success(connection: api.IConnection) {
  // 1) Prepare a minimal, valid request body for guest self-join
  const requestBody = {
    displayName: "guest-automated-test",
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardGuest.ICreate;

  // 2) Call the guest join API
  const authorized: IDiscussionBoardGuest.IAuthorized =
    await api.functional.auth.guest.join(connection, {
      body: requestBody,
    });

  // 3) Runtime type validation for entire response
  typia.assert(authorized);

  // 4) Basic business assertions
  TestValidator.predicate(
    "guest id exists",
    authorized.id !== null && authorized.id !== undefined,
  );
  TestValidator.equals(
    "displayName matches request",
    authorized.displayName,
    requestBody.displayName,
  );

  // 5) If an embedded summary is present, ensure it references the same guest id
  if (authorized.guest) {
    typia.assert(authorized.guest);
    TestValidator.equals(
      "embedded guest id matches top-level id",
      authorized.guest.id,
      authorized.id,
    );
  }

  // 6) Token presence and basic checks
  const token: IAuthorizationToken = authorized.token;
  typia.assert(token);
  TestValidator.predicate(
    "access token present and non-empty",
    typeof token.access === "string" && token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token present and non-empty",
    typeof token.refresh === "string" && token.refresh.length > 0,
  );

  // 7) Temporal fields: ensure they parse to valid dates and satisfy business ordering
  const createdAtNum = new Date(authorized.createdAt).getTime();
  const updatedAtNum = new Date(authorized.updatedAt).getTime();
  const tokenExpiresNum = new Date(token.expired_at).getTime();
  const refreshableUntilNum = new Date(token.refreshable_until).getTime();

  TestValidator.predicate(
    "createdAt is a valid ISO date",
    Number.isFinite(createdAtNum),
  );
  TestValidator.predicate(
    "updatedAt is a valid ISO date",
    Number.isFinite(updatedAtNum),
  );
  TestValidator.predicate(
    "token.expired_at is a valid ISO date",
    Number.isFinite(tokenExpiresNum),
  );
  TestValidator.predicate(
    "token.refreshable_until is a valid ISO date",
    Number.isFinite(refreshableUntilNum),
  );

  TestValidator.predicate(
    "updatedAt is not before createdAt",
    updatedAtNum >= createdAtNum,
  );
  TestValidator.predicate(
    "token expiry after creation",
    tokenExpiresNum > createdAtNum,
  );
  TestValidator.predicate(
    "refreshable_until not before token expiry",
    refreshableUntilNum >= tokenExpiresNum,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";

export async function test_api_guest_refresh_success(
  connection: api.IConnection,
) {
  // 1) Create a temporary guest via POST /auth/guest/join
  const joinBody = {
    displayName: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardGuest.ICreate;

  const original: IDiscussionBoardGuest.IAuthorized =
    await api.functional.auth.guest.join(connection, {
      body: joinBody,
    });
  // Validate response shape
  typia.assert(original);

  // Extract original tokens and guest id
  const originalToken: IAuthorizationToken = original.token;
  const guestId: string & tags.Format<"uuid"> = original.id;

  // Basic sanity checks on returned token
  TestValidator.predicate(
    "original access token not empty",
    originalToken.access.length > 0,
  );
  TestValidator.predicate(
    "original refresh token not empty",
    originalToken.refresh.length > 0,
  );

  // 2) Call POST /auth/guest/refresh with the valid refresh token
  const refreshBody = {
    refresh_token: originalToken.refresh,
  } satisfies IDiscussionBoardGuest.IRefresh;

  const refreshed: IDiscussionBoardGuest.IAuthorized =
    await api.functional.auth.guest.refresh(connection, {
      body: refreshBody,
    });
  typia.assert(refreshed);

  // 3) Verify the response returns a renewed access token and references same guest id
  TestValidator.equals(
    "guest id preserved after refresh",
    refreshed.id,
    guestId,
  );

  // Access token should be rotated (new value)
  TestValidator.notEquals(
    "access token rotated",
    originalToken.access,
    refreshed.token.access,
  );

  // Refresh token may or may not be rotated. Ensure refreshed refresh token exists and is a string.
  TestValidator.predicate(
    "refreshed refresh token exists",
    typeof refreshed.token.refresh === "string" &&
      refreshed.token.refresh.length > 0,
  );

  // 4) Confirm the guest row exists (deleted_at is null)
  // The DTO allows deletedAt to be null|undefined; per scenario require explicit null
  TestValidator.equals(
    "guest not deleted (deletedAt is null)",
    refreshed.deletedAt,
    null,
  );

  // 5) Token lifetime checks: access expiry should be a valid date and short-lived
  const accessExpiry = Date.parse(refreshed.token.expired_at);
  const refreshExpiry = Date.parse(refreshed.token.refreshable_until);
  TestValidator.predicate(
    "access expiry is a valid timestamp",
    !Number.isNaN(accessExpiry),
  );
  TestValidator.predicate(
    "refreshable_until is a valid timestamp",
    !Number.isNaN(refreshExpiry),
  );

  // Access token lifetime should be reasonably short from now (e.g., within 6 hours)
  TestValidator.predicate(
    "access token lifetime is short (<=6 hours)",
    accessExpiry - Date.now() <= 1000 * 60 * 60 * 6,
  );

  // Refresh token lifetime should be within a reasonable sliding window (e.g., <= 7 days)
  TestValidator.predicate(
    "refresh token lifetime is limited (<=7 days)",
    refreshExpiry - Date.now() <= 1000 * 60 * 60 * 24 * 7,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";

/**
 * Validate guest refresh rejects invalid/expired refresh tokens while
 * preserving the original guest record and allowing valid tokens to be
 * refreshed.
 *
 * Workflow:
 *
 * 1. Create a temporary guest via POST /auth/guest/join to obtain initial tokens.
 * 2. Mutate the issued refresh token to simulate an invalid/expired token.
 * 3. Attempt POST /auth/guest/refresh with the mutated token and expect an error.
 * 4. Retry POST /auth/guest/refresh with the original valid refresh token and
 *    expect success. Verify the guest id remains unchanged and the guest record
 *    remains active (deletedAt is null or undefined).
 */
export async function test_api_guest_refresh_invalid_token(
  connection: api.IConnection,
) {
  // 1) Create a guest to obtain initial tokens
  const createBody = {
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
    displayName: RandomGenerator.name(),
  } satisfies IDiscussionBoardGuest.ICreate;

  const authorized: IDiscussionBoardGuest.IAuthorized =
    await api.functional.auth.guest.join(connection, {
      body: createBody,
    });
  typia.assert(authorized);

  // Store the original valid refresh token
  const originalRefreshToken: string = authorized.token.refresh;

  // 2) Mutate the refresh token to simulate invalid/expired token
  const invalidRefreshToken: string = originalRefreshToken + "-invalid";

  // 3) Attempt refresh with invalid token and expect an error (business-level rejection)
  await TestValidator.error(
    "refresh with mutated/invalid refresh token should fail",
    async () => {
      await api.functional.auth.guest.refresh(connection, {
        body: {
          refresh_token: invalidRefreshToken,
        } satisfies IDiscussionBoardGuest.IRefresh,
      });
    },
  );

  // 4) Retry refresh with the original valid refresh token and expect success
  const renewed: IDiscussionBoardGuest.IAuthorized =
    await api.functional.auth.guest.refresh(connection, {
      body: {
        refresh_token: originalRefreshToken,
      } satisfies IDiscussionBoardGuest.IRefresh,
    });
  typia.assert(renewed);

  // Business validations
  TestValidator.equals(
    "guest id unchanged after invalid refresh attempt",
    renewed.id,
    authorized.id,
  );
  TestValidator.predicate(
    "guest record remains active (deletedAt null or undefined)",
    renewed.deletedAt === null || renewed.deletedAt === undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCategory";

export async function test_api_category_list_public(
  connection: api.IConnection,
) {
  // 1) Create moderator account (will set connection.headers.Authorization automatically)
  const moderatorInput = {
    username:
      RandomGenerator.name(1).replace(/\s+/g, "_").toLowerCase() +
      RandomGenerator.alphaNumeric(4),
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardModerator.ICreate;

  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: moderatorInput,
    });
  typia.assert(moderator);

  // 2) Create categories using moderator context
  const activeCategoryInput = {
    name: RandomGenerator.name(2),
    slug: RandomGenerator.alphabets(8).toLowerCase(),
    description: RandomGenerator.paragraph(),
    is_active: true,
  } satisfies IDiscussionBoardCategory.ICreate;

  const inactiveCategoryInput = {
    name: RandomGenerator.name(2),
    slug: RandomGenerator.alphabets(8).toLowerCase(),
    description: RandomGenerator.paragraph(),
    is_active: false,
  } satisfies IDiscussionBoardCategory.ICreate;

  // Create a category that we'll search for
  const searchToken = RandomGenerator.substring(RandomGenerator.paragraph());
  const searchCategoryInput = {
    name: `search-${searchToken}`,
    slug: `search-${RandomGenerator.alphabets(6)}`.toLowerCase(),
    description: RandomGenerator.paragraph(),
    is_active: true,
  } satisfies IDiscussionBoardCategory.ICreate;

  const activeCategory: IDiscussionBoardCategory =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: activeCategoryInput,
      },
    );
  typia.assert(activeCategory);

  const inactiveCategory: IDiscussionBoardCategory =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: inactiveCategoryInput,
      },
    );
  typia.assert(inactiveCategory);

  const searchCategory: IDiscussionBoardCategory =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: searchCategoryInput,
      },
    );
  typia.assert(searchCategory);

  // 3) As unauthenticated client, list categories with default pagination
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  const pageDefault: IPageIDiscussionBoardCategory.ISummary =
    await api.functional.discussionBoard.categories.index(unauthConn, {
      body: {} satisfies IDiscussionBoardCategory.IRequest,
    });
  typia.assert(pageDefault);

  // Validate pagination metadata
  TestValidator.predicate(
    "pagination.current is a non-negative integer",
    typeof pageDefault.pagination.current === "number" &&
      pageDefault.pagination.current >= 0,
  );
  TestValidator.predicate(
    "pagination.limit is a non-negative integer",
    typeof pageDefault.pagination.limit === "number" &&
      pageDefault.pagination.limit >= 0,
  );
  TestValidator.predicate(
    "pagination.records is a non-negative integer",
    typeof pageDefault.pagination.records === "number" &&
      pageDefault.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination.pages is a non-negative integer",
    typeof pageDefault.pagination.pages === "number" &&
      pageDefault.pagination.pages >= 0,
  );

  // Ensure activeCategory is present and inactiveCategory is omitted by default
  TestValidator.predicate(
    "default listing contains created active category",
    ArrayUtil.has(pageDefault.data, (c) => c.id === activeCategory.id),
  );

  TestValidator.predicate(
    "default listing does not contain inactive (non-public) category",
    !ArrayUtil.has(pageDefault.data, (c) => c.id === inactiveCategory.id),
  );

  // 4) Filtering: request only active categories
  const pageActiveOnly: IPageIDiscussionBoardCategory.ISummary =
    await api.functional.discussionBoard.categories.index(unauthConn, {
      body: { isActive: true } satisfies IDiscussionBoardCategory.IRequest,
    });
  typia.assert(pageActiveOnly);

  TestValidator.predicate(
    "all returned categories are active",
    pageActiveOnly.data.every((d) => d.is_active === true),
  );

  TestValidator.predicate(
    "inactive category is not present in active-only listing",
    !ArrayUtil.has(pageActiveOnly.data, (c) => c.id === inactiveCategory.id),
  );

  // 5) Search: partial search using a substring of searchCategory.name
  const partial = searchCategory.name.substring(
    0,
    Math.min(8, searchCategory.name.length),
  );
  const pageSearch: IPageIDiscussionBoardCategory.ISummary =
    await api.functional.discussionBoard.categories.index(unauthConn, {
      body: { search: partial } satisfies IDiscussionBoardCategory.IRequest,
    });
  typia.assert(pageSearch);

  TestValidator.predicate(
    `search results include category matching partial '${partial}'`,
    ArrayUtil.has(pageSearch.data, (c) => c.id === searchCategory.id),
  );

  // 6) Soft-delete semantics (adapted): since provided SDK does not expose a
  // delete endpoint, treat is_active=false as a proxy for non-public/archived
  // categories and confirm they are excluded by default (already validated above).

  // 7) Error handling: invalid pagination
  await TestValidator.error("limit > 100 should be rejected", async () => {
    await api.functional.discussionBoard.categories.index(unauthConn, {
      body: { limit: 101 } satisfies IDiscussionBoardCategory.IRequest,
    });
  });

  await TestValidator.error("page < 1 should be rejected", async () => {
    await api.functional.discussionBoard.categories.index(unauthConn, {
      body: { page: 0 } satisfies IDiscussionBoardCategory.IRequest,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Validate public retrieval of a discussion board category by slug.
 *
 * Business context:
 *
 * - Moderators can create categories used to organize discussion board articles.
 *   Categories are publicly retrievable by slug.
 * - This test creates a moderator, uses that moderator to create a category, and
 *   validates that unauthenticated (public) callers can successfully retrieve
 *   that category by slug. It also validates error behavior for an invalid slug
 *   format and a non-existent slug. The scenario to verify soft-delete
 *   visibility was omitted because the SDK does not provide a category
 *   delete/erase endpoint; instead we validate the non-existent slug behavior.
 *
 * Steps:
 *
 * 1. Moderator signs up via POST /auth/moderator/join
 * 2. Moderator creates a category via POST /discussionBoard/moderator/categories
 * 3. Public (unauthenticated) client GETs the category by slug and verifies the
 *    returned entity fields
 * 4. Validate invalid slug format produces an error
 * 5. Validate non-existent slug produces an error
 */
export async function test_api_category_get_by_slug_public(
  connection: api.IConnection,
) {
  // 1) Create moderator account
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorUsername: string = RandomGenerator.name(1)
    .toLowerCase()
    .replace(/\s+/g, "")
    .slice(0, 20);
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      username: moderatorUsername,
      email: moderatorEmail,
      password: RandomGenerator.alphaNumeric(12),
      href: "https://example.test/",
      referrer: "https://example.test/",
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // 2) Create a category as moderator
  const slugBase = RandomGenerator.alphabets(8).toLowerCase();
  const createBody = {
    name: RandomGenerator.name(2),
    slug: slugBase,
    description: RandomGenerator.paragraph({
      sentences: 6,
      wordMin: 3,
      wordMax: 8,
    }),
    is_active: true,
  } satisfies IDiscussionBoardCategory.ICreate;

  const created: IDiscussionBoardCategory =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: createBody,
      },
    );
  typia.assert(created);

  // 3) Public retrieval using unauthenticated connection
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  const reloaded: IDiscussionBoardCategory =
    await api.functional.discussionBoard.categories.at(unauthConn, {
      categorySlug: created.slug,
    });
  typia.assert(reloaded);

  // Validate returned fields match created resource
  TestValidator.equals(
    "category id matches created id",
    reloaded.id,
    created.id,
  );
  TestValidator.equals("category name matches", reloaded.name, created.name);
  TestValidator.equals("category slug matches", reloaded.slug, created.slug);
  TestValidator.equals(
    "category description matches",
    reloaded.description,
    created.description,
  );
  TestValidator.equals(
    "category is_active matches",
    reloaded.is_active,
    created.is_active,
  );
  TestValidator.predicate(
    "category has created_at",
    typeof reloaded.created_at === "string" && reloaded.created_at.length > 0,
  );
  TestValidator.predicate(
    "category has updated_at",
    typeof reloaded.updated_at === "string" && reloaded.updated_at.length > 0,
  );
  // deleted_at should be null or undefined for active category
  TestValidator.predicate(
    "category deleted_at is null or undefined",
    reloaded.deleted_at === null || reloaded.deleted_at === undefined,
  );

  // 4) Invalid slug format should cause an error (business validation)
  await TestValidator.error("invalid slug format should error", async () => {
    await api.functional.discussionBoard.categories.at(unauthConn, {
      categorySlug: "invalid slug with spaces!",
    });
  });

  // 5) Non-existent slug should cause an error (not found)
  const nonExistentSlug = `${slugBase}-nonexistent-${RandomGenerator.alphaNumeric(4)}`;
  await TestValidator.error("non-existent slug should error", async () => {
    await api.functional.discussionBoard.categories.at(unauthConn, {
      categorySlug: nonExistentSlug,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

export async function test_api_member_sessions_list_by_member(
  connection: api.IConnection,
) {
  /**
   * 1. Register a fresh member using POST /auth/member/join to obtain an
   *    authenticated context. The SDK implementation will place the returned
   *    access token onto connection.headers.Authorization for subsequent
   *    calls.
   */
  const joinBody = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: "P@ssw0rd0123", // >=12 chars, mixed categories
    href: "https://example.com/test",
    referrer: "https://example.com/",
  } satisfies IDiscussionBoardMember.IJoin;

  const authorized: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, { body: joinBody });
  typia.assert(authorized);

  // 2) Call the sessions listing endpoint using the same connection (authenticated)
  const sessionsPage: IDiscussionBoardMember.ISessionsPage =
    await api.functional.auth.member.sessions.listSessions(connection);
  typia.assert(sessionsPage);

  // 3) Validate pagination metadata is present and consistent
  TestValidator.predicate(
    "sessions pagination present",
    sessionsPage.pagination !== null &&
      typeof sessionsPage.pagination.current === "number",
  );

  const { current, limit, records, pages } = sessionsPage.pagination;
  const expectedPages = limit === 0 ? 0 : Math.ceil(records / limit);
  TestValidator.equals("pagination pages consistent", pages, expectedPages);

  // 4) Validate business rules on session items
  // If system issued a session on join, ensure at least one session belongs to the member
  if (sessionsPage.data.length > 0) {
    TestValidator.predicate(
      "at least one session belongs to authenticated member",
      sessionsPage.data.some((s) => s.memberId === authorized.id),
    );
  } else {
    TestValidator.predicate(
      "no sessions returned but shape valid",
      sessionsPage.data.length === 0,
    );
  }

  // 5) Ensure no sensitive token or password fields are leaked in session items
  for (const s of sessionsPage.data) {
    TestValidator.predicate(
      "session items do not expose access/refresh/password values",
      !Object.prototype.hasOwnProperty.call(s as object, "access") &&
        !Object.prototype.hasOwnProperty.call(s as object, "refresh") &&
        !Object.prototype.hasOwnProperty.call(s as object, "password") &&
        !Object.prototype.hasOwnProperty.call(s as object, "password_hash"),
    );
  }

  // 6) Failure cases
  // 6a) No token (unauthenticated) should produce an error (expected 401)
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "unauthenticated requests should fail",
    async () => {
      await api.functional.auth.member.sessions.listSessions(unauthConn);
    },
  );

  // 6b) Malformed token should produce an error (expected 401)
  const malformedConn: api.IConnection = {
    ...connection,
    headers: { Authorization: "malformed.token" },
  };
  await TestValidator.error("malformed token should fail", async () => {
    await api.functional.auth.member.sessions.listSessions(malformedConn);
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

export async function test_api_member_sessions_revoke_by_owner(
  connection: api.IConnection,
) {
  // 1) Create owner member context using a dedicated connection so SDK stores token there
  const ownerConn: api.IConnection = { ...connection, headers: {} };
  const ownerJoinBody = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: `${RandomGenerator.alphaNumeric(9)}A!1`,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.IJoin;

  const ownerAuth: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(ownerConn, {
      body: ownerJoinBody,
    });
  typia.assert(ownerAuth);

  // 2) Retrieve sessions for owner and ensure at least one session exists
  const sessionsPage: IDiscussionBoardMember.ISessionsPage =
    await api.functional.auth.member.sessions.listSessions(ownerConn);
  typia.assert(sessionsPage);
  TestValidator.predicate(
    "owner has at least one session after join",
    sessionsPage.data.length >= 1,
  );

  const targetSessionId: string = sessionsPage.data[0].id;

  // 3) Create a second member (other) on a separate connection to test unauthorized revoke
  const otherConn: api.IConnection = { ...connection, headers: {} };
  const otherJoinBody = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: `${RandomGenerator.alphaNumeric(9)}B@2`,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.IJoin;

  const otherAuth: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(otherConn, { body: otherJoinBody });
  typia.assert(otherAuth);

  // 4) Attempt to revoke the owner's session using the other member (should fail)
  await TestValidator.error(
    "other member cannot revoke another member's session",
    async () => {
      await api.functional.auth.member.sessions.eraseSession(otherConn, {
        sessionId: targetSessionId,
      });
    },
  );

  // 5) Revoke the session as the owner (should succeed)
  await api.functional.auth.member.sessions.eraseSession(ownerConn, {
    sessionId: targetSessionId,
  });

  // 6) Verify the revoked session no longer appears in the owner's session listing
  const sessionsAfter: IDiscussionBoardMember.ISessionsPage =
    await api.functional.auth.member.sessions.listSessions(ownerConn);
  typia.assert(sessionsAfter);
  TestValidator.predicate(
    "revoked session absent from owner's session list",
    sessionsAfter.data.find((s) => s.id === targetSessionId) === undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

export async function test_api_tag_public_retrieval_by_slug(
  connection: api.IConnection,
) {
  /**
   * 1. Create a fresh moderator account (self-join) to obtain moderator
   *    credentials.
   * 2. Using the moderator credentials, create a new tag via moderator-only
   *    endpoint.
   * 3. Use an unauthenticated connection to GET the tag by slug and validate
   *    public fields.
   */

  // 1. Moderator self-join (creates credentials and populates connection.headers)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorUsername = RandomGenerator.name(1)
    .replace(/\s+/g, "-")
    .toLowerCase();
  const moderatorPassword = RandomGenerator.alphaNumeric(12); // >= 12 chars
  const href = typia.random<string & tags.Format<"uri">>();
  const referrer = typia.random<string & tags.Format<"uri">>();

  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        username: moderatorUsername,
        email: moderatorEmail,
        password: moderatorPassword,
        href: href,
        referrer: referrer,
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // 2. Create a new tag as moderator
  const createdName =
    `Integration Test Tag ${RandomGenerator.paragraph({ sentences: 3, wordMin: 3, wordMax: 8 })}`.slice(
      0,
      100,
    );
  const slugSuffix = RandomGenerator.alphabets(6); // lowercase letters
  const createdSlug = `integration-test-${slugSuffix}`; // matches ^[a-z0-9]+(?:[-_][a-z0-9]+)*$
  const createdDescription = "Tag created by E2E test";

  const createdTag: IDiscussionBoardTag =
    await api.functional.discussionBoard.moderator.tags.create(connection, {
      body: {
        name: createdName,
        slug: createdSlug,
        description: createdDescription,
        is_active: true,
      } satisfies IDiscussionBoardTag.ICreate,
    });
  typia.assert(createdTag);

  // Verify created tag returned slug matches our requested slug
  TestValidator.equals(
    "created tag slug matches requested slug",
    createdTag.slug,
    createdSlug,
  );
  TestValidator.equals(
    "created tag name matches requested name",
    createdTag.name,
    createdName,
  );

  // 3. Public retrieval using unauthenticated connection
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  const readTag: IDiscussionBoardTag =
    await api.functional.discussionBoard.tags.at(unauthConn, {
      tagSlug: createdSlug,
    });
  typia.assert(readTag);

  // Business logic validations
  TestValidator.equals(
    "public tag name equals created name",
    readTag.name,
    createdName,
  );
  TestValidator.equals(
    "public tag slug equals requested slug",
    readTag.slug,
    createdSlug,
  );
  TestValidator.equals("public tag is active", readTag.is_active, true);

  // created_at and updated_at must exist and be date-time strings (typia.assert already validated formats)
  TestValidator.predicate(
    "public tag has created_at",
    readTag.created_at !== null && readTag.created_at !== undefined,
  );
  TestValidator.predicate(
    "public tag has updated_at",
    readTag.updated_at !== null && readTag.updated_at !== undefined,
  );

  // deleted_at must be null or undefined for active public records
  TestValidator.predicate(
    "public tag deleted_at is null or undefined",
    readTag.deleted_at === null || readTag.deleted_at === undefined,
  );

  // Slug normalization: ensure returned slug is lower-case (our slug was lower-case)
  TestValidator.equals(
    "returned slug is normalized to lower-case",
    readTag.slug,
    createdSlug.toLowerCase(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

/**
 * Validate that public retrieval of discussion board tags by slug returns no
 * resource when the tag does not exist or is not publicly visible.
 *
 * Business context:
 *
 * - Public consumers should only receive tags that are active and not
 *   soft-deleted. Attempting to fetch a missing/inactive tag must fail for
 *   public callers and must not return a tag payload or internal fields.
 *
 * Test steps:
 *
 * 1. Choose two slug variants (lower-case and mixed-case) that conform to slug
 *    format but do not exist in the system.
 * 2. Call the public endpoint as an unauthenticated request and assert that the
 *    request results in a runtime error (no successful tag payload).
 * 3. Do not inspect HTTP status codes or error message internals; rely on
 *    TestValidator.error to assert failure behavior.
 */
export async function test_api_tag_public_retrieval_not_found(
  connection: api.IConnection,
) {
  // Choose slugs that follow slug patterns but are not created in the system
  const lowerCaseSlug = "nonexistent-test-tag-xyz";
  const mixedCaseSlug = "Nonexistent-Test-Tag-XYZ";

  // Lower-case retrieval should fail (resource missing or not public)
  await TestValidator.error(
    "retrieving non-existent tag by lower-case slug should fail",
    async () => {
      await api.functional.discussionBoard.tags.at(connection, {
        tagSlug: lowerCaseSlug,
      });
    },
  );

  // Mixed-case retrieval (edge normalization case) should also fail
  await TestValidator.error(
    "retrieving non-existent tag by mixed-case slug should fail",
    async () => {
      await api.functional.discussionBoard.tags.at(connection, {
        tagSlug: mixedCaseSlug,
      });
    },
  );

  // Note: We intentionally do not assert HTTP status codes or inspect
  // error internals in order to comply with test guidelines. The fact that
  // the call throws indicates the resource is not publicly retrievable.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

export async function test_api_tag_create_by_moderator(
  connection: api.IConnection,
) {
  /**
   * Purpose:
   *
   * 1. Register a fresh moderator account to obtain authorization tokens.
   * 2. Create a new discussion board tag as that moderator.
   * 3. Validate the returned tag resource for business correctness.
   *
   * Key DTOs used:
   *
   * - IDiscussionBoardModerator.ICreate (request for moderator join)
   * - IDiscussionBoardModerator.IAuthorized (join response)
   * - IDiscussionBoardTag.ICreate (tag creation request)
   * - IDiscussionBoardTag (tag response)
   */

  // 1) Prepare and perform moderator registration (self-join)
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorUsername: string = RandomGenerator.alphabets(8);
  const moderatorPassword: string = `Aa1!${RandomGenerator.alphaNumeric(8)}`; // >=12 chars, contains uppercase, lowercase, digit, symbol
  const moderatorHref: string = typia.random<string & tags.Format<"uri">>();
  const moderatorReferrer: string = typia.random<string & tags.Format<"uri">>();

  const joinBody = {
    username: moderatorUsername,
    email: moderatorEmail,
    password: moderatorPassword,
    display_name: RandomGenerator.name(),
    href: moderatorHref,
    referrer: moderatorReferrer,
  } satisfies IDiscussionBoardModerator.ICreate;

  const authorized: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: joinBody,
    });
  // Runtime schema validation
  typia.assert(authorized);

  // At this point the SDK stores the access token on the connection internally.

  // 2) Create a new tag using moderator context
  const tagName = `E2E Moderator Tag ${RandomGenerator.paragraph({ sentences: 3 })}`;
  const slug =
    `e2e-moderator-tag-${RandomGenerator.alphabets(5)}`.toLowerCase();
  const description = RandomGenerator.content({ paragraphs: 1 });

  const tagCreateBody = {
    name: tagName.slice(0, 100), // ensure <=100 chars
    slug: slug.slice(0, 100),
    description,
    is_active: true,
  } satisfies IDiscussionBoardTag.ICreate;

  const created: IDiscussionBoardTag =
    await api.functional.discussionBoard.moderator.tags.create(connection, {
      body: tagCreateBody,
    });
  typia.assert(created);

  // 3) Business assertions
  TestValidator.equals(
    "created tag name matches request",
    created.name,
    tagCreateBody.name,
  );
  TestValidator.equals(
    "created tag slug matches request",
    created.slug,
    tagCreateBody.slug,
  );
  TestValidator.predicate("created tag is active", created.is_active === true);

  // Timestamps should be present (typia.assert already validated types), but assert non-empty as business check
  TestValidator.predicate(
    "created_at is set",
    created.created_at !== null &&
      created.created_at !== undefined &&
      created.created_at.length > 0,
  );
  TestValidator.predicate(
    "updated_at is set",
    created.updated_at !== null &&
      created.updated_at !== undefined &&
      created.updated_at.length > 0,
  );

  // Soft-delete must be null for newly created tags
  TestValidator.equals(
    "deleted_at is null for newly created tag",
    created.deleted_at,
    null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

export async function test_api_moderator_refresh_token_rotation(
  connection: api.IConnection,
) {
  // 1) Create a new moderator (join) to obtain initial tokens
  const joinBody = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    href: "https://example.com/welcome",
    referrer: "https://example.com/landing",
  } satisfies IDiscussionBoardModerator.ICreate;

  const created: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, { body: joinBody });
  typia.assert(created);

  const originalRefresh: string = created.token.refresh;
  const originalAccess: string = created.token.access;
  const moderatorId: string = created.id;

  // 2) Successful refresh with the captured refresh token
  const refreshRequest = {
    type: "refresh_token",
    refresh_token: originalRefresh,
  } satisfies IDiscussionBoardModerator.IRefresh;

  const refreshed: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.refresh(connection, {
      body: refreshRequest,
    });
  typia.assert(refreshed);

  // Validate moderator id consistency
  TestValidator.equals(
    "moderator id should remain the same after refresh",
    refreshed.id,
    moderatorId,
  );

  // Validate that a new access token was issued (business-level check)
  TestValidator.predicate(
    "access token should be renewed or at least present",
    refreshed.token.access !== undefined && refreshed.token.access.length > 0,
  );

  // 3) Rotation / replay check
  // If the server rotated the refresh token, the new refresh value will differ.
  if (refreshed.token.refresh !== originalRefresh) {
    // Rotation detected — old refresh token must be rejected
    await TestValidator.error(
      "rotated (old) refresh token must be rejected",
      async () => {
        await api.functional.auth.moderator.refresh(connection, {
          body: {
            type: "refresh_token",
            refresh_token: originalRefresh,
          } satisfies IDiscussionBoardModerator.IRefresh,
        });
      },
    );

    // Also assert that the new refresh token is usable for another refresh
    const secondRefreshAttempt = await api.functional.auth.moderator.refresh(
      connection,
      {
        body: {
          type: "refresh_token",
          refresh_token: refreshed.token.refresh,
        } satisfies IDiscussionBoardModerator.IRefresh,
      },
    );
    typia.assert(secondRefreshAttempt);
    TestValidator.equals(
      "second refresh produced same moderator id",
      secondRefreshAttempt.id,
      moderatorId,
    );
  } else {
    // Rotation not enabled on server — document as a predicate check so test
    // remains meaningful without failing due to server policy differences.
    TestValidator.predicate(
      "refresh token was not rotated by server (rotation disabled)",
      refreshed.token.refresh === originalRefresh,
    );
  }

  // 4) Invalid / malformed refresh token should be rejected (business error)
  await TestValidator.error("invalid refresh token should fail", async () => {
    await api.functional.auth.moderator.refresh(connection, {
      body: {
        type: "refresh_token",
        refresh_token: "this-is-an-invalid-or-expired-token",
      } satisfies IDiscussionBoardModerator.IRefresh,
    });
  });

  // 5) Soft-deleted moderator case: Not implementable with provided SDK alone.
  // The scenario requires marking the moderator record as soft-deleted in the
  // database before attempting refresh. Because the provided SDK does not
  // expose a moderator delete endpoint or direct DB access, we cannot perform
  // an authentic soft-delete within this test. We intentionally skip this
  // step while documenting the rationale to maintain test reliability.
  TestValidator.predicate(
    "soft-delete refresh test skipped due to no delete API in provided SDK",
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

export async function test_api_moderator_change_password_revokes_sessions(
  connection: api.IConnection,
) {
  // 1) Create a moderator via join with a policy-compliant password
  // Build a 12+ character password that includes uppercase, lowercase, digit and symbol.
  const passwordSeed = RandomGenerator.alphaNumeric(8); // letters+digits
  const originalPassword = `${passwordSeed}A1!a`; // guarantees at least 12 chars and mixed classes

  const joinBody = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: originalPassword,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardModerator.ICreate;

  const auth = await api.functional.auth.moderator.join(connection, {
    body: joinBody,
  });
  typia.assert(auth);

  // Capture token (join sets connection.headers.Authorization internally)
  const token: IAuthorizationToken = auth.token;
  typia.assert(token);

  // 2) Change password: authenticated call using join-issued authorization
  const newPassword = `${RandomGenerator.alphaNumeric(8)}B2@b`; // ensures mixed classes and >=12 chars
  const changeBody = {
    currentPassword: originalPassword,
    newPassword,
  } satisfies IDiscussionBoardModerator.IChangePassword;

  const updated: IDiscussionBoardModerator =
    await api.functional.auth.moderator.password.change.changePassword(
      connection,
      { body: changeBody },
    );
  typia.assert(updated);

  // If join returned moderator summary, updated.updated_at must differ from prior value
  if (auth.moderator) {
    TestValidator.notEquals(
      "updated_at should change after password update",
      auth.moderator.updated_at,
      updated.updated_at,
    );
  }

  // 3) Post-change: verify that attempts using the old plain-text password fail.
  // NOTE: The SDK provided does not include a token refresh endpoint; therefore
  // direct refresh-token revocation testing is not possible here. Instead, we
  // validate that the old credential no longer works for authenticated
  // operations (business-level verification of password change).
  await TestValidator.error(
    "old password must be rejected after password change",
    async () => {
      await api.functional.auth.moderator.password.change.changePassword(
        connection,
        {
          body: {
            currentPassword: originalPassword,
            newPassword: `${RandomGenerator.alphaNumeric(8)}C3#c`,
          } satisfies IDiscussionBoardModerator.IChangePassword,
        },
      );
    },
  );

  // 4) Negative case: wrong current password should fail (valid DTO, business-rule error)
  await TestValidator.error("wrong current password should fail", async () => {
    await api.functional.auth.moderator.password.change.changePassword(
      connection,
      {
        body: {
          currentPassword: (originalPassword + "x").slice(0, 12), // still type-valid but incorrect
          newPassword: `${RandomGenerator.alphaNumeric(8)}D4$d`,
        } satisfies IDiscussionBoardModerator.IChangePassword,
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

export async function test_api_member_change_password_success(
  connection: api.IConnection,
) {
  // 1) Prepare unique member registration data
  const username = RandomGenerator.alphaNumeric(8); // allowed chars: letters/digits
  const email = typia.random<string & tags.Format<"email">>();
  const href = typia.random<string & tags.Format<"uri">>();
  const referrer = typia.random<string & tags.Format<"uri">>();

  // Build an old (initial) password that meets the policy: >=12 chars and
  // at least three character categories (upper, lower, digit, symbol).
  const oldPassword = `${RandomGenerator.alphaNumeric(6)}A!${RandomGenerator.alphaNumeric(6)}`; // includes uppercase 'A' and symbol '!'

  const joinBody = {
    username,
    email,
    password: oldPassword,
    href,
    referrer,
  } satisfies IDiscussionBoardMember.IJoin;

  // 2) Register the member and obtain authorized response + tokens
  const authorized: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: joinBody,
    });
  typia.assert(authorized);
  TestValidator.equals(
    "joined member username matches request",
    authorized.username,
    username,
  );

  // 3) Prepare a new password that deterministically satisfies policy and is different
  const newPassword = `B@${RandomGenerator.alphaNumeric(10)}c1`; // length >= 13, contains uppercase, symbol, digits and lowercase

  // 4) Change password from oldPassword -> newPassword
  await api.functional.auth.member.password.change.changePassword(connection, {
    body: {
      currentPassword: oldPassword,
      newPassword: newPassword,
      revokeSessions: true,
    } satisfies IDiscussionBoardMember.IChangePassword,
  });

  // 5) Business validation: using the old password must fail now
  await TestValidator.error(
    "old password should be rejected after change",
    async () => {
      await api.functional.auth.member.password.change.changePassword(
        connection,
        {
          body: {
            currentPassword: oldPassword,
            newPassword: `${RandomGenerator.alphaNumeric(12)}Z!`,
          } satisfies IDiscussionBoardMember.IChangePassword,
        },
      );
    },
  );

  // 6) Confirm the new password is valid by performing another change using it
  const anotherPassword = `C#${RandomGenerator.alphaNumeric(10)}d2`;
  await api.functional.auth.member.password.change.changePassword(connection, {
    body: {
      currentPassword: newPassword,
      newPassword: anotherPassword,
      revokeSessions: false,
    } satisfies IDiscussionBoardMember.IChangePassword,
  });

  // If we reached here, password-change operations behaved as expected.
  TestValidator.predicate("password change workflow completed", true);
}

