import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardNotificationFailure } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationFailure";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

export async function test_api_notification_failure_retrieval_by_owner_success(
  connection: api.IConnection,
) {
  // 1) Register a new member and obtain authenticated context
  const joinBody = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: "StrongPassw0rd!", // >=12 chars and mixed categories
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://example.com/initial",
    referrer: "https://example.com/ref",
  } satisfies IDiscussionBoardMember.IJoin;

  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: joinBody,
    });
  typia.assert(member);

  // 2) Create an article while authenticated (establishes content context)
  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 5, wordMin: 5, wordMax: 10 }),
    content: RandomGenerator.content({ paragraphs: 2 }),
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: articleBody,
    });
  typia.assert(article);

  // 3) Prepare notificationId and attemptNumber for retrieval
  // NOTE: Notification creation is out of scope for available SDK functions.
  // The test assumes the environment has a fixture or background process
  // that created a notification failure record for this combination.
  const notificationId = typia.random<string & tags.Format<"uuid">>();
  const attemptNumber = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<1>
  >();

  // 4) Retrieve the failure as the member (owner)
  const failure: IDiscussionBoardNotificationFailure =
    await api.functional.discussionBoard.member.members.notifications.failures.at(
      connection,
      {
        memberUsername: member.username,
        notificationId,
        attemptNumber,
      },
    );
  typia.assert(failure);

  // Business assertions
  TestValidator.equals(
    "notification id matches requested id",
    failure.notificationId,
    notificationId,
  );
  TestValidator.equals(
    "attempt number matches requested attempt",
    failure.attemptNumber,
    attemptNumber,
  );

  // typia.assert already validates date-time formats; perform business-level checks
  TestValidator.predicate(
    "attemptedAt is present",
    typeof failure.attemptedAt === "string" && failure.attemptedAt.length > 0,
  );

  // errorCode is optional per DTO; prefer known tokens when present
  const known = ["SMTP_TIMEOUT", "BOUNCED"] as const;
  TestValidator.predicate(
    "errorCode is null or a known token",
    failure.errorCode === null ||
      failure.errorCode === undefined ||
      (typeof failure.errorCode === "string" &&
        known.includes(failure.errorCode as any)),
  );

  // errorMessage should be non-empty when present
  TestValidator.predicate(
    "errorMessage is non-empty when present",
    failure.errorMessage === null ||
      failure.errorMessage === undefined ||
      (typeof failure.errorMessage === "string" &&
        failure.errorMessage.length > 0),
  );

  // backoffUntil is nullable; typia.assert will have validated format if present
  TestValidator.predicate(
    "backoffUntil is null or ISO date string when present",
    failure.backoffUntil === null ||
      failure.backoffUntil === undefined ||
      (typeof failure.backoffUntil === "string" &&
        failure.backoffUntil.length > 0),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardNotificationFailure } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationFailure";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

export async function test_api_notification_failure_retrieval_not_found(
  connection: api.IConnection,
) {
  /**
   * Validate that requesting a non-existent notification failure attempt for an
   * authenticated member results in an error (expected 404 behavior).
   *
   * Steps:
   *
   * 1. Register a new member via POST /auth/member/join (IAttempt to get auth)
   * 2. Optionally create an article to provide contextual resources
   * 3. Attempt to retrieve a delivery failure record that does NOT exist
   * 4. Assert that the retrieval call throws (TestValidator.error)
   */

  // 1) Member registration (join)
  const joinBody = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: "StrongPassw0rd!", // >= 12 characters
    display_name: RandomGenerator.name(),
    href: "https://example.com/home",
    referrer: "https://example.com/",
  } satisfies IDiscussionBoardMember.IJoin;

  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, { body: joinBody });
  typia.assert(member);
  TestValidator.predicate("member has username", member.username.length > 0);

  // 2) Optional: create an article to provide context (not required for the 404 behavior)
  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 5, wordMin: 5, wordMax: 10 }),
    content: RandomGenerator.content({ paragraphs: 2 }),
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: articleBody,
    });
  typia.assert(article);

  // 3) Attempt to retrieve a non-existent failure record
  const randomNotificationId = typia.random<string & tags.Format<"uuid">>();
  const randomAttemptNumber = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<1>
  >();

  await TestValidator.error(
    "retrieving non-existent notification failure should error",
    async () => {
      await api.functional.discussionBoard.member.members.notifications.failures.at(
        connection,
        {
          memberUsername: member.username,
          notificationId: randomNotificationId,
          attemptNumber: randomAttemptNumber,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

export async function test_api_moderator_remove_soft_delete_account(
  connection: api.IConnection,
) {
  /**
   * Test: soft-delete (erase) moderator account by username.
   *
   * Steps:
   *
   * 1. Create a new moderator via POST /auth/moderator/join using
   *    IDiscussionBoardModerator.ICreate.
   * 2. Assert the join response (IAuthorized) and record username.
   * 3. Call DELETE /discussionBoard/moderator/moderators/:moderatorUsername to
   *    soft-delete the account (erase).
   * 4. Attempt the same erase again and assert it fails (error thrown), which
   *    demonstrates that the account is no longer active (soft-deleted) and
   *    further privileged operations are rejected.
   */

  // 1) Prepare a unique moderator creation request
  const username = `mod_${RandomGenerator.alphaNumeric(8)}`;
  const createBody = {
    username,
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardModerator.ICreate;

  // 2) Create moderator and obtain authorization tokens
  const authorized: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: createBody,
    });
  typia.assert(authorized);

  // Business-level validation: username in response matches requested username
  TestValidator.equals(
    "created moderator username matches",
    authorized.username,
    createBody.username,
  );

  // 3) Soft-delete (erase) the moderator by username
  await api.functional.discussionBoard.moderator.moderators.erase(connection, {
    moderatorUsername: authorized.username,
  });

  // 4) Post-condition: trying to erase again should fail (account already removed)
  await TestValidator.error(
    "erasing already removed moderator should fail",
    async () => {
      await api.functional.discussionBoard.moderator.moderators.erase(
        connection,
        {
          moderatorUsername: authorized.username,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";

export async function test_api_guest_public_retrieval(
  connection: api.IConnection,
) {
  // 1) Prepare a guest creation request
  const displayName = RandomGenerator.name();
  const ip = "127.0.0.1"; // realistic IPv4 for test
  const requestBody = {
    displayName,
    ip,
    href: "https://example.com/current-page",
    referrer: "https://example.com/previous-page",
  } satisfies IDiscussionBoardGuest.ICreate;

  // 2) Create a transient guest account (join)
  const created: IDiscussionBoardGuest.IAuthorized =
    await api.functional.auth.guest.join(connection, {
      body: requestBody,
    });
  typia.assert(created);

  // Basic sanity checks on the authorized response
  TestValidator.predicate(
    "join returned id",
    created.id !== undefined && created.id !== null,
  );
  TestValidator.equals(
    "join returned same displayName",
    created.displayName ?? null,
    displayName ?? null,
  );

  // 3) Public GET retrieval by guestId
  const read: IDiscussionBoardGuest =
    await api.functional.discussionBoard.guests.at(connection, {
      guestId: created.id,
    });
  typia.assert(read);

  // 4) Validate business expectations
  TestValidator.equals(
    "public retrieval: id matches created id",
    read.id,
    created.id,
  );
  TestValidator.equals(
    "public retrieval: displayName preserved",
    read.displayName ?? null,
    created.displayName ?? null,
  );

  // IP may be considered PII and redacted for public callers. If the API returns
  // the IP (not redacted), it should match the value supplied during join.
  // Use predicate to allow either null (redacted) or matching value.
  TestValidator.predicate(
    "public retrieval: ip either redacted or matches created value",
    read.ip === null ||
      read.ip === undefined ||
      read.ip === created.ip ||
      read.ip === ip,
  );

  // 5) Ensure timestamps exist. typia.assert already validates formats; assert they are present.
  TestValidator.predicate(
    "createdAt exists",
    read.createdAt !== null &&
      read.createdAt !== undefined &&
      read.createdAt.length > 0,
  );
  TestValidator.predicate(
    "updatedAt exists",
    read.updatedAt !== null &&
      read.updatedAt !== undefined &&
      read.updatedAt.length > 0,
  );

  // 6) Negative case: non-existent guest should throw an error
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  // Avoid accidental collision
  if (nonExistentId === created.id) {
    // Extremely unlikely, but regenerate if collided
    const another = typia.random<string & tags.Format<"uuid">>();
    await TestValidator.error("non-existent guest should error", async () => {
      await api.functional.discussionBoard.guests.at(connection, {
        guestId: another,
      });
    });
  } else {
    await TestValidator.error("non-existent guest should error", async () => {
      await api.functional.discussionBoard.guests.at(connection, {
        guestId: nonExistentId,
      });
    });
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

export async function test_api_member_update_profile_by_owner(
  connection: api.IConnection,
) {
  /**
   * 1. Register a fresh member to obtain an authenticated context. The SDK
   *    populates connection.headers.Authorization automatically from the
   *    returned token; tests MUST NOT manipulate headers directly.
   */
  const username = `user_${RandomGenerator.alphaNumeric(8)}`;
  const email = typia.random<string & tags.Format<"email">>();
  const initialPassword = `Aa1!${RandomGenerator.alphaNumeric(9)}`; // >=13 chars, contains upper/lower/digit/symbol
  const initialDisplayName = RandomGenerator.name();
  const href = `https://example.com/${RandomGenerator.alphaNumeric(6)}`;
  const referrer = `https://referrer.example/${RandomGenerator.alphaNumeric(6)}`;

  const authorized: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: {
        username,
        email,
        password: initialPassword,
        display_name: initialDisplayName,
        href,
        referrer,
      } satisfies IDiscussionBoardMember.IJoin,
    });
  typia.assert(authorized);

  TestValidator.equals(
    "joined member username matches request",
    authorized.username,
    username,
  );

  /** 2. Perform profile update as the owner: change display_name and password. */
  const newDisplayName = `${initialDisplayName} Updated`;
  const newPassword = `Zz9@${RandomGenerator.alphaNumeric(9)}`; // contains upper, lower, digit, symbol

  const updated: IDiscussionBoardMember =
    await api.functional.discussionBoard.members.update(connection, {
      memberUsername: username,
      body: {
        display_name: newDisplayName,
        password: newPassword,
        revokeSessions: true,
      } satisfies IDiscussionBoardMember.IUpdate,
    });
  typia.assert(updated);

  // Validate business outcomes
  TestValidator.equals(
    "updated display_name is reflected in response",
    updated.display_name,
    newDisplayName,
  );

  TestValidator.predicate(
    "response does not include password_hash",
    "password_hash" in updated === false,
  );

  TestValidator.predicate(
    "updated_at is later than created_at",
    new Date(updated.updated_at).getTime() >
      new Date(updated.created_at).getTime(),
  );

  // Note: No public GET endpoint was available in the SDK to perform an
  // unauthenticated fetch. The test uses the sanitized update response to
  // validate public-facing fields instead.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

export async function test_api_member_soft_delete_by_moderator(
  connection: api.IConnection,
) {
  // 1) Create a fresh moderator context (use a cloned connection so tokens do not collide)
  const modConn: api.IConnection = { ...connection, headers: {} };

  const moderatorBody = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: `${RandomGenerator.alphaNumeric(10)}A!`,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
    display_name: RandomGenerator.name(),
  } satisfies IDiscussionBoardModerator.ICreate;

  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(modConn, {
      body: moderatorBody,
    });
  typia.assert(moderator);
  TestValidator.predicate(
    "moderator created and authorized",
    moderator !== null && typeof moderator.username === "string",
  );

  // 2) Create a fresh member account (use a separate cloned connection)
  const memConn: api.IConnection = { ...connection, headers: {} };

  const memberUsername = RandomGenerator.alphaNumeric(10);
  const memberBody = {
    username: memberUsername,
    email: typia.random<string & tags.Format<"email">>(),
    password: `${RandomGenerator.alphaNumeric(10)}b#`,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.IJoin;

  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(memConn, {
      body: memberBody,
    });
  typia.assert(member);
  TestValidator.equals(
    "created member username matches request",
    member.username,
    memberUsername,
  );

  // 3) As moderator, call DELETE to soft-delete the member
  // modConn has Authorization header set by moderator.join
  let firstEraseSucceeded = false;
  try {
    await api.functional.discussionBoard.moderator.members.erase(modConn, {
      memberUsername: memberUsername,
    });
    firstEraseSucceeded = true;
  } catch (exp) {
    // If deletion fails unexpectedly, record for assertion below
    firstEraseSucceeded = false;
  }
  TestValidator.predicate(
    "first erase should succeed (moderator authorized)",
    firstEraseSucceeded,
  );

  // 4) Attempt a second erase to exercise idempotency/acceptable behavior
  // The API may either accept idempotent repeat (succeed) or respond with an
  // error (e.g., conflict). Both outcomes are acceptable for this test per
  // scenario guidance. We ensure the server either allows repeated erase or
  // responds with an error rather than crashing.
  let secondEraseSucceeded = false;
  let secondEraseErrored = false;
  try {
    await api.functional.discussionBoard.moderator.members.erase(modConn, {
      memberUsername: memberUsername,
    });
    secondEraseSucceeded = true;
  } catch (exp) {
    secondEraseErrored = true;
  }

  TestValidator.predicate(
    "second erase either succeeds again (idempotent) or errors gracefully",
    secondEraseSucceeded || secondEraseErrored,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleSnapshot";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticleSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticleSnapshot";

export async function test_api_article_snapshots_search_by_filters(
  connection: api.IConnection,
) {
  // 1) Create a member (author)
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.auth.member.join(connection, {
    body: {
      username: RandomGenerator.name(1).replace(/\s+/g, "_").toLowerCase(),
      email: memberEmail,
      password: "Password123!@#",
      href: "https://example.test/",
      referrer: "https://referrer.test/",
      ip: null,
    } satisfies IDiscussionBoardMember.IJoin,
  });
  typia.assert(member);

  // 2) Create an article as the member
  const initialTitle = RandomGenerator.paragraph({
    sentences: 4,
    wordMin: 3,
    wordMax: 8,
  });
  const initialContent = RandomGenerator.content({
    paragraphs: 2,
    sentenceMin: 8,
    sentenceMax: 12,
  });

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: {
        title: initialTitle,
        content: initialContent,
        category_slug: null,
        tag_slugs: [],
        state: "published",
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(article);

  // 3) Perform multiple updates to generate snapshots
  const updates: IDiscussionBoardArticle[] = [];
  for (let i = 0; i < 3; ++i) {
    const updatedTitle = `${initialTitle} - edit ${i + 1} ${RandomGenerator.name(1)}`;
    const updatedContent = `${initialContent}\n\n${RandomGenerator.paragraph({ sentences: 6 })}`;
    const updated: IDiscussionBoardArticle =
      await api.functional.discussionBoard.member.articles.update(connection, {
        articleId: article.id,
        body: {
          title: updatedTitle,
          content: updatedContent,
        } satisfies IDiscussionBoardArticle.IUpdate,
      });
    typia.assert(updated);
    updates.push(updated);
  }

  // 4) Switch to moderator: create moderator account which sets Authorization
  const modEmail: string = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      username: `mod_${RandomGenerator.alphaNumeric(6)}`,
      email: modEmail,
      password: "ModeratorPass123!",
      href: "https://moderator.example.test/",
      referrer: "https://moderator.referrer.test/",
      ip: null,
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // 5) As moderator, call snapshot search with multiple filters and pagination
  const searchSubstring = initialTitle.split(/\s+/).slice(0, 2).join(" ");
  const searchBody = {
    page: 1,
    limit: 10,
    sort: "-snapshot_at",
    article_id: article.id,
    author_username: member.username,
    search: searchSubstring,
    include_counts: true,
  } satisfies IDiscussionBoardArticleSnapshot.IRequest;

  const page: IPageIDiscussionBoardArticleSnapshot.ISummary =
    await api.functional.discussionBoard.moderator.articles.versions.index(
      connection,
      {
        body: searchBody,
      },
    );
  typia.assert(page);

  // 6) Validations
  TestValidator.predicate(
    "pagination present",
    page.pagination !== undefined && page.data !== undefined,
  );
  TestValidator.equals(
    "pagination current is requested page",
    page.pagination.current,
    1,
  );
  TestValidator.equals(
    "pagination limit matches request",
    page.pagination.limit,
    10,
  );

  // If data returned, ensure scoping and sorting
  if (page.data.length > 0) {
    // Every returned snapshot should reference the requested article id
    for (const snap of page.data) {
      typia.assert(snap);
      TestValidator.equals(
        "snapshot article id matches filter",
        snap.article.id,
        article.id,
      );
    }

    // Free-text search: when data exists, at least one item should include the substring
    const foundBySearch = page.data.some((s) => {
      const titleHas =
        s.title &&
        s.title.toLowerCase().includes(searchSubstring.toLowerCase());
      const excerptHas =
        !!s.content_excerpt &&
        s.content_excerpt.toLowerCase().includes(searchSubstring.toLowerCase());
      return titleHas || excerptHas;
    });
    TestValidator.predicate(
      "free-text search returns relevant snapshots when data present",
      foundBySearch === true,
    );

    // Sorting by snapshot_at desc: if at least two items, check order
    if (page.data.length >= 2) {
      const a = page.data[0].snapshot_at;
      const b = page.data[1].snapshot_at;
      // ISO 8601 strings are comparable lexicographically when in the same format
      TestValidator.predicate(
        "snapshot_at is desc between first two items",
        a >= b,
      );
    }
  }

  // 7) Edge cases
  // 7.1 Malformed UUID should cause an error
  await TestValidator.error("malformed article_id produces error", async () => {
    await api.functional.discussionBoard.moderator.articles.versions.index(
      connection,
      {
