import type { IPageIDiscussionBoardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAuditLog";

export async function test_api_audit_logs_search_by_moderator(
  connection: api.IConnection,
) {
  // 1) Member registration (creates member token on connection)
  const memberJoinBody = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: "P@ssw0rd1234", // 12 chars, meets complexity
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.IJoin;

  const memberAuth: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuth);

  // Save a snapshot of the current (member-authenticated) connection for later negative tests
  const memberConn: api.IConnection = {
    ...connection,
    headers: { ...(connection.headers ?? {}) },
  };

  // 2) Create an article as the member
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 6, wordMin: 4, wordMax: 10 }),
    content: RandomGenerator.content({
      paragraphs: 1,
      sentenceMin: 10,
      sentenceMax: 20,
      wordMin: 4,
      wordMax: 8,
    }),
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: articleCreateBody,
    });
  typia.assert(article);

  // 3) Create a comment under the article
  const commentCreateBody = {
    content: RandomGenerator.paragraph({
      sentences: 3,
      wordMin: 3,
      wordMax: 7,
    }),
  } satisfies IDiscussionBoardComment.ICreate;

  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.member.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: commentCreateBody,
      },
    );
  typia.assert(comment);

  // 4) Upload an attachment (metadata) for the article
  const attachmentCreateBody = {
    original_filename: "test-file.txt",
    storage_key: typia.random<string & tags.Format<"uri">>(),
    mime_type: "text/plain",
    size: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<0> & tags.Maximum<20971520>
    >(),
    is_image: false,
  } satisfies IDiscussionBoardAttachment.ICreate;

  const attachment: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.member.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: attachmentCreateBody,
      },
    );
  typia.assert(attachment);

  // 5) Create a moderator account (connection will now contain moderator token)
  const moderatorJoinBody = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: "ModP@ssw0rd12", // 12+ chars
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardModerator.ICreate;

  const moderatorAuth: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: moderatorJoinBody,
    });
  typia.assert(moderatorAuth);

  // 6) Build search request: resourceType='article', fullText from article.title, date range covering created artifacts
  const searchTerm = RandomGenerator.substring(article.title);
  const dateFrom = article.created_at;
  const dateTo = new Date(Date.now() + 60_000).toISOString(); // now + 1 minute

  const auditRequest = {
    resourceType: "article",
    fullText: searchTerm,
    dateFrom,
    dateTo,
    page: 1,
    limit: 20,
    sort: "-event_timestamp",
  } satisfies IDiscussionBoardAuditLog.IRequest;

  // 7) Moderator performs the search
  const auditPage: IPageIDiscussionBoardAuditLog.ISummary =
    await api.functional.discussionBoard.moderator.auditLogs.index(connection, {
      body: auditRequest,
    });
  typia.assert(auditPage);

  // Basic pagination checks
  TestValidator.equals(
    "pagination current is 1",
    auditPage.pagination.current,
    1,
  );
  TestValidator.equals(
    "pagination limit is 20",
    auditPage.pagination.limit,
    20,
  );

  // Validate that at least one audit summary references the created resources
  TestValidator.predicate(
    "audit results reference created resources",
    auditPage.data.some(
      (d) =>
        d.resource_id === article.id ||
        d.resource_id === comment.id ||
        d.resource_id === attachment.id,
    ),
  );

  // Validate event timestamps are within the requested inclusive range
  TestValidator.predicate(
    "all event timestamps within requested range",
    auditPage.data.every((d) => {
      const ts = Date.parse(d.event_timestamp);
      return ts >= Date.parse(dateFrom) && ts <= Date.parse(dateTo);
    }),
  );

  // 8) Access control negative tests
  // 8a) Member (non-moderator) should NOT be able to query moderator audit logs
  await TestValidator.error(
    "member cannot access moderator audit logs",
    async () => {
      await api.functional.discussionBoard.moderator.auditLogs.index(
        memberConn,
        {
          body: auditRequest,
        },
      );
    },
  );

  // 8b) Unauthenticated connection should NOT be able to query moderator audit logs
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "unauthenticated cannot access moderator audit logs",
    async () => {
      await api.functional.discussionBoard.moderator.auditLogs.index(
        unauthConn,
        {
          body: auditRequest,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerator";

export async function test_api_moderator_search_pagination(
  connection: api.IConnection,
) {
  /** 1. Seed two moderator accounts and keep their creation inputs for later search */
  const moderatorAUsername = RandomGenerator.alphaNumeric(8);
  const moderatorADisplay = RandomGenerator.name();
  const moderatorAEmail = typia.random<string & tags.Format<"email">>();
  const moderatorAPassword = RandomGenerator.alphaNumeric(12);

  const moderatorA: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        username: moderatorAUsername,
        email: moderatorAEmail,
        password: moderatorAPassword,
        display_name: moderatorADisplay,
        href: "https://example.com/",
        referrer: "https://example.com/ref",
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderatorA);

  // Create second moderator to ensure multiple results and ordering
  const moderatorBUsername = RandomGenerator.alphaNumeric(8);
  const moderatorBDisplay = RandomGenerator.name();
  const moderatorBEmail = typia.random<string & tags.Format<"email">>();
  const moderatorBPassword = RandomGenerator.alphaNumeric(12);

  const moderatorB: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        username: moderatorBUsername,
        email: moderatorBEmail,
        password: moderatorBPassword,
        display_name: moderatorBDisplay,
        href: "https://example.com/",
        referrer: "https://example.com/ref",
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderatorB);

  /**
   * 2. Search as an authenticated moderator using partial display_name and
   *    pagination
   */
  const partial =
    moderatorADisplay.split(" ")[0] ?? moderatorADisplay.slice(0, 3);
  const searchRequest = {
    display_name: partial,
    page: 1,
    limit: 10,
    sort: "-createdAt",
  } satisfies IDiscussionBoardModerator.IRequest;

  const page: IPageIDiscussionBoardModerator.ISummary =
    await api.functional.discussionBoard.moderator.moderators.index(
      connection,
      { body: searchRequest },
    );
  typia.assert(page);

  // Validate pagination metadata
  TestValidator.predicate(
    "pagination current should be 1",
    page.pagination.current === 1,
  );
  TestValidator.equals(
    "pagination limit should match requested limit",
    page.pagination.limit,
    10,
  );

  // Validate that created moderatorA appears in the results (search partial-match)
  TestValidator.predicate(
    "search results include moderatorA by username",
    page.data.some((d) => d.username === moderatorA.username),
  );

  // If multiple items, ensure sort by created_at desc: first >= last
  if (page.data.length >= 2) {
    const first = page.data[0].created_at;
    const last = page.data[page.data.length - 1].created_at;
    TestValidator.predicate("results sorted by created_at desc", first >= last);
  }

  /** 3. Negative checks */
  // 3.a Unauthenticated (no Authorization header)
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  await TestValidator.httpError(
    "unauthenticated caller should receive 401",
    401,
    async () =>
      await api.functional.discussionBoard.moderator.moderators.index(
        unauthConn,
        {
          body: {
            page: 1,
            limit: 10,
          } satisfies IDiscussionBoardModerator.IRequest,
        },
      ),
  );

  // 3.b Unauthorized (member) should receive 403
  const memberConn: api.IConnection = { ...connection, headers: {} };
  const memberUsername = RandomGenerator.alphaNumeric(8);
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);

  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(memberConn, {
      body: {
        username: memberUsername,
        email: memberEmail,
        password: memberPassword,
        href: "https://example.com/",
        referrer: "https://example.com/ref",
      } satisfies IDiscussionBoardMember.IJoin,
    });
  typia.assert(member);

  await TestValidator.httpError(
    "non-moderator member should receive 403",
    403,
    async () =>
      await api.functional.discussionBoard.moderator.moderators.index(
        memberConn,
        {
          body: {
            page: 1,
            limit: 10,
          } satisfies IDiscussionBoardModerator.IRequest,
        },
      ),
  );

  // 3.c Best-effort rate-limit detection (non-deterministic): attempt a small burst and expect at least one failure
  try {
    await TestValidator.error(
      "rate limit burst may throw an error (best-effort)",
      async () => {
        const promises = ArrayUtil.repeat(10, () =>
          api.functional.discussionBoard.moderator.moderators.index(
            connection,
            {
              body: {
                page: 1,
                limit: 10,
              } satisfies IDiscussionBoardModerator.IRequest,
            },
          ),
        );
        await Promise.all(promises);
      },
    );
  } catch {
    // If no rate-limit behavior is observable, swallow the error to avoid failing the entire test run.
    // The test above is best-effort and non-deterministic; we do not assert on a specific HTTP status here.
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

export async function test_api_moderator_retrieve_by_username(
  connection: api.IConnection,
) {
  /**
   * Verify retrieving a single moderator by username and ensure response
   * excludes sensitive fields.
   *
   * Steps:
   *
   * 1. Create a moderator (POST /auth/moderator/join) and obtain auth token.
   * 2. Create a non-moderator member (POST /auth/member/join) using a separate
   *    connection to avoid overwriting the moderator token.
   * 3. Using the moderator's token, call GET
   *    /discussionBoard/moderator/moderators/{username}.
   * 4. Validate response payload contains only safe fields and deleted_at is null
   *    for active account.
   * 5. Verify unauthenticated and non-moderator calls fail (use
   *    TestValidator.error).
   */

  // 1) Create moderator account and obtain authorization
  const moderatorUsername = `mod_${RandomGenerator.alphaNumeric(8)}`;
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = `Aa1!${RandomGenerator.alphaNumeric(8)}`; // ensures complexity, length >= 12
  const moderatorBody = {
    username: moderatorUsername,
    email: moderatorEmail,
    password: moderatorPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardModerator.ICreate;

  const moderatorAuth: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: moderatorBody,
    });
  typia.assert(moderatorAuth);

  // Keep the username for later retrieval
  const createdUsername: string = moderatorAuth.username;
  TestValidator.equals(
    "created moderator username matches",
    createdUsername,
    moderatorUsername,
  );

  // 2) Create a non-moderator member using a separate connection to preserve moderator token
  const memberConn: api.IConnection = { ...connection, headers: {} };
  const memberUsername = `user_${RandomGenerator.alphaNumeric(8)}`;
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = `Bb2@${RandomGenerator.alphaNumeric(8)}`;
  const memberBody = {
    username: memberUsername,
    email: memberEmail,
    password: memberPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.IJoin;

  const memberAuth: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(memberConn, {
      body: memberBody,
    });
  typia.assert(memberAuth);

  // 3) Retrieve moderator summary using moderator's authorization (connection retains moderator token)
  const retrieved: IDiscussionBoardModerator.ISummary =
    await api.functional.discussionBoard.moderator.moderators.at(connection, {
      moderatorUsername: createdUsername,
    });
  typia.assert(retrieved);

  // 4) Validate allowed fields exist and sensitive fields are excluded
  TestValidator.equals(
    "retrieved username equals created username",
    retrieved.username,
    createdUsername,
  );
  TestValidator.predicate(
    "retrieved has id",
    retrieved.id !== undefined && retrieved.id !== null,
  );
  TestValidator.predicate(
    "retrieved has created_at",
    retrieved.created_at !== undefined && retrieved.created_at !== null,
  );

  // Ensure no sensitive fields (like password_hash) are present in the returned object
  TestValidator.predicate(
    "response must not include password_hash",
    !Object.prototype.hasOwnProperty.call(retrieved, "password_hash"),
  );

  // Confirm deleted_at indicates active account (null or undefined means active in many implementations)
  TestValidator.predicate(
    "deleted_at is null or undefined for active account",
    retrieved.deleted_at === null || retrieved.deleted_at === undefined,
  );

  // 5) Authorization checks
  // 5.a Unauthenticated attempt - must throw (use a cloned connection with empty headers)
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "unauthenticated access should be rejected",
    async () => {
      await api.functional.discussionBoard.moderator.moderators.at(unauthConn, {
        moderatorUsername: createdUsername,
      });
    },
  );

  // 5.b Non-moderator attempt (member) - must throw
  await TestValidator.error(
    "non-moderator actor should be rejected",
    async () => {
      await api.functional.discussionBoard.moderator.moderators.at(memberConn, {
        moderatorUsername: createdUsername,
      });
    },
  );
}

