import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAppeal";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportReasonCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportReasonCategory";
import type { IDiscussionBoardReportStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportStatus";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IEDiscussionBoardAppealStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IEDiscussionBoardAppealStatus";

/**
 * Validate moderator updating an appeal: RBAC, chronology, and referential
 * integrity.
 *
 * Business scenario:
 *
 * 1. Member registers and creates an article, attachment, comment, and a report.
 * 2. Member files an appeal referencing the report (status 'pending').
 * 3. Moderator registers, creates a moderation action referencing the
 *    report/comment, and updates the appeal to a resolved status while setting
 *    resolvedAt >= created_at and linking moderationActionId.
 * 4. Validate correct update, chronological validation, and RBAC enforcement.
 */
export async function test_api_appeal_update_by_moderator(
  connection: api.IConnection,
) {
  // 1) Member signs up and authenticates (connection.headers updated by SDK)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: memberEmail,
        password: "Passw0rd!1234",
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardMember.IJoin,
    });
  typia.assert(member);

  // 2) Member creates an article
  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 6,
          wordMin: 4,
          wordMax: 8,
        }),
        content: RandomGenerator.content({
          paragraphs: 2,
          sentenceMin: 8,
          sentenceMax: 12,
          wordMin: 4,
          wordMax: 8,
        }),
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(article);

  // 3) Member uploads an attachment for the article
  const attachment: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.member.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: {
          original_filename: `${RandomGenerator.alphaNumeric(6)}.png`,
          storage_key: typia.random<string & tags.Format<"uri">>(),
          mime_type: "image/png",
          size: 1024,
          is_image: true,
        } satisfies IDiscussionBoardAttachment.ICreate,
      },
    );
  typia.assert(attachment);

  // 4) Member posts a comment on the article
  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.member.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: {
          content: RandomGenerator.paragraph({
            sentences: 3,
            wordMin: 3,
            wordMax: 7,
          }),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment);

  // 5) Member files a report referencing the comment (report will be used for appeal)
  const report: IDiscussionBoardReport =
    await api.functional.discussionBoard.member.reports.create(connection, {
      body: {
        target_type: "comment",
        target_id: comment.id,
        reason_category: "Harassment" as IDiscussionBoardReportReasonCategory,
        explanation: RandomGenerator.paragraph({
          sentences: 4,
          wordMin: 4,
          wordMax: 8,
        }),
      } satisfies IDiscussionBoardReport.ICreate,
    });
  typia.assert(report);

  // 6) Member creates an appeal referencing the report
  const appeal: IDiscussionBoardAppeal =
    await api.functional.discussionBoard.member.appeals.create(connection, {
      body: {
        report_id: report.id,
        explanation: RandomGenerator.paragraph({
          sentences: 5,
          wordMin: 4,
          wordMax: 8,
        }),
      } satisfies IDiscussionBoardAppeal.ICreate,
    });
  typia.assert(appeal);
  TestValidator.equals("appeal initially pending", appeal.status, "pending");

  // 7) Moderator signs up and authenticates (connection.headers updated by SDK)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: moderatorEmail,
        password: "Mod3rator!Pass",
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // 8) Moderator creates a moderation action referencing the report/comment
  const moderationAction: IDiscussionBoardModerationAction =
    await api.functional.discussionBoard.moderator.moderation.actions.create(
      connection,
      {
        body: {
          discussion_board_report_id: report.id,
          action_type: "warn",
          action_reason: "Reviewed by automated triage and moderator",
          action_duration_days: null,
          target_type: "comment",
          target_id: comment.id,
          effective_from: null,
        } satisfies IDiscussionBoardModerationAction.ICreate,
      },
    );
  typia.assert(moderationAction);

  // 9) Moderator updates the appeal: status -> accepted, set resolvedAt >= created_at, include moderationActionId
  const resolvedAt = new Date(
    new Date(appeal.created_at).getTime() + 1000,
  ).toISOString();
  const updated: IDiscussionBoardAppeal =
    await api.functional.discussionBoard.moderator.appeals.update(connection, {
      appealId: appeal.id,
      body: {
        status: "accepted",
        resolvedAt: resolvedAt,
        moderationActionId: moderationAction.id,
        resolutionReason: "Appeal reviewed and resolved in favor of member",
      } satisfies IDiscussionBoardAppeal.IUpdate,
    });
  typia.assert(updated);

  TestValidator.equals(
    "appeal status updated to accepted",
    updated.status,
    "accepted",
  );
  if (updated.resolved_at === null || updated.resolved_at === undefined) {
    throw new Error("resolved_at must not be null after acceptance");
  }
  TestValidator.predicate(
    "resolved_at should be after or equal to created_at",
    new Date(updated.resolved_at).getTime() >=
      new Date(appeal.created_at).getTime(),
  );
  TestValidator.equals(
    "moderation action id linked",
    updated.moderation_action_id,
    moderationAction.id,
  );

  // 10) Negative case: setting resolvedAt earlier than created_at should fail
  const earlier = new Date(
    new Date(appeal.created_at).getTime() - 60_000,
  ).toISOString();
  await TestValidator.error(
    "cannot set resolved_at earlier than created_at",
    async () => {
      await api.functional.discussionBoard.moderator.appeals.update(
        connection,
        {
          appealId: appeal.id,
          body: {
            status: "rejected",
            resolvedAt: earlier,
            moderationActionId: moderationAction.id,
          } satisfies IDiscussionBoardAppeal.IUpdate,
        },
      );
    },
  );

  // 11) RBAC: a member-scoped token must not be able to perform moderator PUT
  // Re-create a member (new token) to assert RBAC denial
  const badMemberEmail = typia.random<string & tags.Format<"email">>();
  const badMember: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: badMemberEmail,
        password: "Passw0rd!1234",
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardMember.IJoin,
    });
  typia.assert(badMember);

  await TestValidator.error(
    "member cannot update appeal (forbidden)",
    async () => {
      await api.functional.discussionBoard.moderator.appeals.update(
        connection,
        {
          appealId: appeal.id,
          body: {
            status: "rejected",
            resolvedAt: new Date().toISOString(),
          } satisfies IDiscussionBoardAppeal.IUpdate,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardSubscription } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSubscription";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

export async function test_api_subscription_unsubscribe_by_member(
  connection: api.IConnection,
) {
  /**
   * E2E: Member unsubscribe (soft-delete) workflow
   *
   * Steps:
   *
   * 1. Register member A (primary actor)
   * 2. Create an article as member A
   * 3. Create a subscription (member A -> article)
   * 4. Verify unauthenticated requests are rejected
   * 5. Verify other-member cannot unsubscribe member A's subscription
   * 6. Perform unsubscribe as owner (member A)
   * 7. Verify idempotency by deleting again
   * 8. Verify deleting a non-associated/random target errors
   * 9. Attempt to recreate subscription and accept either success or conflict
   */

  // 1) Member A registration (authenticated context will be set on the provided connection)
  const memberAUsername = RandomGenerator.alphaNumeric(8);
  const memberAEmail = typia.random<string & tags.Format<"email">>();
  const memberAPassword = RandomGenerator.alphaNumeric(12);

  const memberA: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: {
        username: memberAUsername,
        email: memberAEmail,
        password: memberAPassword,
        href: "https://example.com/entry",
        referrer: "https://referrer.example.com/",
        display_name: RandomGenerator.name(),
      } satisfies IDiscussionBoardMember.IJoin,
    });
  typia.assert(memberA);

  // 2) Create an article as member A
  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 6,
          wordMin: 5,
          wordMax: 10,
        }),
        content: RandomGenerator.content({ paragraphs: 2 }),
        // Use draft to avoid publish preconditions
        state: "draft",
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(article);

  // 3) Create subscription for memberA -> article
  const subscription: IDiscussionBoardSubscription =
    await api.functional.discussionBoard.member.members.subscriptions.create(
      connection,
      {
        memberUsername: memberA.username,
        body: {
          target_type: "article",
          target_id: article.id,
          delivery_mode: "immediate",
          active: true,
        } satisfies IDiscussionBoardSubscription.ICreate,
      },
    );
  typia.assert(subscription);

  // 4) Unauthenticated requests must be rejected (error expected)
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "unauthenticated unsubscribe should fail",
    async () => {
      await api.functional.discussionBoard.member.members.subscriptions.erase(
        unauthConn,
        {
          memberUsername: memberA.username,
          targetType: "article",
          targetId: article.id,
        },
      );
    },
  );

  // 5) Ownership: member B should NOT be able to unsubscribe member A's subscription
  const memberBConn: api.IConnection = { ...connection, headers: {} };
  const memberBUsername = RandomGenerator.alphaNumeric(8);
  const memberBEmail = typia.random<string & tags.Format<"email">>();
  const memberBPassword = RandomGenerator.alphaNumeric(12);

  const memberB: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(memberBConn, {
      body: {
        username: memberBUsername,
        email: memberBEmail,
        password: memberBPassword,
        href: "https://example.com/entry",
        referrer: "https://referrer.example.com/",
        display_name: RandomGenerator.name(),
      } satisfies IDiscussionBoardMember.IJoin,
    });
  typia.assert(memberB);

  await TestValidator.error(
    "other member cannot unsubscribe another member's subscription",
    async () => {
      await api.functional.discussionBoard.member.members.subscriptions.erase(
        memberBConn,
        {
          memberUsername: memberA.username,
          targetType: "article",
          targetId: article.id,
        },
      );
    },
  );

  // 6) Successful unsubscribe by owner (member A)
  await api.functional.discussionBoard.member.members.subscriptions.erase(
    connection,
    {
      memberUsername: memberA.username,
      targetType: "article",
      targetId: article.id,
    },
  );

  // If we reach here no exception was thrown - assert success via predicate
  TestValidator.predicate("owner unsubscribe completed without throwing", true);

  // 7) Idempotency: deleting again should succeed (no error)
  await api.functional.discussionBoard.member.members.subscriptions.erase(
    connection,
    {
      memberUsername: memberA.username,
      targetType: "article",
      targetId: article.id,
    },
  );
  TestValidator.predicate(
    "idempotent unsubscribe (second delete) completed without throwing",
    true,
  );

  // 8) Referential integrity: deleting a non-associated / random target should error
  const randomTargetId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error(
    "unsubscribing non-existent subscription should fail",
    async () => {
      await api.functional.discussionBoard.member.members.subscriptions.erase(
        connection,
        {
          memberUsername: memberA.username,
          targetType: "article",
          targetId: randomTargetId,
        },
      );
    },
  );

  // 9) Attempt to recreate subscription after deletion.
  // Server behavior may vary (201 created, 409 conflict, or return existing). Accept either.
  try {
    const recreated: IDiscussionBoardSubscription =
      await api.functional.discussionBoard.member.members.subscriptions.create(
        connection,
        {
          memberUsername: memberA.username,
          body: {
            target_type: "article",
            target_id: article.id,
            delivery_mode: "immediate",
          } satisfies IDiscussionBoardSubscription.ICreate,
        },
      );
    typia.assert(recreated);
    TestValidator.predicate(
      "recreated subscription is active",
      recreated.active === true,
    );
  } catch {
    // Creation may fail due to idempotent conflict - acceptable outcome
    TestValidator.predicate(
      "recreation resulted in conflict or idempotent response (acceptable)",
      true,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";
import type { IDiscussionBoardSubscription } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSubscription";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardNotification";

/**
 * End-to-end test for notification search and bulk management for a member.
 *
 * Business context:
 *
 * - A member creates content and subscribes to it. Background workers generate
 *   notifications for the member. The member must be able to search and bulk
 *   manage their notifications. The test validates authentication, ownership,
 *   pagination/filtering, payload-safety (no PII leak), and bulk operation side
 *   effects using available DTO fields.
 *
 * Steps:
 *
 * 1. Register a new member (join) and assert authorized response.
 * 2. Create an article as that member.
 * 3. Create a subscription on the article for that member.
 * 4. Poll the notifications index (filtered by articleId) until notifications
 *    appear.
 * 5. Assert pagination, filtering, and payload-safety rules on returned summaries.
 * 6. Verify unauthenticated calls are rejected.
 * 7. Verify other members cannot manage this member's notifications.
 * 8. Perform a bulk action (mark_as_read) via the same endpoint and re-query to
 *    confirm mutation (compare updatedAt values).
 */
export async function test_api_notification_search_and_bulk_manage_by_member(
  connection: api.IConnection,
) {
  // 1) Create primary member (join) and assert authorized response
  const memberEmail = `${RandomGenerator.name(1).replace(/\s+/g, "").toLowerCase()}@example.com`;
  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: {
        username: `u_${RandomGenerator.alphaNumeric(8)}`,
        email: memberEmail,
        // Ensure password meets length requirement
        password: "Aa1!" + RandomGenerator.alphaNumeric(9),
        href: "https://example.com/ctx",
        referrer: "https://example.com/prev",
      } satisfies IDiscussionBoardMember.IJoin,
    });
  typia.assert(member);

  // 2) Create an article as the authenticated member
  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 6,
          wordMin: 3,
          wordMax: 10,
        }),
        content: RandomGenerator.content({ paragraphs: 2 }),
        // leave category and tags undefined to avoid extra validation rules
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(article);

  // 3) Create a subscription for the member to the article
  const subscription: IDiscussionBoardSubscription =
    await api.functional.discussionBoard.member.members.subscriptions.create(
      connection,
      {
        memberUsername: member.username,
        body: {
          target_type: "article",
          target_id: article.id,
          delivery_mode: "immediate",
          active: true,
        } satisfies IDiscussionBoardSubscription.ICreate,
      },
    );
  typia.assert(subscription);

  // 4) Poll notifications index until notifications referencing the article appear
  let page: IPageIDiscussionBoardNotification.ISummary | null = null;
  const maxAttempts = 12;
  for (let attempt = 0; attempt < maxAttempts; ++attempt) {
    page =
      await api.functional.discussionBoard.member.members.notifications.index(
        connection,
        {
          memberUsername: member.username,
          body: {
            page: 1,
            limit: 20,
            articleId: article.id,
          } satisfies IDiscussionBoardNotification.IRequest,
        },
      );
    typia.assert(page);
    if (page.data.length > 0) break;

    // small delay before next attempt
    await new Promise((resolve) => setTimeout(resolve, 1000));
  }

  // Ensure we have polling result
  if (!page) throw new Error("Polling did not initialize page variable");
  typia.assert(page);
  TestValidator.predicate(
    "notifications for article should appear within polling limit",
    page.data.length > 0,
  );

  // Validate one of the returned summaries references the created article
  const related = page.data.find((d) => d.article?.id === article.id);
  TestValidator.predicate(
    "at least one notification references the article",
    related !== undefined,
  );

  // Validate pagination metadata
  TestValidator.predicate(
    "pagination current page is >= 1",
    page.pagination.current >= 1,
  );
  TestValidator.predicate(
    "pagination limit is <= 100",
    page.pagination.limit <= 100,
  );

  // Validate no raw payload leak: summaries must not expose 'payload' own property
  for (const item of page.data) {
    const hasPayload = Object.prototype.hasOwnProperty.call(
      item as unknown as object,
      "payload",
    );
    TestValidator.predicate(
      "notification summary must not include raw payload property",
      !hasPayload,
    );

    // Ownership: recipient should match the authenticated member when present
    if (item.recipient) {
      TestValidator.equals(
        "notification recipient is the member",
        item.recipient.username,
        member.username,
      );
    }
  }

  // 5) Authentication enforcement: unauthenticated requests must fail
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "unauthenticated requests must be rejected when accessing notifications",
    async () => {
      await api.functional.discussionBoard.member.members.notifications.index(
        unauthConn,
        {
          memberUsername: member.username,
          body: { page: 1 } satisfies IDiscussionBoardNotification.IRequest,
        },
      );
    },
  );

  // 6) Ownership enforcement: other member cannot list/manage this member's notifications
  const otherConn: api.IConnection = { ...connection, headers: {} };
  const otherEmail = `${RandomGenerator.name(1).replace(/\s+/g, "").toLowerCase()}@example.com`;
  const otherMember: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(otherConn, {
      body: {
        username: `u_${RandomGenerator.alphaNumeric(8)}`,
        email: otherEmail,
        password: "Aa1!" + RandomGenerator.alphaNumeric(9),
        href: "https://example.com/ctx",
        referrer: "https://example.com/prev",
      } satisfies IDiscussionBoardMember.IJoin,
    });
  typia.assert(otherMember);

  await TestValidator.error(
    "other member must not manage another member's notifications",
    async () => {
      await api.functional.discussionBoard.member.members.notifications.index(
        otherConn,
        {
          memberUsername: member.username,
          body: { page: 1 } satisfies IDiscussionBoardNotification.IRequest,
        },
      );
    },
  );

  // 7) Bulk operation: mark matched notifications as read (atomic semantics)
  //    Use the articleId filter and request a bulkAction; the DTO allows any
  //    shape for IBulkAction so we send an action descriptor.
  const preBulkPage = page; // previous results

  const bulkBody = {
    articleId: article.id,
    bulkAction: { action: "mark_as_read", apply_to_all: true },
    page: 1,
    limit: 50,
  } satisfies IDiscussionBoardNotification.IRequest;

  const postBulkPage: IPageIDiscussionBoardNotification.ISummary =
    await api.functional.discussionBoard.member.members.notifications.index(
      connection,
      {
        memberUsername: member.username,
        body: bulkBody,
      },
    );
  typia.assert(postBulkPage);

  // 8) Re-query the same filter and validate side effects: compare updated timestamps
  const recheck: IPageIDiscussionBoardNotification.ISummary =
    await api.functional.discussionBoard.member.members.notifications.index(
      connection,
      {
        memberUsername: member.username,
        body: {
          articleId: article.id,
          page: 1,
          limit: 50,
        } satisfies IDiscussionBoardNotification.IRequest,
      },
    );
  typia.assert(recheck);

  const prevTimes = preBulkPage.data.map((d) => d.updatedAt ?? d.createdAt);
  const newTimes = recheck.data.map((d) => d.updatedAt ?? d.createdAt);

  // If no items existed previously, we've already asserted existence; now ensure something changed
  TestValidator.notEquals(
    "bulk operation should mutate notifications (updatedAt differs)",
    prevTimes,
    newTimes,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportReasonCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportReasonCategory";
import type { IDiscussionBoardReportStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportStatus";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

export async function test_api_report_processing_update_by_moderator(
  connection: api.IConnection,
) {
  // 1) Create member context (member will be used to create article and file report)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberUsername = RandomGenerator.alphaNumeric(8);
  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: {
        username: memberUsername,
        email: memberEmail,
        password: "Str0ngPassw@rd12",
        display_name: RandomGenerator.name(),
        ip: null,
        href: "https://example.com/create-article",
        referrer: "https://example.com/",
      } satisfies IDiscussionBoardMember.IJoin,
    });
  typia.assert(member);

  // 2) Member creates an article to be reported
  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 6,
          wordMin: 4,
          wordMax: 10,
        }),
        content: RandomGenerator.content({ paragraphs: 2 }),
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(article);

  // 3) Member files a report against the created article
  const explanation = RandomGenerator.paragraph({ sentences: 8 });
  const report: IDiscussionBoardReport =
    await api.functional.discussionBoard.member.reports.create(connection, {
      body: {
        target_type: "article",
        target_id: article.id,
        reason_category: "Other",
        explanation,
      } satisfies IDiscussionBoardReport.ICreate,
    });
  typia.assert(report);

  // Save original report details for later comparisons
  const originalReportId = report.id;
  const originalCreatedAt = report.created_at;
  const originalReporterId = report.reporter_member_id;

  // 4) Prepare moderator context without mutating the original member connection
  const modConn: api.IConnection = { ...connection, headers: {} };
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorUsername = RandomGenerator.alphaNumeric(8);
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(modConn, {
      body: {
        username: moderatorUsername,
        email: moderatorEmail,
        password: "Adm1nStr0ngP@ss",
        display_name: RandomGenerator.name(),
        ip: null,
        href: "https://example.com/moderate",
        referrer: "https://example.com/",
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // 5) Moderator triages the report (set status -> 'triaged' and processed_at >= created_at)
  const processedAt = new Date(
    Math.max(Date.now(), new Date(originalCreatedAt).getTime()),
  ).toISOString();
  const triaged: IDiscussionBoardReport =
    await api.functional.discussionBoard.moderator.reports.update(modConn, {
      reportId: originalReportId,
      body: {
        status: "triaged",
        processed_at: processedAt,
      } satisfies IDiscussionBoardReport.IUpdate,
    });
  typia.assert(triaged);

  // Validate processed_at chronology and that reporter/explanation remain unchanged
  TestValidator.predicate(
    "processed_at is present after triage",
    triaged.processed_at !== null && triaged.processed_at !== undefined,
  );
  TestValidator.predicate(
    "processed_at is >= created_at",
    new Date(triaged.processed_at!).getTime() >=
      new Date(originalCreatedAt).getTime(),
  );
  TestValidator.equals(
    "reporter id unchanged after triage",
    triaged.reporter_member_id,
    originalReporterId,
  );
  TestValidator.equals(
    "explanation unchanged after triage",
    triaged.explanation,
    explanation,
  );

  // 6) Moderator resolves the report (set status -> 'resolved' and closed_at >= processed_at)
  const resolvedClosedAt = new Date(
    Math.max(Date.now(), new Date(triaged.processed_at!).getTime()),
  ).toISOString();
  const resolved: IDiscussionBoardReport =
    await api.functional.discussionBoard.moderator.reports.update(modConn, {
      reportId: originalReportId,
      body: {
        status: "resolved",
        closed_at: resolvedClosedAt,
      } satisfies IDiscussionBoardReport.IUpdate,
    });
  typia.assert(resolved);

  TestValidator.equals(
    "report id unchanged after resolve",
    resolved.id,
    originalReportId,
  );
  TestValidator.predicate(
    "closed_at is present after resolve",
    resolved.closed_at !== null && resolved.closed_at !== undefined,
  );
  TestValidator.predicate(
    "closed_at is >= processed_at",
    new Date(resolved.closed_at!).getTime() >=
      new Date(resolved.processed_at!).getTime(),
  );
  TestValidator.equals(
    "reporter id unchanged after resolve",
    resolved.reporter_member_id,
    originalReporterId,
  );
  TestValidator.equals(
    "explanation unchanged after resolve",
    resolved.explanation,
    explanation,
  );

  // Optional check: Ensure no sensitive reporter_session_id leaked to the default moderator response
  // (If returned, it must be a UUID or null - we assert that it is null/undefined to ensure no leakage in defaults)
  TestValidator.predicate(
    "reporter_session_id not leaked in default moderator response",
    resolved.reporter_session_id === null ||
      resolved.reporter_session_id === undefined,
  );

  // 7) NEGATIVE CASES
  // a) Member attempting moderator update -> expect 403 Forbidden
  await TestValidator.httpError(
    "member cannot perform moderator update",
    403,
    async () => {
      await api.functional.discussionBoard.moderator.reports.update(
        connection,
        {
          reportId: originalReportId,
          body: {
            status: "resolved",
            closed_at: new Date().toISOString(),
          } satisfies IDiscussionBoardReport.IUpdate,
        },
      );
    },
  );

  // b) Moderator attempts to set closed_at earlier than created_at -> expect 400 Bad Request
  await TestValidator.httpError(
    "closed_at earlier than created_at should fail",
    400,
    async () => {
      await api.functional.discussionBoard.moderator.reports.update(modConn, {
        reportId: originalReportId,
        body: {
          closed_at: new Date(
            new Date(originalCreatedAt).getTime() - 1000,
          ).toISOString(),
        } satisfies IDiscussionBoardReport.IUpdate,
      });
    },
  );

  // c) Moderator attempts to update a non-existent report -> expect 404 Not Found
  await TestValidator.httpError(
    "non-existent report should return 404",
    404,
    async () => {
      await api.functional.discussionBoard.moderator.reports.update(modConn, {
        reportId: typia.random<string & tags.Format<"uuid">>(),
        body: {
          status: "triaged",
          processed_at: new Date().toISOString(),
        } satisfies IDiscussionBoardReport.IUpdate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportReasonCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportReasonCategory";
import type { IDiscussionBoardReportStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportStatus";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardReport";

/**
 * Validate moderator search, filtering and pagination for article-targeted
 * reports.
 *
 * Business context:
 *
 * - Multiple members file reports against the same article. Moderators must be
 *   able to search, filter and paginate these reports. Sensitive session-level
 *   fields are redacted in summaries by default. This test creates reporter
 *   accounts, files reports, then exercises moderator search and validation
 *   logic including failure cases (403 for non-moderator, 400 for malformed
 *   articleId) and empty-result handling.
 *
 * Steps:
 *
 * 1. Create three reporter member accounts (separate connections).
 * 2. Create an article by the first reporter.
 * 3. Create three reports targeting that article from different reporters with
 *    distinct reason_category values.
 * 4. Create a moderator account (separate connection).
 * 5. As moderator: retrieve reports without filters and validate pagination
 *    metadata and required summary fields.
 * 6. As moderator: validate status filter, reasonCategory filter and
 *    createdFrom/createdTo (date-range) filter.
 * 7. Negative checks: non-moderator 403, malformed articleId 400, and query for
 *    article with no reports returning empty data + valid pagination.
 */
export async function test_api_article_reports_search_by_moderator(
  connection: api.IConnection,
) {
  // 1) Create three reporter members with separate connections
  const reporterCount = 3;
  const reporters: {
    conn: api.IConnection;
    authorized: IDiscussionBoardMember.IAuthorized;
  }[] = [];

  for (let i = 0; i < reporterCount; ++i) {
    const memberConn: api.IConnection = { ...connection, headers: {} };
    const username = RandomGenerator.alphaNumeric(8);
    const email = typia.random<string & tags.Format<"email">>();
    const joinBody = {
      username,
      email,
      password: "ModeratorPass123!", // >=12 chars
      href: "https://example.com/article",
      referrer: "https://example.com/ref",
    } satisfies IDiscussionBoardMember.IJoin;

    const authorized = await api.functional.auth.member.join(memberConn, {
      body: joinBody,
    });
    typia.assert(authorized);
    reporters.push({ conn: memberConn, authorized });
  }

  // 2) Create an article by the first reporter
  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(
      reporters[0].conn,
      {
        body: {
          title: RandomGenerator.paragraph({
            sentences: 6,
            wordMin: 3,
            wordMax: 8,
          }),
          content: RandomGenerator.content({ paragraphs: 2 }),
          state: "published",
        } satisfies IDiscussionBoardArticle.ICreate,
      },
    );
  typia.assert(article);

  // 3) Create multiple reports against the article from different reporters
  const reasonCategories = [
    "Spam" as IDiscussionBoardReportReasonCategory,
    "Harassment" as IDiscussionBoardReportReasonCategory,
    "Other" as IDiscussionBoardReportReasonCategory,
  ] as const;

  const createdReports: IDiscussionBoardReport[] = [];
  for (let i = 0; i < reporters.length; ++i) {
    const r = reporters[i];
    const report = await api.functional.discussionBoard.member.reports.create(
      r.conn,
      {
        body: {
          target_type: "article",
          target_id: article.id,
          reason_category: reasonCategories[i % reasonCategories.length],
          explanation: RandomGenerator.paragraph({ sentences: 8 }),
        } satisfies IDiscussionBoardReport.ICreate,
      },
    );
    typia.assert(report);
    createdReports.push(report);
  }

  // 4) Create moderator context
  const modConn: api.IConnection = { ...connection, headers: {} };
  const modAuth = await api.functional.auth.moderator.join(modConn, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "ModeratorPass123!",
      href: "https://example.com/mod",
      referrer: "https://example.com/ref",
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(modAuth);

  // 5) Moderator: retrieve paginated summaries without filters
  const pageAll: IPageIDiscussionBoardReport.ISummary =
    await api.functional.discussionBoard.moderator.articles.reports.index(
      modConn,
      {
        articleId: article.id,
        body: {
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardReport.IRequest,
      },
    );
  typia.assert(pageAll);

  // Validate pagination metadata and that at least the reports we created exist
  TestValidator.predicate(
    "pagination.records should be >= number of created reports",
    pageAll.pagination.records >= createdReports.length,
  );
  TestValidator.predicate(
    "page data should include at least one report",
    pageAll.data.length > 0,
  );

  // Each returned summary has required fields guaranteed by typia.assert;
  // do a business-level check that explanationExcerpt is present (excerpt)
  TestValidator.predicate(
    "each returned summary has explanationExcerpt or null",
    pageAll.data.every((s) => s.explanationExcerpt !== undefined),
  );

  // 6a) Filter by status (expect default 'pending')
  const pageStatus: IPageIDiscussionBoardReport.ISummary =
    await api.functional.discussionBoard.moderator.articles.reports.index(
      modConn,
      {
        articleId: article.id,
        body: {
          status: "pending" as IDiscussionBoardReportStatus,
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardReport.IRequest,
      },
    );
  typia.assert(pageStatus);
  TestValidator.predicate(
    "all results must have status 'pending'",
    pageStatus.data.every((d) => d.status === "pending"),
  );

  // 6b) Filter by reasonCategory (Spam)
  const pageSpam: IPageIDiscussionBoardReport.ISummary =
    await api.functional.discussionBoard.moderator.articles.reports.index(
      modConn,
      {
        articleId: article.id,
        body: {
          reasonCategory: "Spam" as IDiscussionBoardReportReasonCategory,
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardReport.IRequest,
      },
    );
  typia.assert(pageSpam);
  TestValidator.predicate(
    "all results must have reasonCategory 'Spam'",
    pageSpam.data.every((d) => d.reasonCategory === "Spam"),
  );

  // 6c) Date-range filter: use one created report's created_at to narrow
  const pivot = createdReports[1].created_at;
  const pageByDate: IPageIDiscussionBoardReport.ISummary =
    await api.functional.discussionBoard.moderator.articles.reports.index(
      modConn,
      {
        articleId: article.id,
        body: {
          createdFrom: pivot,
          createdTo: pivot,
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardReport.IRequest,
      },
    );
  typia.assert(pageByDate);
  TestValidator.predicate(
    "date-range filter results within boundaries",
    pageByDate.data.every((d) => d.createdAt >= pivot && d.createdAt <= pivot),
  );

  // 7a) Negative: non-moderator member should get 403 Forbidden
  await TestValidator.httpError(
    "non-moderator cannot access moderator reports endpoint",
    403,
    async () => {
      await api.functional.discussionBoard.moderator.articles.reports.index(
        reporters[0].conn,
        {
          articleId: article.id,
          body: { page: 1 } satisfies IDiscussionBoardReport.IRequest,
        },
      );
    },
  );

  // 7b) Negative: malformed articleId should return 400 Bad Request
  await TestValidator.httpError(
    "malformed articleId returns 400",
    400,
    async () => {
      await api.functional.discussionBoard.moderator.articles.reports.index(
        modConn,
        {
          articleId: "not-a-uuid",
          body: { page: 1 } satisfies IDiscussionBoardReport.IRequest,
        },
      );
    },
  );

  // 7c) Query an articleId with no reports -> expect empty data array
  const emptyArticle: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(
      reporters[0].conn,
      {
        body: {
          title: RandomGenerator.paragraph({
            sentences: 4,
            wordMin: 3,
            wordMax: 6,
          }),
          content: RandomGenerator.content({ paragraphs: 1 }),
          state: "published",
        } satisfies IDiscussionBoardArticle.ICreate,
      },
    );
  typia.assert(emptyArticle);

  const emptyPage: IPageIDiscussionBoardReport.ISummary =
    await api.functional.discussionBoard.moderator.articles.reports.index(
      modConn,
      {
        articleId: emptyArticle.id,
        body: { page: 1, limit: 10 } satisfies IDiscussionBoardReport.IRequest,
      },
    );
  typia.assert(emptyPage);

  TestValidator.equals(
    "empty article returns zero records",
    emptyPage.pagination.records,
    0,
  );
  TestValidator.equals("empty article data array is empty", emptyPage.data, []);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardSearch } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSearch";
import type { IDiscussionBoardSearchResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSearchResult";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardSearchResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardSearchResult";

/**
 * End-to-end test: Global full-text search filtered by category and tag.
 *
 * Business purpose:
 *
 * - Ensure that the global search endpoint returns published articles that match
 *   a full-text query and respect category/tag filters.
 * - Validate pagination metadata and behavior when no matches exist.
 *
 * Workflow:
 *
 * 1. Register a moderator and create a category and tag (taxonomy setup).
 * 2. Register a member and create a published article containing a unique keyword;
 *    assign the created category (by slug) and tag (by slug).
 * 3. Create a comment and an attachment for the article; these include unique
 *    keywords (for realistic coverage), but primary verification focuses on
 *    article-level search results because the available response DTOs are
 *    article summaries.
 * 4. Call PATCH /discussionBoard/search/global with a query that targets the
 *    article's unique keyword and filters (categoryId + tagSlugs). Validate
 *    that the created article appears in results and that returned summaries
 *    include expected fields and relationships (category, tags).
 * 5. Call search with a non-existent random token and verify empty result set and
 *    correct pagination metadata.
 */
export async function test_api_search_global_fulltext_by_category_and_tag(
  connection: api.IConnection,
) {
  // 1. Moderator: join and create taxonomy (category + tag)
  const moderatorPassword = "Moderator!23456";
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        username: `mod_${RandomGenerator.alphaNumeric(6)}`,
        email: typia.random<string & tags.Format<"email">>(),
        password: moderatorPassword,
        href: "https://example.com/moderator",
        referrer: "https://example.com",
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // Create category
  const categorySlug = `cat-${RandomGenerator.alphaNumeric(6)}`;
  const category: IDiscussionBoardCategory =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: RandomGenerator.name(2),
          slug: categorySlug,
          description: RandomGenerator.paragraph({ sentences: 6 }),
          is_active: true,
        } satisfies IDiscussionBoardCategory.ICreate,
      },
    );
  typia.assert(category);

  // Create tag
  const tagSlug = `tag-${RandomGenerator.alphaNumeric(6)}`;
  const tag: IDiscussionBoardTag =
    await api.functional.discussionBoard.moderator.tags.create(connection, {
      body: {
        name: RandomGenerator.name(2),
        slug: tagSlug,
      } satisfies IDiscussionBoardTag.ICreate,
    });
  typia.assert(tag);

  // 2. Member: join and create a published article referencing category + tag
  const memberPassword = "Member!23456789";
  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: {
        username: `user_${RandomGenerator.alphaNumeric(6)}`,
        email: typia.random<string & tags.Format<"email">>(),
        password: memberPassword,
        href: "https://example.com/member",
        referrer: "https://example.com",
      } satisfies IDiscussionBoardMember.IJoin,
    });
  typia.assert(member);

  // Unique token for searchability
  const articleToken = RandomGenerator.alphaNumeric(8);
  const articleTitle = `E2E Search Article ${articleToken}`;
  const articleContent = `${RandomGenerator.content({ paragraphs: 2 })}\n\nSearchToken:${articleToken}`;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: {
        title: articleTitle,
        content: articleContent,
        category_slug: category.slug,
        tag_slugs: [tag.slug],
        state: "published",
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(article);

  // 3. Create a comment that contains its own token (helps multi-entity coverage)
  const commentToken = RandomGenerator.alphaNumeric(8);
  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.member.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: {
          content: `Comment content referencing ${commentToken}`,
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment);

  // 4. Upload an attachment whose original_filename contains the article token
  const attachmentFilename = `attach_${articleToken}_${RandomGenerator.alphaNumeric(
    6,
  )}.png`;
  const storageKey = `https://storage.example.com/${RandomGenerator.alphaNumeric(12)}`;
  const attachment: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.member.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: {
          original_filename: attachmentFilename,
          storage_key: storageKey,
          mime_type: "image/png",
          size: typia.random<
            number &
              tags.Type<"int32"> &
              tags.Minimum<0> &
              tags.Maximum<5242880>
          >(),
          is_image: true,
        } satisfies IDiscussionBoardAttachment.ICreate,
      },
    );
  typia.assert(attachment);

  // 5. Search: full-text query matching the article token, filter by category id and tag slug
  const searchRequest: IDiscussionBoardSearch.IRequest = {
    query: articleToken,
    filters: {
      types: ["article", "comment", "attachment", "tag"],
      categoryId: category.id,
      tagSlugs: [tag.slug],
    },
    page: 1,
    limit: 20,
    sort: "relevance",
    highlight: true,
  } satisfies IDiscussionBoardSearch.IRequest;

  const searchResult: IPageIDiscussionBoardSearchResult.ISummary =
    await api.functional.discussionBoard.search.global.search(connection, {
      body: searchRequest,
    });
  typia.assert(searchResult);

  // Validate pagination metadata exists
  TestValidator.predicate(
    "pagination exists",
    searchResult.pagination !== null && searchResult.pagination !== undefined,
  );

  // Validate that at least one returned summary matches the created article id
  TestValidator.predicate(
    "created article appears in search results",
    searchResult.data.some((d) => d.id === article.id),
  );

  // Find the article summary and validate fields
  const found = searchResult.data.find((d) => d.id === article.id);
  typia.assert(found!);
  const articleSummary = found!;

  TestValidator.equals("article id matches", articleSummary.id, article.id);
  TestValidator.equals(
    "article title matches",
    articleSummary.title,
    article.title,
  );

  // Category association check (actual-first, expected-second)
  TestValidator.equals(
    "article category matches",
    articleSummary.category?.id ?? null,
    category.id,
  );

  // Tag association: ensure at least one tag with matching slug exists on the summary
  TestValidator.predicate(
    "article includes created tag",
    (articleSummary.tags ?? []).some((t) => t.slug === tag.slug),
  );

  // 6. Combined filters behavior: search again and assert every returned
  // article (if any) belongs to the requested category and references the tag
  const combinedResult: IPageIDiscussionBoardSearchResult.ISummary =
    await api.functional.discussionBoard.search.global.search(connection, {
      body: {
        query: articleToken,
        filters: {
          types: ["article"],
          categoryId: category.id,
          tagSlugs: [tag.slug],
        },
        page: 1,
        limit: 50,
        highlight: false,
      } satisfies IDiscussionBoardSearch.IRequest,
    });
  typia.assert(combinedResult);

  // All returned items (if any) must have the category and tag
  TestValidator.predicate(
    "combined filters restrict results to category and tag",
    combinedResult.data.every(
      (d) =>
        d.category?.id === category.id &&
        (d.tags ?? []).some((t) => t.slug === tag.slug),
    ),
  );

  // 7. Edge-case: search for a random nonexistent token -> expect empty results
  const randomToken = `noexist_${RandomGenerator.alphaNumeric(12)}`;
  const emptySearch: IPageIDiscussionBoardSearchResult.ISummary =
    await api.functional.discussionBoard.search.global.search(connection, {
      body: {
        query: randomToken,
        page: 1,
        limit: 20,
      } satisfies IDiscussionBoardSearch.IRequest,
    });
  typia.assert(emptySearch);

  TestValidator.equals(
    "empty search returns zero data",
    emptySearch.data.length,
    0,
  );
  TestValidator.predicate(
    "empty search pagination is valid",
    emptySearch.pagination !== null && emptySearch.pagination !== undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleActivityStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleActivityStatistics";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

export async function test_api_statistics_article_activity_time_series(
  connection: api.IConnection,
) {
  // Create moderator and category
  const modConn: api.IConnection = { ...connection, headers: {} };
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(modConn, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: typia.random<string & tags.Format<"email">>(),
        password: RandomGenerator.alphaNumeric(12),
        display_name: RandomGenerator.name(),
        href: "http://example.com/scene",
        referrer: "http://example.com/ref",
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  const categoryBody = {
    name: `cat-${RandomGenerator.alphaNumeric(6)}`,
    slug: `cat-${RandomGenerator.alphaNumeric(6)}`.toLowerCase(),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    is_active: true,
  } satisfies IDiscussionBoardCategory.ICreate;

  const category: IDiscussionBoardCategory =
    await api.functional.discussionBoard.moderator.categories.create(modConn, {
      body: categoryBody,
    });
  typia.assert(category);

  // Create two members (authors)
  const memberConn1: api.IConnection = { ...connection, headers: {} };
  const member1: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(memberConn1, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: typia.random<string & tags.Format<"email">>(),
        password: RandomGenerator.alphaNumeric(12),
        display_name: RandomGenerator.name(),
        href: "http://example.com/member1",
        referrer: "http://example.com/ref",
      } satisfies IDiscussionBoardMember.IJoin,
    });
  typia.assert(member1);

  const memberConn2: api.IConnection = { ...connection, headers: {} };
  const member2: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(memberConn2, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: typia.random<string & tags.Format<"email">>(),
        password: RandomGenerator.alphaNumeric(12),
        display_name: RandomGenerator.name(),
        href: "http://example.com/member2",
        referrer: "http://example.com/ref",
      } satisfies IDiscussionBoardMember.IJoin,
    });
  typia.assert(member2);

  // Create articles for both members. Request 'published' state so server
  // sets published_at within the current time window.
  const articlesByMember1 = await ArrayUtil.asyncRepeat(3, async (i) => {
    const body = {
      title: RandomGenerator.paragraph({
        sentences: 6,
        wordMin: 3,
        wordMax: 8,
      }),
      content: RandomGenerator.content({ paragraphs: 2 }),
      category_slug: category.slug,
      state: "published",
    } satisfies IDiscussionBoardArticle.ICreate;

    const article: IDiscussionBoardArticle =
      await api.functional.discussionBoard.member.articles.create(memberConn1, {
        body,
      });
    typia.assert(article);
    return article;
  });

  const articlesByMember2 = await ArrayUtil.asyncRepeat(2, async (i) => {
    const body = {
      title: RandomGenerator.paragraph({ sentences: 5 }),
      content: RandomGenerator.content({ paragraphs: 1 }),
      category_slug: category.slug,
      state: "published",
    } satisfies IDiscussionBoardArticle.ICreate;

    const article: IDiscussionBoardArticle =
      await api.functional.discussionBoard.member.articles.create(memberConn2, {
        body,
      });
    typia.assert(article);
    return article;
  });

  const createdArticles = [...articlesByMember1, ...articlesByMember2];
  const totalArticles = createdArticles.length;

  // For each article create comments and attachments
  let totalComments = 0;
  let totalAttachments = 0;

  await ArrayUtil.asyncForEach(createdArticles, async (article, idx) => {
    const commentsCount = idx % 2 === 0 ? 3 : 1; // varied counts
    const attachmentsCount = idx % 2 === 0 ? 1 : 0; // some articles have attachments

    // Choose the author's connection based on membership
    const authorConn =
      idx < articlesByMember1.length ? memberConn1 : memberConn2;

    // Create comments
    await ArrayUtil.asyncRepeat(commentsCount, async () => {
      const commentBody = {
        content: RandomGenerator.paragraph({ sentences: 2 }),
      } satisfies IDiscussionBoardComment.ICreate;

      const comment: IDiscussionBoardComment =
        await api.functional.discussionBoard.member.articles.comments.create(
          authorConn,
          {
            articleId: article.id,
            body: commentBody,
          },
        );
      typia.assert(comment);
      totalComments += 1;
    });

    // Create attachments when applicable
    await ArrayUtil.asyncRepeat(attachmentsCount, async () => {
      const attachBody = {
        original_filename: `file-${RandomGenerator.alphaNumeric(6)}.txt`,
        storage_key: `https://storage.example.com/${RandomGenerator.alphaNumeric(12)}`,
        mime_type: "text/plain",
        size: 1024,
        is_image: false,
      } satisfies IDiscussionBoardAttachment.ICreate;

      const attachment: IDiscussionBoardAttachment =
        await api.functional.discussionBoard.member.articles.attachments.create(
          authorConn,
          {
            articleId: article.id,
            body: attachBody,
          },
        );
      typia.assert(attachment);
      totalAttachments += 1;
    });
  });

  // Call statistics endpoint (no date params supported by SDK; defaults apply)
  const stats: IDiscussionBoardArticleActivityStatistics =
    await api.functional.discussionBoard.statistics.article_activity.articleActivity(
      connection,
    );
  typia.assert(stats);

  // Validate summary metrics
  TestValidator.equals(
    "summary article_count matches created articles",
    stats.summary.article_count,
    totalArticles,
  );
  TestValidator.equals(
    "summary comment_count matches created comments",
    stats.summary.comment_count,
    totalComments,
  );
  TestValidator.equals(
    "summary attachment_count matches created attachments",
    stats.summary.attachment_count,
    totalAttachments,
  );

  // Today's bucket
  const today = new Date().toISOString().slice(0, 10);
  const todayBucket = stats.time_series.find((b) => b.date === today);
  TestValidator.predicate(
    "time_series contains today's bucket",
    todayBucket !== undefined,
  );

  if (todayBucket) {
    TestValidator.equals(
      "today article_count matches",
      todayBucket.article_count,
      totalArticles,
    );
    TestValidator.equals(
      "today comment_count matches",
      todayBucket.comment_count,
      totalComments,
    );
    TestValidator.equals(
      "today attachment_count matches",
      todayBucket.attachment_count,
      totalAttachments,
    );
  }

  // average_comments_per_article: numeric comparison
  if (totalArticles === 0) {
    TestValidator.equals(
      "average_comments_per_article is null when no articles",
      stats.summary.average_comments_per_article,
      null,
    );
  } else {
    const expectedAvg = totalComments / totalArticles;
    TestValidator.predicate(
      "average_comments_per_article approximately equals computed value",
      typeof stats.summary.average_comments_per_article === "number" &&
        Math.abs(stats.summary.average_comments_per_article - expectedAvg) <
          1e-6,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

/**
 * E2E: Moderator updates a discussion tag
 *
 * Business context:
 *
 * - Moderators manage the discussion board taxonomy. They can create tags and
 *   later modify editable fields for governance (name, description,
 *   activation).
 * - Slug is canonical and immutable; updated_at must advance on modification
 *   while id, slug and created_at remain unchanged.
 *
 * Steps:
 *
 * 1. Register a fresh moderator (auth.moderator.join).
 * 2. Create a tag using moderator.create (capture id, slug, created_at).
 * 3. Update tag via moderator.tags.update (update name, description, is_active).
 * 4. Assert immutable fields unchanged and updated_at advanced.
 */
export async function test_api_tag_update_by_moderator(
  connection: api.IConnection,
) {
  // 1) Register a fresh moderator account
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorCreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: moderatorEmail,
    password: "StrongPass!2345", // >=12 chars
    href: "https://example.com/",
    referrer: "https://example.com/ref",
    display_name: RandomGenerator.name(),
  } satisfies IDiscussionBoardModerator.ICreate;

  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: moderatorCreate,
    });
  typia.assert(moderator);

  // 2) Create an initial tag as the moderator
  const slug = `tag-${RandomGenerator.alphabets(8)}`.toLowerCase();
  const createBody = {
    name: RandomGenerator.paragraph({ sentences: 3 }),
    slug,
    description: RandomGenerator.paragraph({ sentences: 5 }),
    is_active: true,
  } satisfies IDiscussionBoardTag.ICreate;

  const created: IDiscussionBoardTag =
    await api.functional.discussionBoard.moderator.tags.create(connection, {
      body: createBody,
    });
  typia.assert(created);

  // 3) Prepare update payload (ICreate -> IUpdate differences considered)
  const newName = RandomGenerator.paragraph({ sentences: 2 });
  const newDescription = RandomGenerator.paragraph({ sentences: 4 });
  const newIsActive = !created.is_active;

  const updateBody = {
    name: newName,
    description: newDescription,
    is_active: newIsActive,
  } satisfies IDiscussionBoardTag.IUpdate;

  // 4) Perform update (slug is path parameter and must remain unchanged)
  const updated: IDiscussionBoardTag =
    await api.functional.discussionBoard.moderator.tags.update(connection, {
      tagSlug: created.slug,
      body: updateBody,
    });
  typia.assert(updated);

  // 5) Business assertions
  TestValidator.equals("id unchanged after update", updated.id, created.id);
  TestValidator.equals(
    "slug unchanged after update",
    updated.slug,
    created.slug,
  );
  TestValidator.equals(
    "created_at unchanged after update",
    updated.created_at,
    created.created_at,
  );

  TestValidator.equals("name updated", updated.name, newName);
  TestValidator.equals(
    "description updated",
    updated.description,
    newDescription,
  );
  TestValidator.equals("is_active updated", updated.is_active, newIsActive);

  TestValidator.notEquals(
    "updated_at changed",
    updated.updated_at,
    created.updated_at,
  );
  TestValidator.predicate(
    "updated_at is later than created_at",
    Date.parse(updated.updated_at) > Date.parse(created.created_at),
  );

  // Optional: audit/moderation log verification not implemented because no
  // read endpoint was provided in the SDK materials.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleTag";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

/**
 * Validate that soft-deleting a tag is blocked when the tag has active
 * assignments to articles.
 *
 * Business context:
 *
 * - Moderators manage tags. Tags are assignable to articles by members.
 * - When an article is assigned a tag, policy prevents soft-deleting that tag
 *   while active assignments exist. The system should block deletion and
 *   preserve the tag (deleted_at remains null and is_active remains
 *   unchanged).
 *
 * Test steps:
 *
 * 1. Moderator A signs up (moderator token set on connection).
 * 2. Moderator A creates a tag with a unique slug.
 * 3. Member signs up and creates an article.
 * 4. Member assigns the created tag to the article.
 * 5. Moderator B signs up and attempts to delete the tag.
 * 6. Deletion should be blocked (an error is thrown). Verify by attempting to
 *    create a tag with the same slug — that should fail, proving the tag still
 *    exists.
 */
export async function test_api_tag_soft_delete_blocked_when_assigned(
  connection: api.IConnection,
) {
  // 1. Moderator A signs up
  const moderatorAUsername = RandomGenerator.alphaNumeric(8);
  const moderatorAEmail = typia.random<string & tags.Format<"email">>();
  const moderatorAPassword = `Aa1!${RandomGenerator.alphaNumeric(12)}`; // >=12 chars with mixed content

  const moderatorA: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        username: moderatorAUsername,
        email: moderatorAEmail,
        password: moderatorAPassword,
        href: "http://example.com/",
        referrer: "http://example.com/ref",
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderatorA);

  // 2. Moderator A creates a new tag
  const tagSlug = RandomGenerator.alphaNumeric(8).toLowerCase();
  const tagName = RandomGenerator.paragraph({ sentences: 3 });

  const createdTag: IDiscussionBoardTag =
    await api.functional.discussionBoard.moderator.tags.create(connection, {
      body: {
        name: tagName,
        slug: tagSlug,
        description: "E2E test tag",
      } satisfies IDiscussionBoardTag.ICreate,
    });
  typia.assert(createdTag);

  // 3. Member signs up
  const memberUsername = RandomGenerator.alphaNumeric(8);
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = `Mm1!${RandomGenerator.alphaNumeric(12)}`;

  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: {
        username: memberUsername,
        email: memberEmail,
        password: memberPassword,
        href: "http://example.com/",
        referrer: "http://example.com/ref",
      } satisfies IDiscussionBoardMember.IJoin,
    });
  typia.assert(member);

  // 4. Member creates an article
  const articleTitle = RandomGenerator.paragraph({ sentences: 3 });
  const articleBody = RandomGenerator.content({ paragraphs: 2 });

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: {
        title: articleTitle,
        content: articleBody,
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(article);

  // 5. Member assigns the created tag to the article
  const assignment: IDiscussionBoardArticleTag =
    await api.functional.discussionBoard.member.articles.tags.create(
      connection,
      {
        articleId: article.id,
        body: {
          tagSlug: createdTag.slug,
        } satisfies IDiscussionBoardArticleTag.ICreate,
      },
    );
  typia.assert(assignment);

  // Validate assignment references
  TestValidator.equals(
    "assignment references created article",
    assignment.article.id,
    article.id,
  );
  TestValidator.equals(
    "assignment references created tag slug",
    assignment.tag.slug,
    createdTag.slug,
  );

  // 6. Moderator B signs up (to perform the deletion attempt)
  const moderatorBUsername = RandomGenerator.alphaNumeric(8);
  const moderatorBEmail = typia.random<string & tags.Format<"email">>();
  const moderatorBPassword = `Bb1!${RandomGenerator.alphaNumeric(12)}`;

  const moderatorB: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        username: moderatorBUsername,
        email: moderatorBEmail,
        password: moderatorBPassword,
        href: "http://example.com/",
        referrer: "http://example.com/ref",
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderatorB);

  // 7. Moderator B attempts to soft-delete the tag — expect an error because assignment exists
  await TestValidator.error(
    "deletion should be blocked when tag has active article assignments",
    async () => {
      await api.functional.discussionBoard.moderator.tags.erase(connection, {
        tagSlug: createdTag.slug,
      });
    },
  );

  // 8. Verify the tag still persists by attempting to create a tag with the same slug — it should fail (duplicate)
  await TestValidator.error(
    "duplicate tag creation should fail after blocked deletion",
    async () => {
      await api.functional.discussionBoard.moderator.tags.create(connection, {
        body: {
          name: `${tagName}-dup`,
          slug: createdTag.slug,
        } satisfies IDiscussionBoardTag.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

export async function test_api_comment_creation_by_member(
  connection: api.IConnection,
) {
  // 1) Register a fresh member and obtain authorization token
  const memberBody = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: "P@ssw0rd12345",
    href: "https://example.com/test",
    referrer: "https://example.com/referrer",
  } satisfies IDiscussionBoardMember.IJoin;

  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: memberBody,
    });
  typia.assert(member);

  // 2) Create a parent article with the authenticated member's context
  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 5, wordMax: 10 }),
    content: RandomGenerator.content({ paragraphs: 2 }),
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: articleBody,
    });
  typia.assert(article);
  TestValidator.predicate(
    "article id is present",
    typeof article.id === "string" && article.id.length > 0,
  );

  // 3) Create a top-level comment on the article
  const commentContent = RandomGenerator.paragraph({
    sentences: 2,
    wordMin: 3,
    wordMax: 8,
  });
  const commentReq = {
    content: commentContent,
  } satisfies IDiscussionBoardComment.ICreate;

  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.member.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: commentReq,
      },
    );
  typia.assert(comment);

  // Business validations
  TestValidator.equals(
    "comment content persisted",
    comment.content,
    commentContent,
  );

  // Ensure author summary exists and matches created member when present
  if (comment.author !== null && comment.author !== undefined) {
    typia.assert(comment.author);
    TestValidator.equals(
      "comment author id matches member id",
      comment.author.id,
      member.id,
    );
  } else {
    // If author is null (anonymized), at least ensure article association and content
    TestValidator.predicate(
      "comment author is anonymized or absent",
      comment.author === null || comment.author === undefined,
    );
  }

  TestValidator.predicate(
    "comment has creation timestamp",
    comment.createdAt !== null && comment.createdAt !== undefined,
  );
  TestValidator.equals(
    "comment.articleId matches article id",
    comment.articleId,
    article.id,
  );

  // Negative: unauthenticated comment creation should fail (no Authorization header)
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "unauthenticated comment creation should fail",
    async () => {
      await api.functional.discussionBoard.member.articles.comments.create(
        unauthConn,
        {
          articleId: article.id,
          body: commentReq,
        },
      );
    },
  );

  // Negative: invalid parentCommentId (non-existent) should cause failure
  const fakeParentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error(
    "creating comment with non-existent parentCommentId should fail",
    async () => {
      await api.functional.discussionBoard.member.articles.comments.create(
        connection,
        {
          articleId: article.id,
          body: {
            content: RandomGenerator.paragraph({ sentences: 2 }),
            parentCommentId: fakeParentId,
          } satisfies IDiscussionBoardComment.ICreate,
        },
      );
    },
  );

  // Throttling / anti-abuse: attempt rapid repeated comment creation
  // Try creating many comments in quick succession and observe if any error occurs.
  try {
    let createdCount = 0;
    await ArrayUtil.asyncRepeat(10, async () => {
      const c =
        await api.functional.discussionBoard.member.articles.comments.create(
          connection,
          {
            articleId: article.id,
            body: {
              content: RandomGenerator.paragraph({ sentences: 1 }),
            } satisfies IDiscussionBoardComment.ICreate,
          },
        );
      typia.assert(c);
      createdCount++;
    });
    TestValidator.predicate(
      "burst comment creation completed without observable throttling",
      createdCount > 0,
    );
  } catch (err) {
    // If server enforces throttling/anti-abuse, ensure an error was thrown
    TestValidator.predicate(
      "burst comment creation triggered throttling or failed",
      err !== undefined && err !== null,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

export async function test_api_comment_retrieval_public_by_article(
  connection: api.IConnection,
) {
  // 1) Member registration (join)
  const memberBody = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    // Password satisfies length and includes categories (upper/lower/digit/symbol)
    password: `Aa1!${RandomGenerator.alphaNumeric(9)}`,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.IJoin;

  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: memberBody,
    });
  typia.assert(member);

  // 2) Create an article as the authenticated member
  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 6, wordMin: 4, wordMax: 10 }),
    content: RandomGenerator.content({ paragraphs: 2 }),
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: articleBody,
    });
  typia.assert(article);

  // 3) Create a comment under the article
  const commentBody = {
    content: RandomGenerator.paragraph({
      sentences: 8,
      wordMin: 3,
      wordMax: 8,
    }),
  } satisfies IDiscussionBoardComment.ICreate;

  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.member.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: commentBody,
      },
    );
  typia.assert(comment);

  // 4) Public (unauthenticated) retrieval: create unauthenticated connection
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  const publicComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.articles.comments.at(unauthConn, {
      articleId: article.id,
      commentId: comment.id,
    });
  typia.assert(publicComment);

  // Business validations
  TestValidator.equals(
    "public comment id matches created comment",
    publicComment.id,
    comment.id,
  );

  TestValidator.equals(
    "public comment content matches created content",
    publicComment.content,
    comment.content,
  );

  // typia.assert already validated types (including createdAt). Additional
  // business predicates below check presence/shape and omission of sensitive
  // fields in the public JSON payload.
  TestValidator.predicate(
    "public comment has createdAt",
    publicComment.createdAt !== null && publicComment.createdAt !== undefined,
  );

  // Author may be anonymized (null) depending on server policy. If present,
  // assert its shape; if null, accept it as a valid anonymized author.
  if (publicComment.author !== null && publicComment.author !== undefined) {
    typia.assert(publicComment.author);
    TestValidator.predicate(
      "author summary contains id",
      typeof publicComment.author.id === "string" &&
        publicComment.author.id.length > 0,
    );
    TestValidator.predicate(
      "author summary contains username",
      typeof publicComment.author.username === "string" &&
        publicComment.author.username.length > 0,
    );
  } else {
    // Accept anonymized author: no further author-specific assertions
    TestValidator.predicate("author is anonymized or absent", true);
  }

  // Ensure sensitive fields like 'email' are not present in public payload (basic leakage check)
  TestValidator.predicate(
    "public response does not contain sensitive 'email' field",
    !JSON.stringify(publicComment).includes('"email"'),
  );

  // Negative scenarios: non-existent comment under same article and mismatched articleId
  await TestValidator.error(
    "non-existent comment id under existing article yields error",
    async () => {
      await api.functional.discussionBoard.articles.comments.at(unauthConn, {
        articleId: article.id,
        commentId: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  await TestValidator.error(
    "existing comment id with mismatched articleId yields error",
    async () => {
      await api.functional.discussionBoard.articles.comments.at(unauthConn, {
        articleId: typia.random<string & tags.Format<"uuid">>(),
        commentId: comment.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportReasonCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportReasonCategory";
import type { IDiscussionBoardReportStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportStatus";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardReport";

/**
 * Validate moderation queue aggregation and prioritized triage flow for
 * moderator actors.
 *
 * Steps:
 *
 * 1. Register two members (reporters) and one moderator (triage actor).
 * 2. Using member1: create an article, an attachment for that article, and a
 *    comment under the article.
 * 3. File multiple reports across targets (article, comment, attachment) using
 *    both members to create aggregated reportCounts.
 * 4. Using the moderator context, query PATCH
 *    /discussionBoard/moderator/moderationQueue with priority and
 *    includeReporterContext to retrieve aggregated, prioritized queue items.
 * 5. Validate pagination, that created targets are present, that reportCount
 *    aggregation influences ordering (higher reportCount first), that reporter
 *    context is present when requested, and that RBAC prevents members from
 *    calling the moderator endpoint.
 */
export async function test_api_moderation_queue_report_prioritization(
  connection: api.IConnection,
) {
  // Prepare isolated connection contexts so SDK can manage Authorization headers
  const memberConn1: api.IConnection = { ...connection, headers: {} };
  const memberConn2: api.IConnection = { ...connection, headers: {} };
  const moderatorConn: api.IConnection = { ...connection, headers: {} };

  // 1) Register moderator and two members
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(moderatorConn, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: moderatorEmail,
        password: `Mod${RandomGenerator.alphaNumeric(10)}!`,
        display_name: RandomGenerator.name(),
        href: "https://example.com/", // session context
        referrer: "https://example.com/",
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  const member1Email = typia.random<string & tags.Format<"email">>();
  const member1: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(memberConn1, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: member1Email,
        password: `Pass${RandomGenerator.alphaNumeric(10)}!`,
        display_name: RandomGenerator.name(),
        href: "https://example.com/",
        referrer: "https://example.com/",
      } satisfies IDiscussionBoardMember.IJoin,
    });
  typia.assert(member1);

  const member2Email = typia.random<string & tags.Format<"email">>();
  const member2: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(memberConn2, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: member2Email,
        password: `Pass${RandomGenerator.alphaNumeric(10)}!`,
        display_name: RandomGenerator.name(),
        href: "https://example.com/",
        referrer: "https://example.com/",
      } satisfies IDiscussionBoardMember.IJoin,
    });
  typia.assert(member2);

  // 2) Member1 creates an article, attachment, and a comment
  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(memberConn1, {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 4,
          wordMin: 4,
          wordMax: 8,
        }),
        content: RandomGenerator.content({
          paragraphs: 2,
          sentenceMin: 12,
          sentenceMax: 18,
          wordMin: 4,
          wordMax: 8,
        }),
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(article);

  const attachment: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.member.articles.attachments.create(
      memberConn1,
      {
        articleId: article.id,
        body: {
          original_filename: `file-${RandomGenerator.alphaNumeric(6)}.png`,
          storage_key: typia.random<string & tags.Format<"uri">>(),
          mime_type: "image/png",
          size: typia.random<
            number &
              tags.Type<"int32"> &
              tags.Minimum<0> &
              tags.Maximum<5242880>
          >(),
          is_image: true,
        } satisfies IDiscussionBoardAttachment.ICreate,
      },
    );
  typia.assert(attachment);

  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.member.articles.comments.create(
      memberConn1,
      {
        articleId: article.id,
        body: {
          content: RandomGenerator.paragraph({
            sentences: 6,
            wordMin: 3,
            wordMax: 7,
          }),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment);

  // 3) Submit reports using both members to create aggregated counts
  // member1 reports: article, comment
  const reportA1: IDiscussionBoardReport =
    await api.functional.discussionBoard.member.reports.create(memberConn1, {
      body: {
        target_type: "article",
        target_id: article.id,
        reason_category: "Spam",
        explanation: "Inappropriate content repeated",
      } satisfies IDiscussionBoardReport.ICreate,
    });
  typia.assert(reportA1);

  const reportC1: IDiscussionBoardReport =
    await api.functional.discussionBoard.member.reports.create(memberConn1, {
      body: {
        target_type: "comment",
        target_id: comment.id,
        reason_category: "Harassment",
        explanation: "Offensive language",
      } satisfies IDiscussionBoardReport.ICreate,
    });
  typia.assert(reportC1);

  // member2 reports: article, comment, attachment — ensures duplicates across reporters
  const reportA2: IDiscussionBoardReport =
    await api.functional.discussionBoard.member.reports.create(memberConn2, {
      body: {
        target_type: "article",
        target_id: article.id,
        reason_category: "Misinformation",
        explanation: "Contains misleading claims",
      } satisfies IDiscussionBoardReport.ICreate,
    });
  typia.assert(reportA2);

  const reportC2: IDiscussionBoardReport =
    await api.functional.discussionBoard.member.reports.create(memberConn2, {
      body: {
        target_type: "comment",
        target_id: comment.id,
        reason_category: "Harassment",
        explanation: "Abusive reply",
      } satisfies IDiscussionBoardReport.ICreate,
    });
  typia.assert(reportC2);

  const reportAtt2: IDiscussionBoardReport =
    await api.functional.discussionBoard.member.reports.create(memberConn2, {
      body: {
        target_type: "attachment",
        target_id: attachment.id,
        reason_category: "Other",
        explanation: "Attachment is irrelevant",
      } satisfies IDiscussionBoardReport.ICreate,
    });
  typia.assert(reportAtt2);

  // 4) Moderator queries moderation queue requesting reporter context and priority
  const page: IPageIDiscussionBoardReport.ISummary =
    await api.functional.discussionBoard.moderator.moderationQueue.index(
      moderatorConn,
      {
        body: {
          page: 1,
          limit: 20,
          priority: true,
          includeReporterContext: true,
          sortBy: "priority",
        } satisfies IDiscussionBoardReport.IRequest,
      },
    );
  typia.assert(page);

  // Business validations
  TestValidator.predicate("pagination present and sensible", () => {
    return (
      typeof page.pagination?.current === "number" &&
      typeof page.pagination?.limit === "number" &&
      page.pagination.current >= 1 &&
      page.pagination.limit >= 1
    );
  });

  // At least one returned item references created article/comment/attachment
  TestValidator.predicate(
    "moderation queue contains our targets",
    () =>
      ArrayUtil.has(page.data, (d) => d.targetId === article.id) ||
      ArrayUtil.has(page.data, (d) => d.targetId === comment.id) ||
      ArrayUtil.has(page.data, (d) => d.targetId === attachment.id),
  );

  // Ensure aggregated reportCount exists and ordering by priority (desc)
  TestValidator.predicate("reportCount present for items", () =>
    page.data.some(
      (d) => d.reportCount !== null && d.reportCount !== undefined,
    ),
  );

  TestValidator.predicate("items sorted by reportCount descending", () => {
    let previous = Number.POSITIVE_INFINITY;
    for (const item of page.data) {
      const count = item.reportCount ?? 0;
      if (count > previous) return false; // ascending found -> fail
      previous = count;
    }
    return true;
  });

  // Reporter context: because includeReporterContext=true and moderator has audit role,
  // at least one summary should include reporter metadata but must not include session-level PII like 'reporter_session_id' or 'email'
  TestValidator.predicate("reporter context included when requested", () => {
    const found = page.data.find(
      (d) => d.reporter !== undefined && d.reporter !== null,
    );
    if (!found) return false;
    // Ensure reporter summary does not include email property (PII) in summary object
    const reporter = found.reporter as
      | IDiscussionBoardMember.ISummary
      | undefined
      | null;
    if (!reporter) return false;
    // reporter summary schema does not include email; check defensively
    return !("email" in (reporter as any));
  });

  // 5) Role-based access control: member context must not be able to call moderator endpoint
  await TestValidator.error(
    "member cannot access moderation queue",
    async () => {
      await api.functional.discussionBoard.moderator.moderationQueue.index(
        memberConn1,
        {
          body: { page: 1, limit: 1 } satisfies IDiscussionBoardReport.IRequest,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";

/**
 * Validate moderator-scoped member search and controlled exposure of privileged
 * fields.
 *
 * Business purpose:
 *
 * - Ensure a moderator can search members using public filters (username,
 *   createdAt range) and privileged filters (email).
 * - Ensure the endpoint returns paginated member summaries (id, username,
 *   display_name, created_at) and that privileged filters are honored for
 *   privileged callers.
 * - Ensure unauthenticated/unauthorized callers cannot access the
 *   moderator-scoped search endpoint.
 *
 * Test steps:
 *
 * 1. Register a moderator (POST /auth/moderator/join).
 * 2. Create two members via POST /auth/member/join using fresh connection clones.
 * 3. As moderator, call PATCH /discussionBoard/moderator/members with a username
 *    partial and pagination. Assert pagination metadata and that created
 *    members appear in results.
 * 4. As moderator, use privileged email filter to retrieve the specific member.
 *    Assert that the email filter returns the expected member summary.
 * 5. Verify unauthorized access: calling the endpoint with an unauthenticated
 *    connection results in an error.
 */
export async function test_api_moderator_member_search_with_privileged_fields(
  connection: api.IConnection,
) {
  // 1. Moderator registration
  const moderatorBody = typia.random<IDiscussionBoardModerator.ICreate>();
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: moderatorBody,
    });
  typia.assert(moderator);

  // 2. Create multiple members (use separate connection clones to avoid
  //    overwriting moderator Authorization header which the SDK sets on the
  //    passed connection object).
  const createdMembers: IDiscussionBoardMember.IAuthorized[] = [];
  for (let i = 0; i < 2; ++i) {
    const memberConn: api.IConnection = { ...connection, headers: {} };
    const memberBody = typia.random<IDiscussionBoardMember.IJoin>();
    const member: IDiscussionBoardMember.IAuthorized =
      await api.functional.auth.member.join(memberConn, {
        body: memberBody,
      });
    typia.assert(member);
    createdMembers.push(member);
  }

  // Defensive check: ensure we have created members
  TestValidator.predicate("created two members", createdMembers.length >= 2);

  // 3. Moderator searches by username partial with pagination
  const sample = createdMembers[0];
  // Use a short substring from username for partial matching
  const usernamePartial =
    sample.username.length > 3
      ? sample.username.substring(0, 3)
      : sample.username;

  const listRequest = {
    username: usernamePartial,
    page: 1,
    limit: 20,
  } satisfies IDiscussionBoardMember.IRequest;

  const page: IPageIDiscussionBoardMember.ISummary =
    await api.functional.discussionBoard.moderator.members.index(connection, {
      body: listRequest,
    });
  typia.assert(page);

  // Validate pagination metadata exists and is sensible
  TestValidator.predicate(
    "pagination current is at least 1",
    page.pagination.current >= 1,
  );
  TestValidator.predicate(
    "pagination limit is positive",
    page.pagination.limit > 0,
  );

  // Verify that one of created members appears in the results
  const foundByUsername = page.data.some((s) => s.id === sample.id);
  TestValidator.predicate(
    `search results include member by username partial (${usernamePartial})`,
    foundByUsername,
  );

  // 4. Privileged usage: moderator requests by email (privileged filter)
  // The IRequest.email property is privileged: calling with it should work for
  // moderator and return the matching member summary (we cannot assert audit
  // logs here).
  const emailRequest = {
    email: sample.email,
  } satisfies IDiscussionBoardMember.IRequest;

  const byEmail: IPageIDiscussionBoardMember.ISummary =
    await api.functional.discussionBoard.moderator.members.index(connection, {
      body: emailRequest,
    });
  typia.assert(byEmail);

  TestValidator.predicate(
    "email filter returns the targeted member",
    byEmail.data.some((s) => s.id === sample.id),
  );

  // 5. Unauthorized behaviour: unauthenticated connection should not be able
  //    to call moderator-scoped endpoint. Use an unauthenticated clone where
  //    headers is empty.
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  await TestValidator.error(
    "unauthenticated caller should not access moderator member index",
    async () => {
      await api.functional.discussionBoard.moderator.members.index(unauthConn, {
        body: {} satisfies IDiscussionBoardMember.IRequest,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
