import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportReasonCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportReasonCategory";
import type { IDiscussionBoardReportStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportStatus";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

export async function test_api_report_duplicate_conflict(
  connection: api.IConnection,
) {
  /**
   * 1. Register a new member (auth/join) and authenticate.
   * 2. Create an article as that member (state: 'draft' to avoid publish checks).
   * 3. Create a report against the article (first request should succeed).
   * 4. Submit the same report again and expect an error (use TestValidator.error
   *    to assert failure).
   */

  // 1) Member registration
  const joinBody = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: "Str0ngPassw0rd!",
    href: "https://example.com/",
    referrer: "https://referrer.example.com/",
  } satisfies IDiscussionBoardMember.IJoin;

  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: joinBody,
    });
  typia.assert(member);

  // 2) Create article (use draft to avoid publish permission constraints)
  const articleCreate = {
    title: RandomGenerator.paragraph({ sentences: 6, wordMin: 5, wordMax: 10 }),
    content: RandomGenerator.content({ paragraphs: 2 }),
    state: "draft",
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: articleCreate,
    });
  typia.assert(article);

  // Basic sanity check
  TestValidator.predicate(
    "article id should be present",
    article.id !== undefined && article.id !== null,
  );

  // 3) Create first report against article
  const reportBody = {
    target_type: "article",
    target_id: article.id,
    reason_category: "Spam" as IDiscussionBoardReportReasonCategory,
    explanation: RandomGenerator.paragraph({ sentences: 3 }),
  } satisfies IDiscussionBoardReport.ICreate;

  const report: IDiscussionBoardReport =
    await api.functional.discussionBoard.member.reports.create(connection, {
      body: reportBody,
    });
  typia.assert(report);

  TestValidator.equals(
    "report targets created article",
    report.target_id,
    article.id,
  );

  // 4) Re-submit the same report and expect a business error (duplicate). Do NOT assert status codes; assert that an error is thrown.
  await TestValidator.error("duplicate report should fail", async () => {
    await api.functional.discussionBoard.member.reports.create(connection, {
      body: reportBody,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportReasonCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportReasonCategory";
import type { IDiscussionBoardReportStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportStatus";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

/**
 * Validate reporting a comment by a reporter member.
 *
 * Workflow:
 *
 * 1. Author member joins and creates an article.
 * 2. Author posts a comment under that article.
 * 3. Reporter member joins (switches auth token on connection).
 * 4. Reporter files a report against the comment (target_type='comment').
 * 5. Validate report contents and business rules.
 * 6. Validate error conditions: duplicate report, unauthenticated report,
 *    reporting non-existent target.
 */
export async function test_api_report_create_for_comment_success(
  connection: api.IConnection,
) {
  // 1) Author member signs up (will set connection.headers.Authorization)
  const authorJoinBody = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    href: `https://example.com/${RandomGenerator.alphaNumeric(6)}`,
    referrer: `https://ref.example.com/${RandomGenerator.alphaNumeric(6)}`,
  } satisfies IDiscussionBoardMember.IJoin;

  const author: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: authorJoinBody,
    });
  typia.assert(author);

  // 2) Create an article as the author
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 5, wordMin: 3, wordMax: 8 }),
    content: RandomGenerator.content({
      paragraphs: 2,
      sentenceMin: 8,
      sentenceMax: 16,
      wordMin: 3,
      wordMax: 8,
    }),
    // keep as draft to avoid publication constraints
    state: "draft",
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: articleCreateBody,
    });
  typia.assert(article);
  TestValidator.equals(
    "article created id matches response",
    article.id,
    article.id,
  );

  // 3) Create a comment under the article as the author
  const commentCreateBody = {
    content: RandomGenerator.paragraph({
      sentences: 3,
      wordMin: 3,
      wordMax: 8,
    }),
  } satisfies IDiscussionBoardComment.ICreate;

  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.member.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: commentCreateBody,
      },
    );
  typia.assert(comment);

  // Record comment id for reporting
  const reportedCommentId: string & tags.Format<"uuid"> = comment.id;

  // 4) Create reporter member (this will switch the connection's Authorization header)
  const reporterJoinBody = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    href: `https://example.com/${RandomGenerator.alphaNumeric(6)}`,
    referrer: `https://ref.example.com/${RandomGenerator.alphaNumeric(6)}`,
  } satisfies IDiscussionBoardMember.IJoin;

  const reporter: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: reporterJoinBody,
    });
  typia.assert(reporter);

  // 5) Reporter files a report against the comment
  const reportCreateBody = {
    target_type: "comment",
    target_id: reportedCommentId,
    reason_category: "Harassment" as IDiscussionBoardReportReasonCategory,
    explanation: RandomGenerator.paragraph({
      sentences: 4,
      wordMin: 4,
      wordMax: 8,
    }),
  } satisfies IDiscussionBoardReport.ICreate;

  const report: IDiscussionBoardReport =
    await api.functional.discussionBoard.member.reports.create(connection, {
      body: reportCreateBody,
    });
  typia.assert(report);

  // Business validations
  TestValidator.equals(
    "report references correct target id",
    report.target_id,
    reportedCommentId,
  );
  TestValidator.equals(
    "report target_type is comment",
    report.target_type,
    "comment",
  );
  TestValidator.equals(
    "report reporter_member_id matches reporter",
    report.reporter_member_id,
    reporter.id,
  );
  TestValidator.equals("report status is pending", report.status, "pending");

  // 6) Error validations
  // 6.a Duplicate report by same reporter should fail (409 expected)
  await TestValidator.error("duplicate report should fail", async () => {
    await api.functional.discussionBoard.member.reports.create(connection, {
      body: reportCreateBody,
    });
  });

  // 6.b Unauthenticated request should fail: create a shallow copy with empty headers
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthenticated report should fail", async () => {
    await api.functional.discussionBoard.member.reports.create(unauthConn, {
      body: reportCreateBody,
    });
  });

  // 6.c Reporting a non-existent comment should fail (404/400 depending on impl)
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  const nonExistReportBody = {
    target_type: "comment",
    target_id: nonExistentId,
    reason_category: "Spam" as IDiscussionBoardReportReasonCategory,
  } satisfies IDiscussionBoardReport.ICreate;

  await TestValidator.error(
    "reporting non-existent comment should fail",
    async () => {
      await api.functional.discussionBoard.member.reports.create(connection, {
        body: nonExistReportBody,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

export async function test_api_moderator_list_sessions_by_self(
  connection: api.IConnection,
) {
  // 1. Create a new moderator account and obtain authorization
  const username = RandomGenerator.alphaNumeric(8);
  const email = typia.random<string & tags.Format<"email">>();
  const password = `${RandomGenerator.alphaNumeric(8)}Aa1!`; // >=12 chars and includes classes
  const href = typia.random<string & tags.Format<"uri">>();
  const referrer = typia.random<string & tags.Format<"uri">>();
  const ip = typia.random<string & tags.Format<"ipv4">>();

  const joinBody = {
    username,
    email,
    password,
    href,
    referrer,
    ip,
  } satisfies IDiscussionBoardModerator.ICreate;

  const authorized: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: joinBody,
    });
  // Validate authorization response shape (includes id and token)
  typia.assert(authorized);

  // 2. List sessions for the authenticated moderator
  const page: IDiscussionBoardModerator.ISessionsPage =
    await api.functional.auth.moderator.sessions.listSessions(connection);
  typia.assert(page);

  // 3. Basic pagination and data presence checks
  TestValidator.predicate(
    "pagination object exists",
    page.pagination !== null && page.pagination !== undefined,
  );

  // The SDK normally creates an initial session at join; assert at least one session exists.
  TestValidator.predicate(
    "contains at least one session",
    page.data.length >= 1,
  );

  // 4. Ensure all session items follow the session contract and belong to the created moderator
  TestValidator.predicate(
    "all sessions belong to the created moderator",
    page.data.every((s) => s.moderatorId === authorized.id),
  );

  // 5. Check each session item's field presence and types (business checks)
  TestValidator.predicate(
    "each session has expected field shapes",
    page.data.every((s) => {
      const ipOk = typeof s.ip === "string" || s.ip === null;
      const hrefOk = typeof s.href === "string";
      const referrerOk = typeof s.referrer === "string";
      const createdAtOk = typeof s.createdAt === "string";
      const expiredAtOk =
        s.expiredAt === null ||
        s.expiredAt === undefined ||
        typeof s.expiredAt === "string";
      const idOk = typeof s.id === "string";
      return ipOk && hrefOk && referrerOk && createdAtOk && expiredAtOk && idOk;
    }),
  );

  // 6. Ensure sensitive fields are NOT present on session items
  TestValidator.predicate(
    "session items do not expose sensitive fields",
    page.data.every(
      (s) => !("password_hash" in s) && !("token" in s) && !("tokens" in s),
    ),
  );

  // 7. Validate results are ordered by createdAt DESC
  const actualOrder = page.data.map((s) => s.id);
  const expectedOrder = [...page.data]
    .sort((a, b) => b.createdAt.localeCompare(a.createdAt))
    .map((s) => s.id);
  TestValidator.equals(
    "sessions ordered by createdAt desc",
    actualOrder,
    expectedOrder,
  );
}

