  } satisfies IDiscussionBoardModerator.ICreate;

  const authB: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: moderatorBBody,
    });
  typia.assert(authB);

  // List sessions for B (connection is now authenticated as B)
  const sessionsB: IDiscussionBoardModerator.ISessionsPage =
    await api.functional.auth.moderator.sessions.listSessions(connection);
  typia.assert(sessionsB);
  TestValidator.predicate(
    "moderator B should have at least one session",
    sessionsB.data.length > 0,
  );
  const sessionBId: string = sessionsB.data[0].id;

  // 3. As B, revoke B's own session
  const eraseResultB: IDiscussionBoardModerator.ISessionErasedResult =
    await api.functional.auth.moderator.sessions.eraseSession(connection, {
      sessionId: sessionBId,
    });
  typia.assert(eraseResultB);
  TestValidator.equals(
    "erase result reports erased for B",
    eraseResultB.erased,
    true,
  );
  TestValidator.equals(
    "erase result id matches revoked session",
    eraseResultB.id,
    sessionBId,
  );

  // Verify the revoked session no longer appears in B's session list
  const sessionsBAfterErase: IDiscussionBoardModerator.ISessionsPage =
    await api.functional.auth.moderator.sessions.listSessions(connection);
  typia.assert(sessionsBAfterErase);
  const existsAfter = sessionsBAfterErase.data.some((s) => s.id === sessionBId);
  TestValidator.predicate(
    "revoked session removed from B's sessions",
    !existsAfter,
  );

  // 4. Still authenticated as B, attempt to revoke A's session -> should fail
  await TestValidator.error(
    "moderator B cannot revoke moderator A's session",
    async () => {
      await api.functional.auth.moderator.sessions.eraseSession(connection, {
        sessionId: sessionAId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

export async function test_api_member_update_self_service(
  connection: api.IConnection,
) {
  // 1) Create first member (the actor who will perform self-update)
  const connA: api.IConnection = { ...connection, headers: {} };
  const usernameA = `user_${RandomGenerator.alphaNumeric(6)}`;
  const emailA = typia.random<string & tags.Format<"email">>();
  const strongPasswordA = "Aa1!" + RandomGenerator.alphaNumeric(8); // 12 chars, includes upper/lower/number/symbol

  const joinBodyA = {
    username: usernameA,
    email: emailA,
    password: strongPasswordA,
    href: "https://example.com/welcome",
    referrer: "https://example.com/",
    display_name: RandomGenerator.name(),
  } satisfies IDiscussionBoardMember.IJoin;

  const authA: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connA, { body: joinBodyA });
  typia.assert(authA);

  const memberUsername = authA.username;

  // 2) Successful self-update: change display_name and password
  const newDisplayName = RandomGenerator.name();
  const newStrongPassword = "Aa1!" + RandomGenerator.alphaNumeric(8);
  const updateBody = {
    display_name: newDisplayName,
    password: newStrongPassword,
    revokeSessions: true,
  } satisfies IDiscussionBoardMember.IUpdate;

  const updated: IDiscussionBoardMember =
    await api.functional.discussionBoard.member.members.update(connA, {
      memberUsername,
      body: updateBody,
    });
  typia.assert(updated);

  // Validate business expectations
  TestValidator.equals(
    "display_name updated",
    updated.display_name,
    updateBody.display_name,
  );
  TestValidator.predicate(
    "updated_at is newer than created_at",
    new Date(updated.updated_at) > new Date(authA.created_at),
  );

  // Ensure sensitive credential field is not present in the response object
  TestValidator.predicate(
    "response does not include password_hash",
    Object.keys(updated).includes("password_hash") === false,
  );

  // 3) Negative case: attempt update without authorization
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "update without authorization should fail",
    async () => {
      await api.functional.discussionBoard.member.members.update(unauthConn, {
        memberUsername,
        body: {
          display_name: RandomGenerator.name(),
        } satisfies IDiscussionBoardMember.IUpdate,
      });
    },
  );

  // 4) Negative case: attempt update as a different member
  const connB: api.IConnection = { ...connection, headers: {} };
  const usernameB = `user_${RandomGenerator.alphaNumeric(6)}`;
  const emailB = typia.random<string & tags.Format<"email">>();
  const passwordB = "Bb1!" + RandomGenerator.alphaNumeric(8);

  const joinBodyB = {
    username: usernameB,
    email: emailB,
    password: passwordB,
    href: "https://example.com/welcome",
    referrer: "https://example.com/",
  } satisfies IDiscussionBoardMember.IJoin;

  const authB: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connB, { body: joinBodyB });
  typia.assert(authB);

  await TestValidator.error(
    "other authenticated member cannot update target member",
    async () => {
      await api.functional.discussionBoard.member.members.update(connB, {
        memberUsername,
        body: {
          display_name: "attempted-hijack",
        } satisfies IDiscussionBoardMember.IUpdate,
      });
    },
  );

  // 5) Negative case: weak password should be rejected by server-side policy
  await TestValidator.error("weak password should be rejected", async () => {
    await api.functional.discussionBoard.member.members.update(connA, {
      memberUsername,
      body: { password: "weakpass" } satisfies IDiscussionBoardMember.IUpdate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardNotificationFailure } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationFailure";
import type { IDiscussionBoardSubscription } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSubscription";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardNotificationFailure } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardNotificationFailure";

export async function test_api_notification_failures_listing_by_member(
  connection: api.IConnection,
) {
  // 1) Create an isolated member account (owner)
  const ownerJoinBody = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: "P@ssw0rd1234",
    href: "http://example.com",
    referrer: "http://example.com",
  } satisfies IDiscussionBoardMember.IJoin;

  const owner: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, { body: ownerJoinBody });
  typia.assert(owner);

  // 2) Create an article as the owner to provide realistic context
  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 5, wordMin: 5, wordMax: 10 }),
    content: RandomGenerator.content({ paragraphs: 2 }),
    category_slug: null,
    tag_slugs: undefined,
    state: "draft",
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: articleBody,
    });
  typia.assert(article);

  // 3) Create a subscription so the notification pipeline logically targets the owner
  const subscriptionBody = {
    target_type: "article",
    target_id: article.id,
    delivery_mode: "immediate",
    active: true,
  } satisfies IDiscussionBoardSubscription.ICreate;

  const subscription: IDiscussionBoardSubscription =
    await api.functional.discussionBoard.member.members.subscriptions.create(
      connection,
      {
        memberUsername: owner.username,
        body: subscriptionBody,
      },
    );
  typia.assert(subscription);

  // 4) Prepare a notificationId (UUID). In environments without a test hook,
  //    we'll use a generated UUID and validate listing behavior and filtering semantics.
  const notificationId = typia.random<string & tags.Format<"uuid">>();

  // 5) Call the failures listing endpoint as the owner and validate the response envelope
  const pageRequest = {
    page: 1,
    limit: 5,
  } satisfies IDiscussionBoardNotificationFailure.IRequest;

  const failuresPage: IPageIDiscussionBoardNotificationFailure.ISummary =
    await api.functional.discussionBoard.member.members.notifications.failures.index(
      connection,
      {
        memberUsername: owner.username,
        notificationId,
        body: pageRequest,
      },
    );
  typia.assert(failuresPage);

  // Validate pagination basic invariants
  TestValidator.equals(
    "pagination.current should be 1",
    failuresPage.pagination.current,
    1,
  );
  TestValidator.predicate(
    "pagination.limit is positive",
    failuresPage.pagination.limit > 0,
  );
  TestValidator.predicate(
    "pagination.pages is non-negative",
    failuresPage.pagination.pages >= 0,
  );

  // 6) If any returned item has an errorCode, test the errorCode filter semantics
  if (failuresPage.data.length > 0) {
    const sampleWithError = failuresPage.data.find(
      (d) => d.errorCode !== null && d.errorCode !== undefined,
    );

    if (sampleWithError) {
      const code = sampleWithError.errorCode!;
      const filteredRequest = {
        page: 1,
        limit: 10,
        errorCode: code,
      } satisfies IDiscussionBoardNotificationFailure.IRequest;

      const filtered: IPageIDiscussionBoardNotificationFailure.ISummary =
        await api.functional.discussionBoard.member.members.notifications.failures.index(
          connection,
          {
            memberUsername: owner.username,
            notificationId,
            body: filteredRequest,
          },
        );
      typia.assert(filtered);

      TestValidator.predicate(
        `all returned items must have errorCode ${code}`,
        filtered.data.every((d) => d.errorCode === code),
      );
    } else {
      // No records with errorCode present; mark as informational success
      TestValidator.predicate(
        "no failure records with errorCode to test filter",
        true,
      );
    }
  }

  // 7) Authorization boundary: create another member and assert non-owner access is rejected
  const otherJoinBody = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: "P@ssw0rd1234",
    href: "http://example.com",
    referrer: "http://example.com",
  } satisfies IDiscussionBoardMember.IJoin;

  const otherMember: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, { body: otherJoinBody });
  typia.assert(otherMember);

  // Now the connection is authenticated as otherMember. Attempting to list owner failures
  // should be rejected by authorization checks (401/403). We assert that an error occurs.
  await TestValidator.error(
    "non-owner cannot access another member's notification failures",
    async () => {
      await api.functional.discussionBoard.member.members.notifications.failures.index(
        connection,
        {
          memberUsername: owner.username,
          notificationId,
          body: {
            page: 1,
          } satisfies IDiscussionBoardNotificationFailure.IRequest,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
