      body: reportBody,
    });
  typia.assert(report);

  // 6) Moderator registration
  const moderatorBody = {
    username: `mod_${RandomGenerator.alphaNumeric(6)}`,
    email: `${RandomGenerator.name(1).replace(/\s+/g, "").toLowerCase()}+mod@example.com`,
    password: RandomGenerator.alphaNumeric(12),
