  // Basic pagination metadata assertions
  TestValidator.equals(
    "pagination current page is requested page",
    auditPage.pagination.current,
    pageNumber,
  );
  TestValidator.equals(
    "pagination limit matches requested limit",
    auditPage.pagination.limit,
    pageLimit,
  );
  TestValidator.predicate(
    "pagination records should be non-negative",
    auditPage.pagination.records >= 0,
  );

  // Data assertions: length should be <= limit and every result belongs to the moderator
  TestValidator.predicate(
    "data length less or equal to limit",
    auditPage.data.length <= pageLimit,
  );

  if (auditPage.data.length > 0) {
    for (const item of auditPage.data) {
      // Prefer actor_moderator_id when available; otherwise check actor_moderator summary
      if (
        item.actor_moderator_id !== null &&
        item.actor_moderator_id !== undefined
      ) {
        TestValidator.equals(
          "audit actor moderator id matches",
          item.actor_moderator_id,
          moderator.id,
        );
      } else if (item.actor_moderator) {
        TestValidator.equals(
          "audit actor moderator summary id matches",
          item.actor_moderator.id,
          moderator.id,
        );
      } else if (item.moderation_action) {
        // As a last resort, check embedded moderation_action.moderator.id if present
        TestValidator.predicate(
          "embedded moderation action contains moderator summary or id",
          item.moderation_action !== null &&
            item.moderation_action !== undefined,
        );
      }

      // Ensure event_type reflects moderation action or that moderation_action exists
      TestValidator.predicate(
        "audit item has moderation action context",
        item.event_type === "moderation.action" ||
          (item.moderation_action !== null &&
            item.moderation_action !== undefined),
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

export async function test_api_moderator_join_success(
  connection: api.IConnection,
) {
  // 1) Prepare unique registration data
  const username = `mod_${RandomGenerator.alphaNumeric(8)}`;
  const email = typia.random<string & tags.Format<"email">>();
  const password = `${RandomGenerator.alphaNumeric(8)}!A1`; // at least 12 chars: combine later
  const strongPassword =
    password.length >= 12
      ? password
      : password + RandomGenerator.alphaNumeric(12 - password.length);
  const display_name = RandomGenerator.name();
  const href = typia.random<string & tags.Format<"uri">>();
  const referrer = typia.random<string & tags.Format<"uri">>();

  const createBody = {
    username,
    email,
    password: strongPassword,
    display_name,
    href,
    referrer,
  } satisfies IDiscussionBoardModerator.ICreate;

  // 2) Call join API and validate successful authorization response
  const authorized: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: createBody,
    });

  // Runtime type validation
  typia.assert(authorized);
  typia.assert<IAuthorizationToken>(authorized.token);

  // 3) Business assertions
  TestValidator.equals(
    "returned username matches request",
    authorized.username,
    username,
  );
  // display_name may be optional in response; if present, ensure it matches
  if (
    authorized.display_name !== undefined &&
    authorized.display_name !== null
  ) {
    TestValidator.equals(
      "returned display_name matches request",
      authorized.display_name,
      display_name,
    );
  }

  // Token basic format checks (JWT-like: contains at least two dots)
  TestValidator.predicate(
    "access token looks like JWT",
    typeof authorized.token.access === "string" &&
      authorized.token.access.includes(".") &&
      authorized.token.access.length > 20,
  );
  TestValidator.predicate(
    "refresh token looks like token string",
    typeof authorized.token.refresh === "string" &&
      authorized.token.refresh.length > 20,
  );

  // created_at / updated_at should be present and valid date-time strings (typia.assert already validated formats)
  TestValidator.predicate(
    "created_at present",
    typeof authorized.created_at === "string" &&
      authorized.created_at.length > 0,
  );
  TestValidator.predicate(
    "updated_at present",
    typeof authorized.updated_at === "string" &&
      authorized.updated_at.length > 0,
  );

  // 4) Security: ensure password_hash is NOT exposed in response object
  TestValidator.predicate(
    "password_hash not exposed",
    !("password_hash" in (authorized as any)),
  );

  // 5) Duplicate username should be rejected (409)
  const dupByUsername = {
    username,
    email: typia.random<string & tags.Format<"email">>(), // different email
    password: strongPassword,
    href,
    referrer,
  } satisfies IDiscussionBoardModerator.ICreate;

  await TestValidator.httpError(
    "duplicate username should return 409",
    409,
    async () => {
      await api.functional.auth.moderator.join(connection, {
        body: dupByUsername,
      });
    },
  );

  // 6) Duplicate email should be rejected (409)
  const dupByEmail = {
    username: `mod_${RandomGenerator.alphaNumeric(8)}`,
    email,
    password: strongPassword,
    href,
    referrer,
  } satisfies IDiscussionBoardModerator.ICreate;

  await TestValidator.httpError(
    "duplicate email should return 409",
    409,
    async () => {
      await api.functional.auth.moderator.join(connection, {
        body: dupByEmail,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Validate moderator authentication using existing account flow.
 *
 * Business context:
 *
 * 1. Create a moderator via /auth/moderator/join (self-join scenario).
 * 2. Authenticate using /auth/moderator/login with the same credentials.
 * 3. Verify returned authorization tokens and that the authenticated moderator
 *    matches the created account.
 * 4. Negative case: assert that incorrect password is rejected.
 *
 * Notes:
 *
 * - The test uses only api.functional.auth.moderator.join and
 *   api.functional.auth.moderator.login as provided by the SDK.
 * - All request bodies use `satisfies` with the correct DTO types.
 * - All non-void responses are validated with typia.assert().
 * - Do NOT touch connection.headers; the SDK manages Authorization headers.
 */
export async function test_api_moderator_login_existing(
  connection: api.IConnection,
) {
  // 1) Prepare realistic moderator credentials
  const username = `mod_${RandomGenerator.alphaNumeric(8)}`;
  const email = `${RandomGenerator.alphaNumeric(6)}@example.com`;
  // Construct a password >= 12 chars with mixed characters to respect policy
  const password = `Aa1!${RandomGenerator.alphaNumeric(8)}`; // 4 + 8 = 12 chars

  const href = typia.random<string & tags.Format<"uri">>();
  const referrer = typia.random<string & tags.Format<"uri">>();

  // 2) Create moderator account via join
  const joinBody = {
    username,
    email,
    password,
    display_name: RandomGenerator.name(),
    href,
    referrer,
  } satisfies IDiscussionBoardModerator.ICreate;

  const created: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: joinBody,
    });
  typia.assert(created);

  // Basic business assertions about join response
  TestValidator.predicate(
    "join returned an access token",
    typeof created.token?.access === "string" &&
      created.token.access.length > 0,
  );
  TestValidator.predicate(
    "join returned a refresh token",
    typeof created.token?.refresh === "string" &&
      created.token.refresh.length > 0,
  );
  // created.id must exist and be a string (typia.assert ensured it), store for later

  // 3) Successful login using username and password
  const loginBody = {
    usernameOrEmail: username,
    password,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardModerator.ILogin;

  const logged: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.login(connection, {
      body: loginBody,
    });
  typia.assert(logged);

  // Business validations for successful login
  TestValidator.equals(
    "login returns same moderator id as join",
    logged.id,
    created.id,
  );

  TestValidator.predicate(
    "login returned non-empty access and refresh tokens",
    typeof logged.token.access === "string" &&
      logged.token.access.length > 0 &&
      typeof logged.token.refresh === "string" &&
      logged.token.refresh.length > 0,
  );

  // Validate token metadata presence (expired_at and refreshable_until)
  TestValidator.predicate(
    "token contains expiration metadata",
    typeof logged.token.expired_at === "string" &&
      logged.token.expired_at.length > 0 &&
      typeof logged.token.refreshable_until === "string" &&
      logged.token.refreshable_until.length > 0,
  );

  // 4) Negative case: incorrect password should fail (business error)
  await TestValidator.error(
    "login with incorrect password should be rejected",
    async () => {
      await api.functional.auth.moderator.login(connection, {
        body: {
          usernameOrEmail: username,
          password: `${password}__wrong`,
          href: typia.random<string & tags.Format<"uri">>(),
          referrer: typia.random<string & tags.Format<"uri">>(),
        } satisfies IDiscussionBoardModerator.ILogin,
      });
    },
  );

  // Security note: IDiscussionBoardModerator.IAuthorized does not include
  // password_hash; typia.assert ensures that no sensitive fields are present
  // in the returned response shape. No further assertions about internal
  // storage are performed here because that would require direct DB access.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

export async function test_api_moderator_login_failure_modes(
  connection: api.IConnection,
) {
  /**
   * Purpose:
   *
   * - Create a moderator account via POST /auth/moderator/join
   * - Repeatedly attempt login with an incorrect password using an
   *   unauthenticated connection to observe brute-force protections
   *   (rate-limiting/lockout)
   * - Compare failure behavior for an existing account and a non-existent
   *   identifier to ensure failures are generic
   *
   * Notes:
   *
   * - Do NOT inspect HTTP status codes or error messages (forbidden)
   * - Use typia.assert for response validation and TestValidator.error for
   *   asserting that login attempts throw
   */

  // 1) Create moderator account
  const username = `mod_${RandomGenerator.alphaNumeric(8)}`;
  const email = typia.random<string & tags.Format<"email">>();
  const password = "P@ssw0rd1234"; // 13 chars, contains upper/lower/number/symbol
  const href = "https://example.com/login";
  const referrer = "https://referrer.example.com/";

  const createBody = {
    username,
    email,
    password,
    display_name: RandomGenerator.name(),
    ip: null,
    href,
    referrer,
  } satisfies IDiscussionBoardModerator.ICreate;

  const created: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: createBody,
    });
  // Validate returned shape
  typia.assert(created);
  TestValidator.equals(
    "created moderator username matches request",
    created.username,
    createBody.username,
  );

  // 2) Prepare unauthenticated connection (SDK-managed headers must not be touched)
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  // 3) Prepare a wrong-login payload (must satisfy ILogin)
  const wrongLogin = {
    usernameOrEmail: createBody.username,
    password: "WrongPassw0rd!", // >=12 chars, incorrect password
    mfa_code: null,
    ip: null,
    href: createBody.href,
    referrer: createBody.referrer,
  } satisfies IDiscussionBoardModerator.ILogin;

  // 4) Repeated failed login attempts to exercise rate-limiting / lockout behavior
  const attempts = 5;
  for (let i = 1; i <= attempts; ++i) {
    await TestValidator.error(
      `failed login attempt #${i} should throw`,
      async () => {
        await api.functional.auth.moderator.login(unauthConn, {
          body: wrongLogin,
        });
      },
    );
  }

  // 5) Additional attempt after repeated failures: expect failure as well
  await TestValidator.error(
    "post-threshold login attempt should still fail",
    async () => {
      await api.functional.auth.moderator.login(unauthConn, {
        body: wrongLogin,
      });
    },
  );

  // 6) Compare with a non-existent identifier to verify generic failure behavior
  const nonExistentLogin = {
    usernameOrEmail: typia.random<string>(),
    password: "AnotherWrong1!",
    mfa_code: null,
    ip: null,
    href: createBody.href,
    referrer: createBody.referrer,
  } satisfies IDiscussionBoardModerator.ILogin;

  await TestValidator.error(
    "login with non-existent account should also throw (generic)",
    async () => {
      await api.functional.auth.moderator.login(unauthConn, {
        body: nonExistentLogin,
      });
    },
  );

  // 7) Final predicate: both known-wrong and unknown credentials produced errors
  // (We rely on TestValidator.error checks above; add a final sanity predicate)
  TestValidator.predicate(
    "completed brute-force simulation without leaking types",
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportReasonCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportReasonCategory";
import type { IDiscussionBoardReportStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportStatus";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardReport";

export async function test_api_moderator_reports_search(
  connection: api.IConnection,
) {
  /**
   * E2E: Moderator report search and filtering
   *
   * Steps implemented:
   *
   * 1. Create a member account and authenticate (SDK sets Authorization header)
   * 2. As that member, create an article
   * 3. Create a comment under the article
   * 4. Submit two reports as the member: one for the article (Spam) and one for
   *    the comment (Harassment)
   * 5. Assert member cannot call moderator search (RBAC enforcement)
   * 6. Create a moderator account and authenticate
   * 7. As moderator, call moderator reports index with filters and assert:
   *
   *    - Typia.assert on response
   *    - Pagination meta exists and limit respects server max (<= 100)
   *    - Response.data contains the created reports according to filters
   *    - Summary does not expose reporter_session_id
   * 8. Negative cases: invalid pagination (page=0) -> expect error; unsupported
   *    sort token -> expect error
   */

  // 1) Member sign-up
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: {
        username: RandomGenerator.name(1) + Date.now().toString().slice(-4),
        email: memberEmail,
        password: RandomGenerator.alphaNumeric(12),
        href: "https://example.com/",
        referrer: "https://example.com/ref",
      } satisfies IDiscussionBoardMember.IJoin,
    });
  typia.assert(member);

  // 2) Create an article as member
  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 6,
          wordMin: 4,
          wordMax: 10,
        }),
        content: RandomGenerator.content({ paragraphs: 2 }),
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(article);

  // 3) Create a comment under that article
  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.member.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: {
          content: RandomGenerator.paragraph({ sentences: 3 }),
          parentCommentId: null,
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment);

  // 4) Submit reports: one for article, one for comment
  const articleReport: IDiscussionBoardReport =
    await api.functional.discussionBoard.member.reports.create(connection, {
      body: {
        target_type: "article",
        target_id: article.id,
        reason_category: "Spam",
        explanation: RandomGenerator.paragraph({ sentences: 4 }),
      } satisfies IDiscussionBoardReport.ICreate,
    });
  typia.assert(articleReport);

  const commentReport: IDiscussionBoardReport =
    await api.functional.discussionBoard.member.reports.create(connection, {
      body: {
        target_type: "comment",
        target_id: comment.id,
        reason_category: "Harassment",
        explanation: RandomGenerator.paragraph({ sentences: 4 }),
      } satisfies IDiscussionBoardReport.ICreate,
    });
  typia.assert(commentReport);

  // 5) RBAC: member should NOT be allowed to call moderator endpoint
  await TestValidator.error(
    "member cannot access moderator report search",
    async () => {
      await api.functional.discussionBoard.moderator.reports.index(connection, {
        body: {
          page: 1,
          limit: 10,
        } satisfies IDiscussionBoardReport.IRequest,
      });
    },
  );

  // 6) Create moderator account and authenticate (SDK will set Authorization header)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        username:
          RandomGenerator.name(1) + "_mod" + Date.now().toString().slice(-3),
        email: moderatorEmail,
        password: RandomGenerator.alphaNumeric(12),
        href: "https://example.com/mod",
        referrer: "https://example.com/ref",
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // 7) Moderator: Search reports with filters
  const requestedLimit = 20;
  const pageResult: IPageIDiscussionBoardReport.ISummary =
    await api.functional.discussionBoard.moderator.reports.index(connection, {
      body: {
        page: 1,
        limit: requestedLimit,
        targetType: "article",
        reasonCategory: "Spam",
        search: null,
        includeClosed: false,
      } satisfies IDiscussionBoardReport.IRequest,
    });
  typia.assert(pageResult);

  // Validate pagination metadata
  TestValidator.predicate(
    "pagination present",
    pageResult.pagination !== null && pageResult.pagination !== undefined,
  );
  TestValidator.predicate(
    "limit respects server max page size",
    pageResult.pagination.limit <= 100,
  );

  // The moderator requested targetType 'article' and reasonCategory 'Spam'
  const foundArticleReport = pageResult.data.find(
    (s) => s.targetId === article.id && s.targetType === "article",
  );
  TestValidator.predicate(
    "response contains created article report",
    foundArticleReport !== undefined,
  );

  // Summary must not expose reporter_session_id and must include expected fields
  if (foundArticleReport) {
    // reporter_session_id must not be present on summary object
    TestValidator.predicate(
      "reporter_session_id not exposed in summary",
      !Object.prototype.hasOwnProperty.call(
        foundArticleReport,
        "reporter_session_id",
      ),
    );

    // Ensure required summary fields exist
    TestValidator.predicate(
      "summary has reporterMemberId",
      (foundArticleReport.reporterMemberId !== undefined &&
        foundArticleReport.reporterMemberId !== null) ||
        foundArticleReport.reporter !== undefined,
    );
    TestValidator.predicate(
      "summary has targetType",
      foundArticleReport.targetType === "article",
    );
    TestValidator.predicate(
      "summary has targetId",
      foundArticleReport.targetId === article.id,
    );
    TestValidator.predicate(
      "summary has reasonCategory",
      foundArticleReport.reasonCategory === "Spam",
    );
    TestValidator.predicate(
      "summary has createdAt",
      !!foundArticleReport.createdAt,
    );
    TestValidator.predicate(
      "summary has explanation excerpt",
      foundArticleReport.explanationExcerpt === null ||
        typeof foundArticleReport.explanationExcerpt === "string",
    );
  }

  // Additional filtering exercise: request comments only and ensure comment report is returned
  const commentPage: IPageIDiscussionBoardReport.ISummary =
    await api.functional.discussionBoard.moderator.reports.index(connection, {
      body: {
        page: 1,
        limit: 10,
        targetType: "comment",
        reasonCategory: "Harassment",
      } satisfies IDiscussionBoardReport.IRequest,
    });
  typia.assert(commentPage);
  const foundCommentReport = commentPage.data.find(
    (s) => s.targetId === comment.id && s.targetType === "comment",
  );
  TestValidator.predicate(
    "response contains created comment report",
    foundCommentReport !== undefined,
  );

  // 8) Negative cases
  // invalid page (page=0) should result in 400
  await TestValidator.error(
    "invalid page (0) should return error",
    async () => {
      await api.functional.discussionBoard.moderator.reports.index(connection, {
        body: {
          page: 0,
          limit: 10,
        } satisfies IDiscussionBoardReport.IRequest,
      });
    },
  );

  // unsupported sort token should produce 400
  await TestValidator.error(
    "unsupported sort token should return error",
    async () => {
      await api.functional.discussionBoard.moderator.reports.index(connection, {
        body: {
          page: 1,
          limit: 10,
          sortBy: "unsupported_sort",
        } satisfies IDiscussionBoardReport.IRequest,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
