import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardNotificationFailure } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationFailure";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function getDiscussionBoardMemberMembersMemberUsernameNotificationsNotificationIdFailuresAttemptNumber(props: {
  member: MemberPayload;
  memberUsername: string;
  notificationId: string & tags.Format<"uuid">;
  attemptNumber: number & tags.Type<"int32">;
}): Promise<IDiscussionBoardNotificationFailure> {
  const { member, memberUsername, notificationId, attemptNumber } = props;

  // Business validation: attemptNumber must be a positive integer
  if (attemptNumber < 1) {
    throw new HttpException("Invalid attempt number", 400);
  }

  // Verify the username exists and obtain its member id
  const targetMember =
    await MyGlobal.prisma.discussion_board_member.findUniqueOrThrow({
      where: { username: memberUsername },
      select: { id: true },
    });

  // Load the notification and ensure it exists
  const notification =
    await MyGlobal.prisma.discussion_board_notifications.findUniqueOrThrow({
      where: { id: notificationId },
      select: { id: true, recipient_member_id: true },
    });

  // If the notification is not associated with the provided username, respond 404
  if (notification.recipient_member_id !== targetMember.id) {
    throw new HttpException("Not Found", 404);
  }

  // Authorization: ensure the authenticated member is the owner of the notification
  if (member.id !== notification.recipient_member_id) {
    throw new HttpException(
      "Unauthorized: You can only view your own notification failures",
      403,
    );
  }

  // Retrieve the specific failure record using composite key (notification id + attempt number)
  const failure =
    await MyGlobal.prisma.discussion_board_notification_failures.findFirstOrThrow(
      {
        where: {
          discussion_board_notification_id: notificationId,
          attempt_number: attemptNumber,
        },
        select: {
          id: true,
          discussion_board_notification_id: true,
          attempt_number: true,
          attempted_at: true,
          error_code: true,
          error_message: true,
          backoff_until: true,
          created_at: true,
        },
      },
    );

  // Map DB fields to API DTO, converting Date -> ISO strings using toISOStringSafe
  return {
    id: failure.id as string & tags.Format<"uuid">,
    notificationId: failure.discussion_board_notification_id as string &
      tags.Format<"uuid">,
    attemptNumber: failure.attempt_number satisfies number as number,
    attemptedAt: toISOStringSafe(failure.attempted_at),
    errorCode: failure.error_code ?? null,
    errorMessage: failure.error_message ?? null,
    backoffUntil: failure.backoff_until
      ? toISOStringSafe(failure.backoff_until)
      : null,
    createdAt: toISOStringSafe(failure.created_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardSubscription } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSubscription";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

export async function getDiscussionBoardMemberMembersMemberUsernameSubscriptionsTargetTypeTargetId(props: {
  memberUsername: string;
  targetType: string;
  targetId: string & tags.Format<"uuid">;
}): Promise<IDiscussionBoardSubscription> {
  const { memberUsername, targetType, targetId } = props;

  // Business-level validation for allowed subscription target types
  if (targetType !== "article" && targetType !== "author")
    throw new HttpException("Bad Request: unsupported targetType", 400);

  // Resolve member by username
  const member = await MyGlobal.prisma.discussion_board_member.findUnique({
    where: { username: memberUsername },
    select: { id: true, username: true, display_name: true, created_at: true },
  });

  if (!member) throw new HttpException("Not Found: member does not exist", 404);

  // Retrieve subscription matching member id, target type and target id
  const subscription =
    await MyGlobal.prisma.discussion_board_subscriptions.findFirst({
      where: {
        discussion_board_member_id: member.id,
        target_type: targetType,
        target_id: targetId,
      },
      select: {
        id: true,
        discussion_board_member_id: true,
        target_type: true,
        target_id: true,
        delivery_mode: true,
        active: true,
        last_notified_at: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
      },
    });

  if (!subscription)
    throw new HttpException("Not Found: subscription does not exist", 404);

  // Treat soft-deleted subscription as not found for member reads
  if (subscription.deleted_at !== null)
    throw new HttpException("Not Found: subscription does not exist", 404);

  // Map database fields to API DTO and convert Date fields to ISO strings
  return {
    id: subscription.id as string & tags.Format<"uuid">,
    member: {
      id: member.id as string & tags.Format<"uuid">,
      username: member.username,
      display_name: member.display_name === null ? null : member.display_name,
      created_at: toISOStringSafe(member.created_at),
    },
    // Narrow literal string fields using typia.assert at the individual property level
    targetType: typia.assert<"author" | "article">(subscription.target_type),
    targetId: subscription.target_id as string & tags.Format<"uuid">,
    deliveryMode: typia.assert<"immediate" | "daily_digest">(
      subscription.delivery_mode,
    ),
    active: subscription.active,
    lastNotifiedAt: subscription.last_notified_at
      ? toISOStringSafe(subscription.last_notified_at)
      : null,
    createdAt: toISOStringSafe(subscription.created_at),
    updatedAt: subscription.updated_at
      ? toISOStringSafe(subscription.updated_at)
      : null,
    deletedAt: subscription.deleted_at
      ? toISOStringSafe(subscription.deleted_at)
      : null,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IPageIDiscussionBoardArticleSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticleSnapshot";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IDiscussionBoardArticleSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleSnapshot";
import { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function getDiscussionBoardModeratorArticlesArticleIdVersions(props: {
  moderator: ModeratorPayload;
  articleId: string & tags.Format<"uuid">;
  page: number & tags.Type<"int32">;
  limit: number & tags.Type<"int32">;
  sort: string;
}): Promise<IPageIDiscussionBoardArticleSnapshot.ISummary> {
  const { moderator, articleId, page: rawPage, limit: rawLimit, sort } = props;

  // Authorization: ensure moderator exists and is active
  const moderatorExists =
    await MyGlobal.prisma.discussion_board_moderator.findFirst({
      where: { id: moderator.id, deleted_at: null },
    });
  if (!moderatorExists) throw new HttpException("Forbidden", 403);

  // Pagination normalization and validation (business logic)
  const page = Number(rawPage) || 1;
  const limit = Number(rawLimit) || 20;
  if (page < 1) throw new HttpException("Bad Request: page must be >= 1", 400);
  if (limit < 1 || limit > 100)
    throw new HttpException(
      "Bad Request: limit must be between 1 and 100",
      400,
    );

  const skip = (page - 1) * limit;

  // Determine order inline (only snapshot_at supported)
  const orderByClause: Prisma.discussion_board_article_snapshotsOrderByWithRelationInput =
    sort &&
    typeof sort === "string" &&
    sort.replace(/^[-+]/, "") === "snapshot_at"
      ? sort.startsWith("-")
        ? { snapshot_at: "desc" as Prisma.SortOrder }
        : { snapshot_at: "asc" as Prisma.SortOrder }
      : { snapshot_at: "desc" as Prisma.SortOrder };

  // Count total snapshots for pagination
  const total = await MyGlobal.prisma.discussion_board_article_snapshots.count({
    where: { discussion_board_article_id: articleId },
  });

  // Fetch snapshots page
  const rows =
    await MyGlobal.prisma.discussion_board_article_snapshots.findMany({
      where: { discussion_board_article_id: articleId },
      orderBy: orderByClause,
      skip,
      take: limit,
    });

  // Map Prisma results to DTOs with careful null/undefined handling
  const data: IDiscussionBoardArticleSnapshot.ISummary[] = rows.map((r) => {
    // Build minimal article summary from denormalized snapshot fields
    const article: IDiscussionBoardArticle.ISummary = {
      id: r.discussion_board_article_id,
      title: r.title,
      excerpt: r.content ? r.content.slice(0, 200) : undefined,
      author: undefined,
      isPinned: undefined,
      publishedAt: undefined,
      createdAt: toISOStringSafe(r.created_at),
      updatedAt: r.updated_at ? toISOStringSafe(r.updated_at) : undefined,
      category: undefined,
    };

    const snapshot: IDiscussionBoardArticleSnapshot.ISummary = {
      id: r.id,
      article,
      title: r.title,
      snapshot_at: toISOStringSafe(r.snapshot_at),
      created_at: toISOStringSafe(r.created_at),
      state: typia.assert<"draft" | "published" | "pending_review" | "hidden">(
        r.state,
      ),
      content_excerpt: r.content ? r.content.slice(0, 200) : undefined,
      updated_at: r.updated_at ? toISOStringSafe(r.updated_at) : undefined,
      deleted_at: r.deleted_at ? toISOStringSafe(r.deleted_at) : null,
    };

    return snapshot;
  });

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / Number(limit)),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardModerationOverview } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationOverview";
import { IKeyValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IKeyValue";
import { IProcessingTime } from "@ORGANIZATION/PROJECT-api/lib/structures/IProcessingTime";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function getDiscussionBoardModeratorDashboardModerationOverview(props: {
  moderator: ModeratorPayload;
}): Promise<IDiscussionBoardModerationOverview> {
  const { moderator } = props;

  // Authorization: ensure moderator exists and not soft-deleted
  const foundModerator =
    await MyGlobal.prisma.discussion_board_moderator.findFirst({
      where: { id: moderator.id, deleted_at: null },
      select: { id: true },
    });
  if (!foundModerator) {
    throw new HttpException(
      "Unauthorized: moderator not found or inactive",
      403,
    );
  }

  try {
    // Time window boundaries as ISO strings
    const nowIso = toISOStringSafe(new Date());
    const iso24h = toISOStringSafe(new Date(Date.now() - 24 * 60 * 60 * 1000));
    const iso7d = toISOStringSafe(
      new Date(Date.now() - 7 * 24 * 60 * 60 * 1000),
    );

    // Parallel basic aggregations
    const [pending24, pending7, actionGroups, recentReports, recentAudits] =
      await Promise.all([
        MyGlobal.prisma.discussion_board_reports.count({
          where: { status: "pending", created_at: { gte: iso24h } },
        }),
        MyGlobal.prisma.discussion_board_reports.count({
          where: { status: "pending", created_at: { gte: iso7d } },
        }),
        // Group by action_type for breakdown
        MyGlobal.prisma.discussion_board_moderation_actions.groupBy({
          by: ["action_type"],
          _count: { action_type: true },
        }),
        // Fetch recent processed reports for processing-time metrics (limit to recent 1000)
        MyGlobal.prisma.discussion_board_reports.findMany({
          where: { processed_at: { not: null }, created_at: { gte: iso7d } },
          select: {
            id: true,
            created_at: true,
            processed_at: true,
            closed_at: true,
          },
          take: 1000,
        }),
        // Recent high-priority audits
        MyGlobal.prisma.discussion_board_moderation_audit.findMany({
          where: {
            event_type: {
              in: ["moderation.action", "report.filed", "appeal.submitted"],
            },
          },
          orderBy: { occurred_at: "desc" },
          take: 10,
          select: {
            id: true,
            event_type: true,
            occurred_at: true,
            event_payload: true,
          },
        }),
      ]);

    // Build actions_breakdown
    const actions_breakdown: IKeyValue[] = actionGroups.map((g) => ({
      key: g.action_type,
      value: Number(g._count.action_type),
    }));

    // Processing time calculations
    const reportIds = recentReports.map((r) => r.id);
    let average_processing_times: IProcessingTime[] = [];

    if (reportIds.length > 0) {
      const actions =
        await MyGlobal.prisma.discussion_board_moderation_actions.findMany({
          where: { discussion_board_report_id: { in: reportIds } },
          select: { discussion_board_report_id: true, created_at: true },
          orderBy: { created_at: "asc" },
        });

      // earliest action per report
      const earliestActionByReport: Record<string, Date> = {} as Record<
        string,
        Date
      >;
      for (const a of actions) {
        const rid = a.discussion_board_report_id;
        // Only use rid as an object key when it is a non-null string
        if (rid !== null && rid !== undefined) {
          if (!earliestActionByReport[rid]) {
            earliestActionByReport[rid] = a.created_at;
          }
        }
      }

      // compute time_to_first_action (in seconds)
      const firstActionDiffs: number[] = [];
      const resolutionDiffs: number[] = [];

      for (const r of recentReports) {
        const reportId = r.id;
        if (reportId !== null && reportId !== undefined) {
          const ea = earliestActionByReport[reportId];
          if (ea) {
            const diffSec = (ea.getTime() - r.created_at.getTime()) / 1000;
            if (Number.isFinite(diffSec) && diffSec >= 0)
              firstActionDiffs.push(diffSec);
          }
        }

        if (r.closed_at) {
          const diffRes =
            (r.closed_at.getTime() - r.created_at.getTime()) / 1000;
          if (Number.isFinite(diffRes) && diffRes >= 0)
            resolutionDiffs.push(diffRes);
        }
      }

      if (firstActionDiffs.length > 0) {
        const avg =
          firstActionDiffs.reduce((a, b) => a + b, 0) / firstActionDiffs.length;
        average_processing_times.push({
          metric: "time_to_first_action",
          value_seconds: avg,
        });
      }
      if (resolutionDiffs.length > 0) {
        const avgRes =
          resolutionDiffs.reduce((a, b) => a + b, 0) / resolutionDiffs.length;
        average_processing_times.push({
          metric: "time_to_resolution",
          value_seconds: avgRes,
        });
      }
    }

    // Sanitize recent audits into lightweight summaries
    const sanitize = (payload: string | null | undefined): string => {
      if (!payload) return "";
      // redact email-like patterns and long hexs/ids, keep short text
      const redacted = payload.replace(
        /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g,
        "[REDACTED]",
      );
      const trimmed = redacted.replace(/\s+/g, " ").trim();
      return trimmed.length > 500 ? trimmed.slice(0, 500) : trimmed;
    };

    const recent_high_priority_audits = recentAudits.map((a) => ({
      id: a.id as string & tags.Format<"uuid">,
      event_type: a.event_type,
      occurred_at: toISOStringSafe(a.occurred_at),
      short_summary: sanitize(a.event_payload),
    }));

    return {
      pending_reports_24h: pending24,
      pending_reports_7d: pending7,
      actions_breakdown,
      average_processing_times,
      recent_high_priority_audits,
      generated_at: nowIso,
    };
  } catch (err) {
    throw new HttpException("Internal Server Error", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import { IDiscussionBoardReportReasonCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportReasonCategory";
import { IDiscussionBoardReportStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportStatus";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function getDiscussionBoardModeratorReportsReportId(props: {
  moderator: ModeratorPayload;
  reportId: string & tags.Format<"uuid">;
}): Promise<IDiscussionBoardReport> {
  const { moderator, reportId } = props;

  try {
    // Fetch the report by primary key
    const record = await MyGlobal.prisma.discussion_board_reports.findUnique({
      where: { id: reportId },
    });

    if (!record) {
      throw new HttpException("Not Found", 404);
    }

    // Audit the read access for moderator triage (append-only)
    try {
      const auditId = v4();
      await MyGlobal.prisma.discussion_board_moderation_audit.create({
        data: {
          id: auditId,
          moderation_action_id: null,
          report_id: record.id,
          actor_moderator_id: moderator.id,
          event_type: "report.viewed",
          event_payload: JSON.stringify({
            report_id: record.id,
            moderator_id: moderator.id,
            reporter_session_id: record.reporter_session_id ?? null,
          }),
          // Use report.created_at as timestamp source to avoid creating new Date()
          occurred_at: toISOStringSafe(record.created_at),
        },
      });
    } catch (auditError) {
      // Audit failure should not block the main response, but log and continue
      // If Prisma is unavailable, surface a 503 with correlation id
      if (
        auditError instanceof Prisma.PrismaClientKnownRequestError ||
        auditError instanceof Error
      ) {
        const correlationId = v4();
        // Attempt to write to global logs where available
        try {
          // Best-effort: if MyGlobal has logging, use it; otherwise ignore
          if (
            (MyGlobal as any).logger &&
            typeof (MyGlobal as any).logger.error === "function"
          ) {
            (MyGlobal as any).logger.error(
              `Audit logging failed (${correlationId})`,
              auditError,
            );
          }
        } catch (e) {
          // noop
        }
      }
    }

    // Validate and strip tags for primitive enum/literal properties
    const reason_category = typia.assert<IDiscussionBoardReportReasonCategory>(
      record.reason_category,
    );
    const status = typia.assert<IDiscussionBoardReportStatus>(record.status);

    // Build API response mapping Prisma result to DTO
    const result = {
      id: record.id,
      reporter_member_id: record.reporter_member_id,
      // reporter_session_id is optional+nullable in DTO - return null when DB null
      reporter_session_id: record.reporter_session_id ?? null,
      target_type: record.target_type,
      target_id: record.target_id,
      reason_category,
      explanation: record.explanation ?? null,
      status,
      created_at: toISOStringSafe(record.created_at),
      processed_at: record.processed_at
        ? toISOStringSafe(record.processed_at)
        : null,
      closed_at: record.closed_at ? toISOStringSafe(record.closed_at) : null,
    } satisfies IDiscussionBoardReport;

    return result;
  } catch (error) {
    // Known HttpException should be rethrown
    if (error instanceof HttpException) throw error;

    // Prisma transient or unexpected error -> surface 503 with correlation id
    const correlationId = v4();
    // Attempt to log error
    try {
      if (
        (MyGlobal as any).logger &&
        typeof (MyGlobal as any).logger.error === "function"
      ) {
        (MyGlobal as any).logger.error(
          `getDiscussionBoardModeratorReportsReportId failed (${correlationId})`,
          error,
        );
      }
    } catch (e) {
      // noop
    }

    throw new HttpException(`Service Unavailable: ${correlationId}`, 503);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardArticlesMonthlyStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticlesMonthlyStatistics";

export async function getDiscussionBoardStatisticsArticlesByMonth(): Promise<IDiscussionBoardArticlesMonthlyStatistics> {
  try {
    // Aggregate monthly buckets on DB side. We bucket rows by published_at when
    // available, otherwise by created_at (COALESCE), then compute conditional
    // counts per state. Soft-deleted rows (deleted_at IS NOT NULL) are excluded.
    const rows = (await MyGlobal.prisma.$queryRaw(Prisma.sql`
      SELECT
        date_trunc('month', COALESCE(published_at, created_at)) AS month,
        COUNT(*) FILTER (WHERE state = 'published' AND published_at IS NOT NULL
          AND published_at >= date_trunc('month', COALESCE(published_at, created_at))
          AND published_at < date_trunc('month', COALESCE(published_at, created_at)) + interval '1 month') AS published_count,
        COUNT(*) FILTER (WHERE state = 'draft' AND created_at >= date_trunc('month', COALESCE(published_at, created_at))
          AND created_at < date_trunc('month', COALESCE(published_at, created_at)) + interval '1 month') AS draft_count,
        COUNT(*) FILTER (WHERE state = 'pending_review' AND created_at >= date_trunc('month', COALESCE(published_at, created_at))
          AND created_at < date_trunc('month', COALESCE(published_at, created_at)) + interval '1 month') AS pending_review_count,
        COUNT(*) FILTER (WHERE state = 'hidden' AND created_at >= date_trunc('month', COALESCE(published_at, created_at))
          AND created_at < date_trunc('month', COALESCE(published_at, created_at)) + interval '1 month') AS hidden_count,
        COUNT(DISTINCT CASE WHEN state = 'published' AND published_at IS NOT NULL THEN discussion_board_member_id END) AS distinct_authors_published
      FROM discussion_board_articles
      WHERE deleted_at IS NULL
      GROUP BY date_trunc('month', COALESCE(published_at, created_at))
      ORDER BY date_trunc('month', COALESCE(published_at, created_at)) DESC
      LIMIT 1
    `)) as unknown as Array<Record<string, any>>;

    if (!rows || rows.length === 0) {
      return {
        month: "1970-01-01T00:00:00Z",
        published_count: 0,
        draft_count: 0,
        pending_review_count: 0,
        hidden_count: 0,
        distinct_authors_published: 0,
        average_published_per_author: 0,
      };
    }

    const row = rows[0] as Record<string, any>;

    const month = row.month
      ? toISOStringSafe(row.month as any)
      : "1970-01-01T00:00:00Z";

    const published_count = Number(row.published_count ?? 0);
    const draft_count = Number(row.draft_count ?? 0);
    const pending_review_count = Number(row.pending_review_count ?? 0);
    const hidden_count = Number(row.hidden_count ?? 0);
    const distinct_authors_published = Number(
      row.distinct_authors_published ?? 0,
    );

    const average_published_per_author =
      published_count / Math.max(distinct_authors_published, 1);

    return {
      month,
      published_count,
      draft_count,
      pending_review_count,
      hidden_count,
      distinct_authors_published,
      average_published_per_author,
    };
  } catch (err) {
    const correlationId = v4();
    throw new HttpException(`Database error (${correlationId})`, 500);
  }
}

