  const whereCondition: Record<string, unknown> = {
    ...(includeArchived ? {} : { deleted_at: null }),
    ...(isActive !== undefined && { is_active: isActive }),
    ...((body.createdFrom !== undefined && body.createdFrom !== null) ||
