import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function postAuthModeratorRefresh(props: {
  moderator: ModeratorPayload;
  body: IDiscussionBoardModerator.IRefresh;
}): Promise<IDiscussionBoardModerator.IAuthorized> {
  const { moderator, body } = props;

  // Determine target ids based on variant
  let targetModeratorId: string & tags.Format<"uuid">;
  let targetSessionId: string & tags.Format<"uuid">;

  if (body.type === "refresh_token") {
    let decoded: { id: string; session_id: string; type: string };
    try {
      decoded = jwt.verify(body.refresh_token, MyGlobal.env.JWT_SECRET_KEY, {
        issuer: "autobe",
      }) as { id: string; session_id: string; type: string };
    } catch (err) {
      throw new HttpException("Invalid or expired refresh token", 401);
    }

    if (decoded.type !== "moderator") {
      throw new HttpException("Invalid token type", 403);
    }

    targetModeratorId = decoded.id as unknown as string & tags.Format<"uuid">;
    targetSessionId = decoded.session_id as unknown as string &
      tags.Format<"uuid">;
  } else {
    // session_id variant
    targetSessionId = body.session_id;
    targetModeratorId = moderator.id;
  }

  // Fetch session
  const session =
    await MyGlobal.prisma.discussion_board_moderator_sessions.findFirst({
      where: {
        id: targetSessionId,
        discussion_board_moderator_id: targetModeratorId,
      },
    });

  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }

  // Validate session expiry
  if (session.expired_at && session.expired_at.getTime() <= Date.now()) {
    throw new HttpException("Session expired or revoked", 401);
  }

  // Fetch moderator and validate
  const mod =
    await MyGlobal.prisma.discussion_board_moderator.findUniqueOrThrow({
      where: { id: targetModeratorId },
    });

  if (mod.deleted_at !== null) {
    throw new HttpException("Account has been deleted", 403);
  }

  // If authenticated moderator provided, ensure ownership
  if (moderator && moderator.id !== targetModeratorId) {
    throw new HttpException(
      "Unauthorized: session does not belong to actor",
      403,
    );
  }

  // Prepare timestamps
  const now = new Date();
  const nowIso = toISOStringSafe(now);
  const accessExpireDate = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpireDate = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const accessExpiredAt = toISOStringSafe(accessExpireDate);
  const refreshableUntil = toISOStringSafe(refreshExpireDate);

  // Sign tokens
  const access = jwt.sign(
    {
      type: "moderator",
      id: targetModeratorId,
      session_id: targetSessionId,
      created_at: nowIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "1h", issuer: "autobe" },
  );

  const refresh = jwt.sign(
    {
      type: "moderator",
      id: targetModeratorId,
      session_id: targetSessionId,
      tokenType: "refresh",
      created_at: nowIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );

  // Update session expiry (sliding window)
  await MyGlobal.prisma.discussion_board_moderator_sessions.update({
    where: { id: targetSessionId },
    data: {
      expired_at: refreshExpireDate,
    },
  });

  // Create audit entry
  await MyGlobal.prisma.discussion_board_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      event_type: "auth.moderator.refresh",
      event_timestamp: nowIso,
      resource_type: null,
      resource_id: null,
      actor_type: "moderator",
      actor_id: targetModeratorId,
      ip: session.ip ?? null,
      user_agent: session.href ?? null,
      metadata: JSON.stringify({ session_id: targetSessionId }),
      created_at: nowIso,
      updated_at: nowIso,
    },
  });

  // Build response object
  const response: IDiscussionBoardModerator.IAuthorized = {
    id: mod.id,
    username: mod.username,
    email: mod.email ?? undefined,
    display_name: mod.display_name ?? null,
    created_at: toISOStringSafe(mod.created_at),
    updated_at: toISOStringSafe(mod.updated_at),
    token: {
      access,
      refresh,
      expired_at: accessExpiredAt,
      refreshable_until: refreshableUntil,
    },
    moderator: {
      id: mod.id,
      username: mod.username,
      display_name: mod.display_name ?? null,
      created_at: toISOStringSafe(mod.created_at),
      updated_at: toISOStringSafe(mod.updated_at),
      deleted_at: mod.deleted_at ? toISOStringSafe(mod.deleted_at) : null,
    },
  };

  return response;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function putDiscussionBoardMemberMembersMemberUsername(props: {
  member: MemberPayload;
  memberUsername: string;
  body: IDiscussionBoardMember.IUpdate;
}): Promise<IDiscussionBoardMember> {
  const { member, memberUsername, body } = props;

  // Fetch target member by username
  const target = await MyGlobal.prisma.discussion_board_member.findUnique({
    where: { username: memberUsername },
  });

  if (!target || target.deleted_at !== null) {
    throw new HttpException("Not Found", 404);
  }

  // Authorization: only owner can update
  if (target.id !== member.id) {
    throw new HttpException(
      "Unauthorized: Only the member may update their profile",
      403,
    );
  }

  // Determine which fields will be updated
  const willUpdateDisplayName = body.display_name !== undefined;
  const willUpdatePassword =
    body.password !== undefined && body.password !== null;

  if (!willUpdateDisplayName && !willUpdatePassword) {
    throw new HttpException("Bad Request: No updatable fields provided", 400);
  }

  // Password strength validation and hashing
  let hashedPassword: string | undefined;
  if (willUpdatePassword) {
    // body.password has been checked for !== undefined && !== null above
    const pwd = body.password!;
    // Business rule: min 12 chars
    if (pwd.length < 12)
      throw new HttpException(
        "Bad Request: Password must be at least 12 characters",
        400,
      );
    // At least 3 of 4 categories
    const categories = [
      /[A-Z]/.test(pwd),
      /[a-z]/.test(pwd),
      /[0-9]/.test(pwd),
      /[^A-Za-z0-9]/.test(pwd),
    ];
    const satisfied = categories.filter(Boolean).length;
    if (satisfied < 3)
      throw new HttpException(
        "Bad Request: Password must include at least three of: uppercase, lowercase, number, symbol",
        400,
      );

    hashedPassword = await PasswordUtil.hash(pwd);
  }

  // Prepare timestamp once
  const now = toISOStringSafe(new Date());

  // Inline update - explicit field conversion for nullability
  const updated = await MyGlobal.prisma.discussion_board_member.update({
    where: { id: target.id },
    data: {
      ...(willUpdateDisplayName
        ? { display_name: body.display_name ?? null }
        : {}),
      ...(hashedPassword ? { password_hash: hashedPassword } : {}),
      updated_at: now,
    },
  });

  // Revoke sessions if requested after password change
  if (willUpdatePassword && body.revokeSessions === true) {
    await MyGlobal.prisma.discussion_board_member_sessions.updateMany({
      where: {
        discussion_board_member_id: updated.id,
        expired_at: null,
      },
      data: { expired_at: now },
    });
  }

  // Construct response, converting Date fields to ISO strings
  return {
    id: updated.id,
    username: updated.username,
    display_name: updated.display_name === null ? null : updated.display_name,
    role: updated.role,
    mfa_enabled: updated.mfa_enabled,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at
      ? toISOStringSafe(updated.deleted_at)
      : undefined,
  };
}

