  // Fetch existing appeal (throws if not found)
  const existing =
    await MyGlobal.prisma.discussion_board_appeals.findUniqueOrThrow({
      where: { id: appealId },
    });

  // STATUS TRANSITION VALIDATION
  if (body.status !== undefined && body.status !== null) {
    if (
      (existing.status === "accepted" || existing.status === "rejected") &&
      body.status === "pending"
    ) {
      throw new HttpException(
        "Invalid status transition: cannot revert resolved appeal to pending",
        400,
      );
    }
  }

  // MODERATION ACTION REFERENTIAL CHECK
  if (
    body.moderationActionId !== undefined &&
    body.moderationActionId !== null
  ) {
    const modAction =
      await MyGlobal.prisma.discussion_board_moderation_actions.findUnique({
        where: { id: body.moderationActionId },
      });
    if (!modAction) {
      throw new HttpException("Moderation action not found", 404);
    }

    // If both the appeal and moderation action reference a report, they must match
    if (
      existing.report_id &&
      modAction.discussion_board_report_id &&
      modAction.discussion_board_report_id !== existing.report_id
    ) {
      throw new HttpException(
        "Conflict: moderation action does not reference the same report as the appeal",
        409,
      );
    }
  }

  // RESOLVED_AT CHRONOLOGY VALIDATION
  if (body.resolvedAt !== undefined && body.resolvedAt !== null) {
    // created_at from Prisma is a Date | string handled by toISOStringSafe
    const createdIso = toISOStringSafe(existing.created_at);
    const provided = body.resolvedAt;
    const createdMs = Date.parse(createdIso);
    const providedMs = Date.parse(provided);
    if (Number.isNaN(providedMs)) {
      throw new HttpException(
        "resolvedAt must be a valid ISO 8601 datetime string",
        400,
      );
    }
    if (providedMs < createdMs) {
      throw new HttpException(
        "resolvedAt must not be earlier than appeal.created_at",
        400,
      );
    }
  }

  // PERFORM UPDATE - inline data object with conditional fields
  const updated = await MyGlobal.prisma.discussion_board_appeals.update({
    where: { id: appealId },
    data: {
      // status is required in DB; if caller provided null, treat as "no-op" (skip)
      ...(body.status !== undefined && body.status !== null
        ? { status: body.status }
        : {}),

      // resolution_reason is nullable; preserve explicit null when provided
      ...(body.resolutionReason !== undefined
        ? { resolution_reason: body.resolutionReason }
        : {}),

      // resolved_at is nullable date-time; convert when non-null
      ...(body.resolvedAt !== undefined
        ? {
            resolved_at:
              body.resolvedAt === null
                ? null
                : toISOStringSafe(body.resolvedAt),
          }
        : {}),

      // moderation_action_id is nullable FK; preserve explicit null when provided
      ...(body.moderationActionId !== undefined
        ? {
            moderation_action_id:
              body.moderationActionId === null ? null : body.moderationActionId,
          }
        : {}),
    },
  });

  // BUILD AUDIT ENTRY: capture before and after snapshots (stringify-safe)
  const before = {
    id: existing.id,
    appellant_member_id: existing.appellant_member_id,
    moderation_action_id:
      existing.moderation_action_id === null
        ? undefined
        : existing.moderation_action_id,
    report_id: existing.report_id === null ? undefined : existing.report_id,
    explanation: existing.explanation,
    status: existing.status,
    created_at: toISOStringSafe(existing.created_at),
    resolved_at: existing.resolved_at
      ? toISOStringSafe(existing.resolved_at)
      : null,
    resolution_reason:
      existing.resolution_reason === null
        ? undefined
        : existing.resolution_reason,
  };

  const after = {
    id: updated.id,
    appellant_member_id: updated.appellant_member_id,
    moderation_action_id:
      updated.moderation_action_id === null
        ? undefined
        : updated.moderation_action_id,
    report_id: updated.report_id === null ? undefined : updated.report_id,
    explanation: updated.explanation,
    status: updated.status,
    created_at: toISOStringSafe(updated.created_at),
    resolved_at: updated.resolved_at
      ? toISOStringSafe(updated.resolved_at)
      : null,
    resolution_reason:
      updated.resolution_reason === null
        ? undefined
        : updated.resolution_reason,
  };

  await MyGlobal.prisma.discussion_board_moderation_audit.create({
    data: {
      id: v4(),
      moderation_action_id: updated.moderation_action_id ?? null,
      report_id: updated.report_id ?? null,
      actor_moderator_id: moderator.id,
      event_type: "appeal.updated",
      event_payload: JSON.stringify({ before, after }),
      // Use existing created_at as the audit occurred_at timestamp because updated.updated_at is not present on the returned type
      occurred_at: toISOStringSafe(updated.created_at),
    },
  });

  // MAP DB ROW TO API RETURN TYPE (respecting null vs undefined rules)
  return {
    id: updated.id,
    appellant_member_id: updated.appellant_member_id,
    moderation_action_id:
      updated.moderation_action_id === null
        ? undefined
        : updated.moderation_action_id,
    report_id: updated.report_id === null ? undefined : updated.report_id,
    explanation: updated.explanation,
    status: typia.assert<IEDiscussionBoardAppealStatus>(updated.status),
    created_at: toISOStringSafe(updated.created_at),
    resolved_at: updated.resolved_at
      ? toISOStringSafe(updated.resolved_at)
      : null,
    resolution_reason:
      updated.resolution_reason === null
        ? undefined
        : updated.resolution_reason,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import { IDiscussionBoardReportReasonCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportReasonCategory";
import { IDiscussionBoardReportStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportStatus";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function putDiscussionBoardModeratorReportsReportId(props: {
  moderator: ModeratorPayload;
  reportId: string & tags.Format<"uuid">;
  body: IDiscussionBoardReport.IUpdate;
}): Promise<IDiscussionBoardReport> {
  const { moderator, reportId, body } = props;

  // Authorization: ensure moderator session is valid and moderator not deleted
  const session =
    await MyGlobal.prisma.discussion_board_moderator_sessions.findFirst({
      where: {
        id: moderator.session_id,
        discussion_board_moderator_id: moderator.id,
        expired_at: null,
        moderator: { deleted_at: null },
      },
    });
  if (!session)
    throw new HttpException("Unauthorized: invalid moderator session", 403);

  // Validate allowed status values (business rule)
  const allowedStatuses = ["pending", "triaged", "resolved"] as const;
  if (body.status !== undefined && !allowedStatuses.includes(body.status)) {
    throw new HttpException("Bad Request: invalid status value", 400);
  }

  // Fetch existing report
  const existing = await MyGlobal.prisma.discussion_board_reports.findUnique({
    where: { id: reportId },
  });
  if (!existing) throw new HttpException("Not Found", 404);

  // Validate provided timestamps (must be ISO 8601 and chronological)
  if (body.processed_at !== undefined && body.processed_at !== null) {
    const parsedProcessed = Date.parse(body.processed_at);
    if (Number.isNaN(parsedProcessed)) {
      throw new HttpException(
        "Bad Request: processed_at must be ISO 8601",
        400,
      );
    }
    if (
      parsedProcessed <
      Date.parse(toISOStringSafe(existing.created_at as unknown as string))
    ) {
      throw new HttpException(
        "Bad Request: processed_at cannot be earlier than created_at",
        400,
      );
    }
  }

  if (body.closed_at !== undefined && body.closed_at !== null) {
    const parsedClosed = Date.parse(body.closed_at);
    if (Number.isNaN(parsedClosed)) {
      throw new HttpException("Bad Request: closed_at must be ISO 8601", 400);
    }
    if (
      parsedClosed <
      Date.parse(toISOStringSafe(existing.created_at as unknown as string))
    ) {
      throw new HttpException(
        "Bad Request: closed_at cannot be earlier than created_at",
        400,
      );
    }
    const processedReference =
      body.processed_at !== undefined && body.processed_at !== null
        ? Date.parse(body.processed_at)
        : existing.processed_at
          ? Date.parse(
              toISOStringSafe(existing.processed_at as unknown as string),
            )
          : null;
    if (processedReference !== null && parsedClosed < processedReference) {
      throw new HttpException(
        "Bad Request: closed_at cannot be earlier than processed_at",
        400,
      );
    }
  }

  // Prepare values for update using toISOStringSafe (null-checked)
  const processedAtValue =
    body.processed_at === undefined
      ? undefined
      : body.processed_at === null
        ? null
        : toISOStringSafe(body.processed_at);

  let closedAtValue: (string & tags.Format<"date-time">) | null | undefined =
    body.closed_at === undefined
      ? undefined
      : body.closed_at === null
        ? null
        : toISOStringSafe(body.closed_at);

  // If status changes to resolved and closed_at not explicitly provided, set now
  if (body.status === "resolved" && body.closed_at === undefined) {
    closedAtValue = toISOStringSafe(new Date() as unknown as string);
  }

  // Inline update per Prisma guidance
  const updated = await MyGlobal.prisma.discussion_board_reports.update({
    where: { id: reportId },
    data: {
      ...(body.status !== undefined && { status: body.status }),
      ...(body.processed_at !== undefined && {
        processed_at: processedAtValue,
      }),
      ...((body.closed_at !== undefined ||
        (body.status === "resolved" && closedAtValue !== undefined)) && {
        closed_at: closedAtValue,
      }),
    },
  });

  // Append audit entry for moderation changes
  await MyGlobal.prisma.discussion_board_moderation_audit.create({
    data: {
      id: v4(),
      report_id: reportId,
      actor_moderator_id: moderator.id,
      event_type: "moderation.report.updated",
      event_payload: JSON.stringify({
        before: {
          id: existing.id,
          status: existing.status,
          processed_at: existing.processed_at
            ? toISOStringSafe(existing.processed_at as unknown as string)
            : null,
          closed_at: existing.closed_at
            ? toISOStringSafe(existing.closed_at as unknown as string)
            : null,
        },
        after: {
          id: updated.id,
          status: updated.status,
          processed_at: updated.processed_at
            ? toISOStringSafe(updated.processed_at as unknown as string)
            : null,
          closed_at: updated.closed_at
            ? toISOStringSafe(updated.closed_at as unknown as string)
            : null,
        },
        actor: moderator.id,
      }),
      occurred_at: toISOStringSafe(new Date() as unknown as string),
    },
  });

  // Build response and redact sensitive session-level data (reporter_session_id omitted)
  const response = {
    id: updated.id,
    reporter_member_id: updated.reporter_member_id,
    target_type: updated.target_type,
    target_id: updated.target_id,
    reason_category: typia.assert<IDiscussionBoardReportReasonCategory>(
      updated.reason_category,
    ),
    explanation: updated.explanation ?? null,
    status: typia.assert<IDiscussionBoardReportStatus>(updated.status),
    created_at: toISOStringSafe(updated.created_at as unknown as string),
    processed_at: updated.processed_at
      ? toISOStringSafe(updated.processed_at as unknown as string)
      : null,
    closed_at: updated.closed_at
      ? toISOStringSafe(updated.closed_at as unknown as string)
      : null,
  } satisfies IDiscussionBoardReport;

  return response;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function deleteAuthMemberSessionsSessionId(props: {
  member: MemberPayload;
  sessionId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { member, sessionId } = props;

  const session =
    await MyGlobal.prisma.discussion_board_member_sessions.findUnique({
      where: { id: sessionId },
    });

  if (!session) throw new HttpException("Not Found", 404);

  // Authorization: only the session owner may revoke
  if (session.discussion_board_member_id !== member.id) {
    throw new HttpException(
      "Unauthorized: You can only revoke your own sessions",
      403,
    );
  }

  const now = toISOStringSafe(new Date());

  // Soft-revoke the session by setting expired_at
  await MyGlobal.prisma.discussion_board_member_sessions.update({
    where: { id: sessionId },
    data: { expired_at: now },
  });

  // Audit the revocation - use 'metadata' (schema field) to store payload
  await MyGlobal.prisma.discussion_board_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      event_type: "auth.session_revoked",
      event_timestamp: now,
      resource_type: "session",
      resource_id: sessionId,
      actor_type: "member",
      actor_id: member.id,
      ip: session.ip ?? null,
      metadata: JSON.stringify({
        action: "session_revoked",
        actor_member_id: member.id,
        target_session_id: sessionId,
        ip: session.ip ?? null,
      }),
      created_at: now,
      updated_at: now,
    },
  });
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function deleteDiscussionBoardMemberArticlesArticleIdCommentsCommentId(props: {
  member: MemberPayload;
  articleId: string & tags.Format<"uuid">;
  commentId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { member, articleId, commentId } = props;

  // Verify parent article exists
  const article = await MyGlobal.prisma.discussion_board_articles.findUnique({
    where: { id: articleId },
    select: { id: true },
  });
  if (!article) throw new HttpException("Not Found", 404);

  // Fetch the comment and validate ownership and association
  const comment = await MyGlobal.prisma.discussion_board_comments.findUnique({
    where: { id: commentId },
    select: {
      id: true,
      discussion_board_article_id: true,
      discussion_board_author_id: true,
      deleted_at: true,
    },
  });
  if (!comment) throw new HttpException("Not Found", 404);
  if (comment.discussion_board_article_id !== articleId)
    throw new HttpException("Not Found", 404);

  // Authorization: only the original author may perform this operation
  if (comment.discussion_board_author_id !== member.id) {
    throw new HttpException(
      "Unauthorized: Only the comment author may delete this comment",
      403,
    );
  }

  // Idempotent: if already soft-deleted, succeed silently
  if (comment.deleted_at !== null) return;

  // Prevent deletion if there is active moderation work (reports/appeals)
  const activeReport = await MyGlobal.prisma.discussion_board_reports.findFirst(
    {
      where: {
        target_type: "comment",
        target_id: commentId,
        NOT: { status: "resolved" },
      },
      select: { id: true },
    },
  );
  if (activeReport)
    throw new HttpException(
      "Conflict: active moderation in progress for this comment",
      409,
    );

  // Prepare timestamp once and reuse
  const now = toISOStringSafe(new Date());

  // Soft-delete the comment
  await MyGlobal.prisma.discussion_board_comments.update({
    where: { id: commentId },
    data: { deleted_at: now },
  });

  // Record an audit entry describing the author-driven deletion
  await MyGlobal.prisma.discussion_board_moderation_audit.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      event_type: "comment.deleted",
      event_payload: JSON.stringify({
        actor: { type: "member", id: member.id },
        reason: "author_deleted",
        article_id: articleId,
        comment_id: commentId,
      }),
      occurred_at: now,
    } satisfies Prisma.discussion_board_moderation_auditCreateInput,
  });
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function deleteDiscussionBoardMemberArticlesArticleIdCommentsCommentIdAttachmentsAttachmentId(props: {
  member: MemberPayload;
  articleId: string & tags.Format<"uuid">;
  commentId: string & tags.Format<"uuid">;
  attachmentId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { member, articleId, commentId, attachmentId } = props;

  const article = await MyGlobal.prisma.discussion_board_articles.findUnique({
    where: { id: articleId },
    select: { id: true, discussion_board_member_id: true },
  });
  if (!article) throw new HttpException("Not Found", 404);

  const comment = await MyGlobal.prisma.discussion_board_comments.findUnique({
    where: { id: commentId },
    select: { id: true, discussion_board_article_id: true },
  });
  if (!comment || comment.discussion_board_article_id !== articleId) {
    throw new HttpException("Not Found", 404);
  }

  const attachment =
    await MyGlobal.prisma.discussion_board_comment_attachments.findUnique({
      where: { id: attachmentId },
      select: {
        id: true,
        discussion_board_comment_id: true,
        discussion_board_uploaded_by_id: true,
        storage_key: true,
        original_filename: true,
        quarantined: true,
        created_at: true,
      },
    });
  if (!attachment || attachment.discussion_board_comment_id !== commentId) {
    throw new HttpException("Not Found", 404);
  }

  const isUploader = member.id === attachment.discussion_board_uploaded_by_id;
  const isArticleAuthor = member.id === article.discussion_board_member_id;

  let isModerator = false;
  const memberRecord = await MyGlobal.prisma.discussion_board_member.findUnique(
    {
      where: { id: member.id },
      select: { role: true },
    },
  );
  if (memberRecord && memberRecord.role === "moderator") isModerator = true;

  if (!isUploader && !isArticleAuthor && !isModerator) {
    throw new HttpException("Unauthorized: insufficient permission", 403);
  }

  const auditId = v4() as string & tags.Format<"uuid">;
  const occurred_at = toISOStringSafe(new Date());
  const basePayload = {
    action: "delete_comment_attachment",
    actor_member_id: member.id,
    article_id: articleId,
    comment_id: commentId,
    attachment_id: attachmentId,
    storage_key: attachment.storage_key,
    original_filename: attachment.original_filename,
    quarantined: attachment.quarantined === true,
    storage_deleted: false,
  };

  // Delete DB row and create audit entry in a single transaction
  await MyGlobal.prisma.$transaction([
    MyGlobal.prisma.discussion_board_comment_attachments.delete({
      where: { id: attachmentId },
    }),
    MyGlobal.prisma.discussion_board_moderation_audit.create({
      data: {
        id: auditId,
        event_type: "attachment.deleted",
        event_payload: JSON.stringify(basePayload),
        occurred_at: occurred_at,
      },
    }),
  ]);

  // Access optional storage client in a type-safe way without assuming property exists on MyGlobal
  const storageClient = (
    MyGlobal as unknown as {
      storage?: {
        delete?: (key: string) => Promise<void>;
        deleteObject?: (key: string) => Promise<void>;
      };
    }
  ).storage;

  try {
    if (storageClient && typeof storageClient.delete === "function") {
      await storageClient.delete(attachment.storage_key);
    } else if (
      storageClient &&
      typeof storageClient.deleteObject === "function"
    ) {
      await storageClient.deleteObject(attachment.storage_key);
    } else {
      // Storage client not available - record a failure audit and surface error
      const failureAuditId = v4() as string & tags.Format<"uuid">;
      const failurePayload = {
        ...basePayload,
        storage_deleted: false,
        storage_error: "storage client not available",
      };
      await MyGlobal.prisma.discussion_board_moderation_audit.create({
        data: {
          id: failureAuditId,
          event_type: "attachment.delete_storage_failed",
          event_payload: JSON.stringify(failurePayload),
          occurred_at: toISOStringSafe(new Date()),
        },
      });

      throw new HttpException("Storage deletion failed", 500);
    }

    // mark audit payload storage_deleted = true
    const updatedPayload = { ...basePayload, storage_deleted: true };
    await MyGlobal.prisma.discussion_board_moderation_audit.update({
      where: { id: auditId },
      data: { event_payload: JSON.stringify(updatedPayload) },
    });

    return;
  } catch (err) {
    const failureAuditId = v4() as string & tags.Format<"uuid">;
    const storageError = String(
      (err as unknown as { message?: unknown }).message ?? err,
    );
    const failurePayload = {
      ...basePayload,
      storage_deleted: false,
      storage_error: storageError,
    };
    await MyGlobal.prisma.discussion_board_moderation_audit.create({
      data: {
        id: failureAuditId,
        event_type: "attachment.delete_storage_failed",
        event_payload: JSON.stringify(failurePayload),
        occurred_at: toISOStringSafe(new Date()),
      },
    });

    throw new HttpException("Storage deletion failed", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

export async function getDiscussionBoardArticlesArticleIdAttachmentsAttachmentId(props: {
  articleId: string & tags.Format<"uuid">;
  attachmentId: string & tags.Format<"uuid">;
}): Promise<IDiscussionBoardAttachment> {
  const { articleId, attachmentId } = props;

  try {
    const attachment =
      await MyGlobal.prisma.discussion_board_attachments.findUnique({
        where: { id: attachmentId },
        include: { article: true, uploader: true },
      });

    if (!attachment) throw new HttpException("Not Found", 404);

    // Ensure the attachment belongs to the requested article
    if (attachment.discussion_board_article_id !== articleId) {
      throw new HttpException("Not Found", 404);
    }

    // Visibility enforcement: treat deleted or non-published as not found
    if (attachment.deleted_at !== null)
      throw new HttpException("Not Found", 404);
    if (!attachment.article) throw new HttpException("Not Found", 404);
    if (attachment.article.deleted_at !== null)
      throw new HttpException("Not Found", 404);
    if (attachment.article.state !== "published")
      throw new HttpException("Not Found", 404);

    // Map uploader summary when available
    const uploader = attachment.uploader
      ? {
          id: attachment.uploader.id as string & tags.Format<"uuid">,
          username: attachment.uploader.username,
          display_name: attachment.uploader.display_name ?? null,
          created_at: toISOStringSafe(attachment.uploader.created_at),
        }
      : undefined;

    // Provide a safe, implementation-defined download URL (avoid non-existent env keys)
    const downloadUrl = `/attachments/download/${attachment.id}` as string &
      tags.Format<"uri">;

    const result = {
      id: attachment.id as string & tags.Format<"uuid">,
      article_id: attachment.discussion_board_article_id as string &
        tags.Format<"uuid">,
      original_filename: attachment.original_filename,
      storage_key: attachment.storage_key as string & tags.Format<"uri">,
      mime_type: attachment.mime_type,
      size: attachment.size,
      is_image: attachment.is_image,
      created_at: toISOStringSafe(attachment.created_at),
      deleted_at: attachment.deleted_at
        ? toISOStringSafe(attachment.deleted_at)
        : null,
      uploader,
      downloadUrl,
    };

    return result;
  } catch (error) {
    if (error instanceof HttpException) throw error;
    throw new HttpException("Internal Server Error", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
