import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function patchDiscussionBoardModeratorMembers(props: {
  moderator: ModeratorPayload;
  body: IDiscussionBoardMember.IRequest;
}): Promise<IPageIDiscussionBoardMember.ISummary> {
  const { moderator, body } = props;

  // Pagination defaults and validation
  const page = Number(body.page ?? 1);
  const requestedLimit = Number(body.limit ?? 20);
  if (!Number.isFinite(page) || page < 1)
    throw new HttpException("Invalid page", 400);
  if (!Number.isFinite(requestedLimit) || requestedLimit < 1)
    throw new HttpException("Invalid limit", 400);

  const limit = Math.min(requestedLimit, 100);
  const skip = (page - 1) * limit;

  // Build where conditions inline
  const where: Record<string, unknown> = {
    ...(body.includeDeleted ? {} : { deleted_at: null }),
    ...(body.role !== undefined && { role: body.role }),
    ...(body.mfaEnabled !== undefined &&
      body.mfaEnabled !== null && { mfa_enabled: body.mfaEnabled }),
    ...(body.username !== undefined &&
      body.username !== null && { username: { contains: body.username } }),
    ...((body.createdAtFrom !== undefined && body.createdAtFrom !== null) ||
    (body.createdAtTo !== undefined && body.createdAtTo !== null)
      ? {
          created_at: {
            ...(body.createdAtFrom !== undefined &&
              body.createdAtFrom !== null && { gte: body.createdAtFrom }),
            ...(body.createdAtTo !== undefined &&
              body.createdAtTo !== null && { lte: body.createdAtTo }),
          },
        }
      : {}),
    ...(body.email !== undefined &&
      body.email !== null && { email: body.email }),
  };

  // Privileged action: audit when email filter used
  if (body.email !== undefined && body.email !== null) {
    await MyGlobal.prisma.discussion_board_audit_logs.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        event_type: "member.search.email",
        // 'metadata' exists on discussion_board_audit_logs; event_payload does not
        metadata: JSON.stringify({
          moderator_id: moderator.id,
          email: body.email,
        }),
        event_timestamp: toISOStringSafe(new Date()),
        actor_type: "moderator",
        actor_id: moderator.id,
        created_at: toISOStringSafe(new Date()),
        updated_at: toISOStringSafe(new Date()),
      },
    });
  }

  // Inline orderBy mapping
  const orderBy =
    body.sortBy === "createdAt"
      ? { created_at: "asc" as const }
      : body.sortBy === "-createdAt"
        ? { created_at: "desc" as const }
        : body.sortBy === "username"
          ? { username: "asc" as const }
          : body.sortBy === "-username"
            ? { username: "desc" as const }
            : { created_at: "desc" as const };

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_member.findMany({
      where,
      orderBy,
      skip,
      take: limit,
      select: {
        id: true,
        username: true,
        display_name: true,
        created_at: true,
      },
    }),
    MyGlobal.prisma.discussion_board_member.count({ where }),
  ]);

  const data = rows.map((r) => ({
    id: r.id as string & tags.Format<"uuid">,
    username: r.username,
    display_name:
      r.display_name === null ? null : (r.display_name ?? undefined),
    created_at: toISOStringSafe(r.created_at),
  }));

  const pages = Math.ceil(total / limit);

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Number(pages),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function postAuthModeratorPasswordChange(props: {
  moderator: ModeratorPayload;
  body: IDiscussionBoardModerator.IChangePassword;
}): Promise<IDiscussionBoardModerator> {
  const { moderator, body } = props;

  // Fetch active moderator (reject if soft-deleted)
  const existing = await MyGlobal.prisma.discussion_board_moderator.findFirst({
    where: { id: moderator.id, deleted_at: null },
  });

  if (!existing) {
    throw new HttpException("Not Found", 404);
  }

  // Verify current password against stored hash
  const passwordMatches = await PasswordUtil.verify(
    body.currentPassword,
    existing.password_hash,
  );
  if (!passwordMatches) {
    throw new HttpException("Unauthorized: current password is incorrect", 403);
  }

  // Hash the new password
  const newPasswordHash = await PasswordUtil.hash(body.newPassword);

  // Single consistent timestamp for DB writes and audit
  const now = toISOStringSafe(new Date());

  // Update moderator password_hash and updated_at
  const updated = await MyGlobal.prisma.discussion_board_moderator.update({
    where: { id: moderator.id },
    data: {
      password_hash: newPasswordHash,
      updated_at: now,
    },
  });

  // Revoke all active sessions by setting expired_at to now
  await MyGlobal.prisma.discussion_board_moderator_sessions.updateMany({
    where: {
      discussion_board_moderator_id: moderator.id,
      expired_at: null,
    },
    data: {
      expired_at: now,
    },
  });

  // Create an audit entry for the password change
  await MyGlobal.prisma.discussion_board_moderation_audit.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      actor_moderator_id: moderator.id,
      event_type: "moderation.password_change",
      event_payload: JSON.stringify({ moderator_id: moderator.id }),
      occurred_at: now,
    },
  });

  // Return moderator summary (never include password_hash)
  return {
    id: updated.id as string & tags.Format<"uuid">,
    username: updated.username,
    email: updated.email as string & tags.Format<"email">,
    display_name: updated.display_name ?? null,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function postDiscussionBoardMemberArticlesArticleIdAttachments(props: {
  member: MemberPayload;
  articleId: string & tags.Format<"uuid">;
  body: IDiscussionBoardAttachment.ICreate;
}): Promise<IDiscussionBoardAttachment> {
  const { member, articleId, body } = props;

  const article = await MyGlobal.prisma.discussion_board_articles.findUnique({
    where: { id: articleId },
    select: { id: true, discussion_board_member_id: true, deleted_at: true },
  });
  if (!article)
    throw new HttpException("Not Found: article does not exist", 404);
  if (article.deleted_at !== null)
    throw new HttpException("Not Found: article is deleted", 404);

  if (article.discussion_board_member_id !== member.id) {
    throw new HttpException(
      "Forbidden: only the article author may upload attachments",
      403,
    );
  }

  const allowedMimeTypes = new Set<string>([
    "image/jpeg",
    "image/png",
    "image/gif",
    "image/webp",
    "application/pdf",
    "text/plain",
    "application/msword",
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  ]);
  if (!allowedMimeTypes.has(body.mime_type)) {
    throw new HttpException("Bad Request: unsupported mime type", 400);
  }

  const IMAGE_LIMIT = 5_242_880;
  const DOC_LIMIT = 20_971_520;
  if (body.is_image) {
    if (body.size > IMAGE_LIMIT)
      throw new HttpException(
        "Payload Too Large: image exceeds 5 MB limit",
        413,
      );
  } else {
    if (body.size > DOC_LIMIT)
      throw new HttpException(
        "Payload Too Large: document exceeds 20 MB limit",
        413,
      );
  }

  const totalCount = await MyGlobal.prisma.discussion_board_attachments.count({
    where: { discussion_board_article_id: articleId, deleted_at: null },
  });
  if (totalCount + 1 > 5)
    throw new HttpException(
      "Conflict: attachment quota (max 5) exceeded for this article",
      409,
    );

  const imageCount = await MyGlobal.prisma.discussion_board_attachments.count({
    where: {
      discussion_board_article_id: articleId,
      is_image: true,
      deleted_at: null,
    },
  });
  if (body.is_image && imageCount + 1 > 3)
    throw new HttpException(
      "Conflict: image quota (max 3) exceeded for this article",
      409,
    );

  const now = toISOStringSafe(new Date());
  const attachmentId = v4() as string & tags.Format<"uuid">;
  const auditId = v4() as string & tags.Format<"uuid">;

  const [created] = await MyGlobal.prisma.$transaction([
    MyGlobal.prisma.discussion_board_attachments.create({
      data: {
        id: attachmentId,
        discussion_board_article_id: articleId,
        discussion_board_member_id: member.id,
        original_filename: body.original_filename,
        storage_key: body.storage_key,
        mime_type: body.mime_type,
        size: body.size,
        is_image: body.is_image ?? false,
        created_at: now,
        deleted_at: null,
      },
    }),
    MyGlobal.prisma.discussion_board_audit_logs.create({
      data: {
        id: auditId,
        event_type: "attachment.uploaded",
        metadata: JSON.stringify({
          attachment_id: attachmentId,
          article_id: articleId,
          member_id: member.id,
          original_filename: body.original_filename,
        }),
        event_timestamp: now,
        resource_type: "article",
        resource_id: articleId,
        actor_type: "member",
        actor_id: member.id,
        created_at: now,
        updated_at: now,
      },
    }),
  ]);

  const uploader = await MyGlobal.prisma.discussion_board_member.findUnique({
    where: { id: member.id },
    select: { id: true, username: true, display_name: true, created_at: true },
  });

  const response: IDiscussionBoardAttachment = {
    id: created.id as string & tags.Format<"uuid">,
    article_id: created.discussion_board_article_id as string &
      tags.Format<"uuid">,
    original_filename: created.original_filename,
    storage_key: created.storage_key,
    mime_type: created.mime_type,
    size: created.size,
    is_image: created.is_image,
    created_at: now,
    deleted_at: created.deleted_at
      ? toISOStringSafe(created.deleted_at)
      : undefined,
    uploader: uploader
      ? {
          id: uploader.id as string & tags.Format<"uuid">,
          username: uploader.username,
          display_name: uploader.display_name ?? null,
          created_at: toISOStringSafe(uploader.created_at),
        }
      : undefined,
  };

  return response;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function postDiscussionBoardModeratorTags(props: {
  moderator: ModeratorPayload;
  body: IDiscussionBoardTag.ICreate;
}): Promise<IDiscussionBoardTag> {
  const { moderator, body } = props;

  const moderatorRecord =
    await MyGlobal.prisma.discussion_board_moderator.findUnique({
      where: { id: moderator.id },
    });

  if (!moderatorRecord || moderatorRecord.deleted_at) {
    throw new HttpException("Unauthorized: moderator not found", 403);
  }

  const normalizedSlug = body.slug.toLowerCase();
  const now = toISOStringSafe(new Date());

  try {
    const created = await MyGlobal.prisma.discussion_board_tags.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        name: body.name,
        slug: normalizedSlug,
        description: body.description ?? null,
        is_active: body.is_active ?? true,
        created_at: now,
        updated_at: now,
        deleted_at: null,
      },
    });

    await MyGlobal.prisma.discussion_board_moderation_audit.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        moderation_action_id: null,
        report_id: null,
        actor_moderator_id: moderator.id,
        event_type: "tag.create",
        event_payload: JSON.stringify({
          tag_id: created.id,
          name: created.name,
          slug: created.slug,
          description: created.description,
          is_active: created.is_active,
          created_by: moderator.id,
        }),
        occurred_at: now,
      },
    });

    return {
      id: created.id as string & tags.Format<"uuid">,
      name: created.name,
      slug: created.slug,
      description: created.description ?? null,
      is_active: created.is_active,
      sort_order: null,
      created_at: toISOStringSafe(created.created_at),
      updated_at: toISOStringSafe(created.updated_at),
      deleted_at: created.deleted_at
        ? toISOStringSafe(created.deleted_at)
        : null,
    };
  } catch (error) {
    if (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === "P2002"
    ) {
      const targets = (error.meta && (error.meta.target as string[])) || [];
      if (targets.includes("slug"))
        throw new HttpException("Conflict: tag slug already exists", 409);
      if (targets.includes("name"))
        throw new HttpException("Conflict: tag name already exists", 409);
      throw new HttpException("Conflict: Unique constraint violation", 409);
    }

    throw new HttpException("Internal Server Error", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function putDiscussionBoardMemberArticlesArticleId(props: {
  member: MemberPayload;
  articleId: string & tags.Format<"uuid">;
  body: IDiscussionBoardArticle.IUpdate;
}): Promise<IDiscussionBoardArticle> {
  const { member, articleId, body } = props;

  const article = await MyGlobal.prisma.discussion_board_articles.findUnique({
    where: { id: articleId },
  });
  if (!article || article.deleted_at !== null)
    throw new HttpException("Not Found", 404);

  if (article.discussion_board_member_id !== member.id) {
    throw new HttpException(
      "Unauthorized: Only the author may update this article",
      403,
    );
  }

  const EDIT_WINDOW_MS = 15 * 60 * 1000;
  const createdAtMs = new Date(article.created_at).getTime();
  const nowMs = Date.now();
  if (nowMs - createdAtMs > EDIT_WINDOW_MS) {
    throw new HttpException("Forbidden: Edit window expired", 403);
  }

  let resolvedCategoryId: string | null | undefined = undefined;
  if (body.category_slug !== undefined) {
    if (body.category_slug === null) {
      resolvedCategoryId = null;
    } else {
      const cat = await MyGlobal.prisma.discussion_board_categories.findFirst({
        where: { slug: body.category_slug, deleted_at: null, is_active: true },
      });
      if (!cat) throw new HttpException("Category not found", 400);
      resolvedCategoryId = cat.id;
    }
  }

  let tagIdsToAdd: string[] = [];
  let tagIdsToDelete: string[] = [];
  if (body.tag_slugs !== undefined) {
    const provided = body.tag_slugs ?? [];
    if (provided.length > 10)
      throw new HttpException("Too many tags (max 10)", 400);

    const found = await MyGlobal.prisma.discussion_board_tags.findMany({
      where: { slug: { in: provided }, deleted_at: null, is_active: true },
    });

    const uniqProvided = Array.from(
      new Set(provided.filter((s) => s !== null && s !== undefined)),
    );
    if (found.length !== uniqProvided.length)
      throw new HttpException("One or more tags not found or inactive", 400);

    const currentLinks =
      await MyGlobal.prisma.discussion_board_article_tags.findMany({
        where: { discussion_board_article_id: articleId },
      });
    const currentTagIds = currentLinks.map((r) => r.discussion_board_tag_id);
    const desiredTagIds = found.map((t) => t.id);

    tagIdsToAdd = desiredTagIds.filter((id) => !currentTagIds.includes(id));
    tagIdsToDelete = currentTagIds.filter((id) => !desiredTagIds.includes(id));
  }

  const now = toISOStringSafe(new Date());
  const updatePayload = {
    ...(body.title !== undefined && { title: body.title }),
    ...(body.content !== undefined && { content: body.content }),
    ...(body.state !== undefined && { state: body.state }),
    ...(body.is_pinned !== undefined && { is_pinned: body.is_pinned }),
    ...(body.category_slug !== undefined && {
      discussion_board_category_id: resolvedCategoryId,
    }),
    updated_at: now,
    ...(body.state === "published" &&
      article.published_at === null && { published_at: now }),
  };

  const snapshotCreate =
    MyGlobal.prisma.discussion_board_article_snapshots.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        discussion_board_article_id: articleId,
        title: article.title,
        content: article.content,
        state: article.state,
        snapshot_at: now,
        created_at: toISOStringSafe(article.created_at),
        updated_at: toISOStringSafe(article.updated_at),
        deleted_at: article.deleted_at
          ? toISOStringSafe(article.deleted_at)
          : null,
      },
    });

  const updateResult = MyGlobal.prisma.discussion_board_articles.updateMany({
    where: { id: articleId, updated_at: article.updated_at },
    data: updatePayload,
  });

  const [, updateRes] = await MyGlobal.prisma.$transaction([
    snapshotCreate,
    updateResult,
  ]);
  if (updateRes.count === 0)
    throw new HttpException("Conflict: concurrent modification", 409);

  if (body.tag_slugs !== undefined) {
    const deletes = tagIdsToDelete.map((tagId) =>
      MyGlobal.prisma.discussion_board_article_tags.deleteMany({
        where: {
          discussion_board_article_id: articleId,
          discussion_board_tag_id: tagId,
        },
      }),
    );

    const creates = tagIdsToAdd.map((tagId) =>
      MyGlobal.prisma.discussion_board_article_tags.create({
        data: {
          id: v4() as string & tags.Format<"uuid">,
          discussion_board_article_id: articleId,
          discussion_board_tag_id: tagId,
          created_at: now,
          created_by_member_id: member.id,
        },
      }),
    );

    await MyGlobal.prisma.$transaction([...deletes, ...creates]);
  }

  const updated =
    await MyGlobal.prisma.discussion_board_articles.findUniqueOrThrow({
      where: { id: articleId },
      include: {
        author: true,
        discussion_board_attachments: { include: { uploader: true } },
        category: true,
        discussion_board_article_tags: { include: { tag: true } },
      },
    });

  return {
    id: updated.id as string & tags.Format<"uuid">,
    title: updated.title,
    content: updated.content,
    author: updated.author
      ? {
          id: updated.author.id as string & tags.Format<"uuid">,
          username: updated.author.username,
          display_name: updated.author.display_name ?? null,
          created_at: toISOStringSafe(updated.author.created_at),
        }
      : null,
    is_pinned: updated.is_pinned,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    attachments: (updated.discussion_board_attachments ?? []).map((a) => ({
      id: a.id as string & tags.Format<"uuid">,
      original_filename: a.original_filename,
      mime_type: a.mime_type,
      size: a.size,
      is_image: a.is_image,
      created_at: toISOStringSafe(a.created_at),
      uploader: a.uploader
        ? {
            id: a.uploader.id as string & tags.Format<"uuid">,
            username: a.uploader.username,
            display_name: a.uploader.display_name ?? null,
            created_at: toISOStringSafe(a.uploader.created_at),
          }
        : null,
      downloadUrl: null,
      cdnUrl: null,
    })),
    state: updated.state as "draft" | "published" | "pending_review" | "hidden",
    published_at: updated.published_at
      ? toISOStringSafe(updated.published_at)
      : null,
    category: updated.category
      ? {
          id: updated.category.id as string & tags.Format<"uuid">,
          name: updated.category.name,
          slug: updated.category.slug,
          description: updated.category.description ?? null,
          is_active: updated.category.is_active,
          sort_order: updated.category.sort_order ?? null,
          created_at: toISOStringSafe(updated.category.created_at),
          updated_at: updated.category.updated_at
            ? toISOStringSafe(updated.category.updated_at)
            : null,
          deleted_at: updated.category.deleted_at
            ? toISOStringSafe(updated.category.deleted_at)
            : null,
        }
      : undefined,
    tags: (updated.discussion_board_article_tags ?? []).map((rel) => ({
      id: rel.tag.id as string & tags.Format<"uuid">,
      name: rel.tag.name,
      slug: rel.tag.slug,
      description: rel.tag.description ?? null,
      is_active: rel.tag.is_active,
      created_at: toISOStringSafe(rel.tag.created_at),
      updated_at: rel.tag.updated_at
        ? toISOStringSafe(rel.tag.updated_at)
        : null,
      deleted_at: rel.tag.deleted_at
        ? toISOStringSafe(rel.tag.deleted_at)
        : null,
    })),
  };
}

