import { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function putDiscussionBoardMemberArticlesArticleIdCommentsCommentId(props: {
  member: MemberPayload;
  articleId: string & tags.Format<"uuid">;
  commentId: string & tags.Format<"uuid">;
  body: IDiscussionBoardComment.IUpdate;
}): Promise<IDiscussionBoardComment> {
  const { member, articleId, commentId, body } = props;

  const existing = await MyGlobal.prisma.discussion_board_comments.findFirst({
    where: {
      id: commentId,
      discussion_board_article_id: articleId,
      deleted_at: null,
    },
  });

  if (!existing) throw new HttpException("Not Found", 404);

  if (existing.discussion_board_author_id !== member.id) {
    throw new HttpException(
      "Unauthorized: You can only edit your own comment",
      403,
    );
  }

  const envRecord = MyGlobal.env as unknown as Record<string, unknown>;
  const editWindowMs =
    Number(envRecord["COMMENT_EDIT_WINDOW_MS"] ?? 15 * 60 * 1000) ||
    15 * 60 * 1000;

  const createdAtMs = Date.parse(toISOStringSafe(existing.created_at));
  const nowMs = Date.parse(toISOStringSafe(new Date()));
  if (nowMs - createdAtMs > editWindowMs) {
    throw new HttpException("Edit window expired", 409);
  }

  const nowIso = toISOStringSafe(new Date());

  const [updated] = await MyGlobal.prisma.$transaction([
    MyGlobal.prisma.discussion_board_comments.update({
      where: { id: commentId },
      data: {
        content: body.content ?? undefined,
        updated_at: nowIso,
      },
      select: {
        id: true,
        discussion_board_article_id: true,
        discussion_board_parent_comment_id: true,
        discussion_board_author_id: true,
        content: true,
        is_hidden: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
        author: {
          select: {
            id: true,
            username: true,
            display_name: true,
            created_at: true,
          },
        },
      },
    }),
    MyGlobal.prisma.discussion_board_moderation_audit.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        event_type: "comment.updated",
        event_payload: JSON.stringify({
          commentId,
          articleId,
          authorId: member.id,
          before: existing.content,
          after: body.content,
        }),
        occurred_at: nowIso,
      },
    }),
  ]);

  const result: IDiscussionBoardComment = {
    id: updated.id as string & tags.Format<"uuid">,
    articleId: updated.discussion_board_article_id as string &
      tags.Format<"uuid">,
    parentCommentId:
      updated.discussion_board_parent_comment_id === null
        ? undefined
        : (updated.discussion_board_parent_comment_id as string &
            tags.Format<"uuid">),
    author: updated.author
      ? {
          id: updated.author.id as string & tags.Format<"uuid">,
          username: updated.author.username,
          display_name: updated.author.display_name ?? null,
          created_at: toISOStringSafe(updated.author.created_at),
        }
      : null,
    content: updated.content,
    isHidden: updated.is_hidden,
    createdAt: toISOStringSafe(updated.created_at),
    updatedAt: toISOStringSafe(updated.updated_at),
    deletedAt: updated.deleted_at
      ? toISOStringSafe(updated.deleted_at)
      : undefined,
  };

  return result;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function putDiscussionBoardModeratorTagsTagSlug(props: {
  moderator: ModeratorPayload;
  tagSlug: string;
  body: IDiscussionBoardTag.IUpdate;
}): Promise<IDiscussionBoardTag> {
  const { moderator, tagSlug, body } = props;

  // Reject attempts to change immutable slug
  if ("slug" in body) {
    throw new HttpException("Bad Request: 'slug' is immutable", 400);
  }

  // Verify moderator exists and is active
  const moderatorRecord =
    await MyGlobal.prisma.discussion_board_moderator.findUnique({
      where: { id: moderator.id },
      select: { id: true, deleted_at: true },
    });
  if (!moderatorRecord || moderatorRecord.deleted_at !== null) {
    throw new HttpException("Unauthorized: invalid moderator", 403);
  }

  // Find existing tag by slug
  const existing = await MyGlobal.prisma.discussion_board_tags.findUnique({
    where: { slug: tagSlug },
  });
  if (!existing) {
    throw new HttpException("Not Found", 404);
  }

  // If name provided, ensure uniqueness across tags (excluding current)
  if (body.name !== undefined) {
    const conflict = await MyGlobal.prisma.discussion_board_tags.findFirst({
      where: {
        name: body.name,
        NOT: { id: existing.id },
      },
    });
    if (conflict) {
      throw new HttpException("Conflict: tag name already exists", 409);
    }
  }

  const now = toISOStringSafe(new Date());

  try {
    const updated = await MyGlobal.prisma.discussion_board_tags.update({
      where: { slug: tagSlug },
      data: {
        ...(body.name !== undefined && { name: body.name }),
        ...(body.description !== undefined && {
          description: body.description,
        }),
        ...(body.is_active !== undefined && { is_active: body.is_active }),
        updated_at: now,
      },
    });

    // Record moderation audit entry for traceability
    await MyGlobal.prisma.discussion_board_moderation_audit.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        actor_moderator_id: moderator.id,
        event_type: "moderation.tag.update",
        event_payload: JSON.stringify({
          action_type: "update",
          target_type: "tag",
          target_id: updated.id,
          before: {
            id: existing.id,
            name: existing.name,
            slug: existing.slug,
            description: existing.description,
            is_active: existing.is_active,
            created_at: toISOStringSafe(existing.created_at),
            updated_at: toISOStringSafe(existing.updated_at),
            deleted_at: existing.deleted_at
              ? toISOStringSafe(existing.deleted_at)
              : null,
          },
          after: {
            id: updated.id,
            name: updated.name,
            slug: updated.slug,
            description: updated.description,
            is_active: updated.is_active,
            created_at: toISOStringSafe(updated.created_at),
            updated_at: toISOStringSafe(updated.updated_at),
            deleted_at: updated.deleted_at
              ? toISOStringSafe(updated.deleted_at)
              : null,
          },
          moderator_id: moderator.id,
        }),
        occurred_at: now,
      },
    });

    return {
      id: updated.id as string & tags.Format<"uuid">,
      name: updated.name,
      slug: updated.slug,
      description:
        updated.description === null
          ? null
          : (updated.description ?? undefined),
      is_active: updated.is_active,
      created_at: toISOStringSafe(updated.created_at),
      updated_at: toISOStringSafe(updated.updated_at),
      deleted_at: updated.deleted_at
        ? toISOStringSafe(updated.deleted_at)
        : undefined,
    };
  } catch (err) {
    if (
      err instanceof Prisma.PrismaClientKnownRequestError &&
      err.code === "P2002"
    ) {
      throw new HttpException("Conflict: unique constraint violation", 409);
    }
    throw new HttpException("Internal Server Error", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardSubscription } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSubscription";
import { IPageIDiscussionBoardSubscription } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardSubscription";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function patchDiscussionBoardMemberMembersMemberUsernameSubscriptions(props: {
  member: MemberPayload;
  memberUsername: string;
  body: IDiscussionBoardSubscription.IRequest;
}): Promise<IPageIDiscussionBoardSubscription.ISummary> {
  try {
    const { member, memberUsername, body } = props;

    // Resolve target member by username
    const target = await MyGlobal.prisma.discussion_board_member.findUnique({
      where: { username: memberUsername },
      select: { id: true },
    });
    if (!target) throw new HttpException("Not Found", 404);

    // Authorization: only the owner may list their subscriptions
    if (member.id !== target.id) {
      throw new HttpException(
        "Unauthorized: cannot list another member's subscriptions",
        403,
      );
    }

    // Pagination defaults and validation
    const page = (body && body.page) ?? 1;
    const limit = (body && body.limit) ?? 20;
    if (!(Number.isFinite(page) && page >= 1)) {
      throw new HttpException("Bad Request: page must be >= 1", 400);
    }
    if (!(Number.isFinite(limit) && limit >= 1 && limit <= 100)) {
      throw new HttpException(
        "Bad Request: limit must be between 1 and 100",
        400,
      );
    }

    // Build where conditions inline
    const whereCondition: Record<string, unknown> = {
      discussion_board_member_id: target.id,
      deleted_at: null,
    };

    if (body && body.deliveryMode !== undefined && body.deliveryMode !== null) {
      whereCondition.delivery_mode = body.deliveryMode;
    }
    if (body && body.active !== undefined && body.active !== null) {
      whereCondition.active = body.active;
    }
    if (body && body.search !== undefined && body.search !== null) {
      const s = body.search;
      // If search looks like a UUID (36-char dashed), filter by target_id exact match
      const uuidLike =
        typeof s === "string" &&
        /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(
          s,
        );
      if (uuidLike) whereCondition.target_id = s;
    }

    // Perform count and fetch in parallel
    const [total, results] = await Promise.all([
      MyGlobal.prisma.discussion_board_subscriptions.count({
        where: whereCondition,
      }),
      MyGlobal.prisma.discussion_board_subscriptions.findMany({
        where: whereCondition,
        orderBy: { created_at: "desc" },
        skip: (page - 1) * limit,
        take: limit,
        include: {
          member: {
            select: {
              id: true,
              username: true,
              display_name: true,
              created_at: true,
            },
          },
        },
      }),
    ]);

    const data = results.map((r) => ({
      id: r.id,
      member: {
        id: r.member.id,
        username: r.member.username,
        display_name:
          r.member.display_name === null ? null : r.member.display_name,
        created_at: toISOStringSafe(r.member.created_at),
      },
      targetType: typia.assert<"author" | "article">(r.target_type),
      targetId: r.target_id,
      deliveryMode: typia.assert<"immediate" | "daily_digest">(r.delivery_mode),
      active: r.active,
      lastNotifiedAt: r.last_notified_at
        ? toISOStringSafe(r.last_notified_at)
        : null,
      createdAt: toISOStringSafe(r.created_at),
      updatedAt: r.updated_at ? toISOStringSafe(r.updated_at) : null,
      deletedAt: r.deleted_at ? toISOStringSafe(r.deleted_at) : null,
    }));

    const pages = Math.ceil(total / limit);

    return {
      pagination: {
        current: Number(page),
        limit: Number(limit),
        records: total,
        pages: Number(pages),
      },
      data,
    };
  } catch (err) {
    if (err instanceof HttpException) throw err;
    throw new HttpException("Internal Server Error", 500);
  }
}

