                created_at: true,
                updated_at: true,
                deleted_at: true,
              },
            },
          },
        },
        report: {
          select: {
            id: true,
            reason_category: true,
            target_type: true,
            target_id: true,
            created_at: true,
            processed_at: true,
            closed_at: true,
          },
        },
      },
      orderBy,
      take: limit,
      skip,
      ...(useCursor ? { cursor } : {}),
    } as any),

    MyGlobal.prisma.discussion_board_appeals.count({
      where: whereCondition as any,
    }),
  ]);

  // Map to DTO summaries
  const data = rows.map((r) => {
    const appellant = (r as any).appellantMember
      ? {
          id: (r as any).appellantMember.id,
          username: (r as any).appellantMember.username,
          display_name: (r as any).appellantMember.display_name ?? null,
          created_at: toISOStringSafe((r as any).appellantMember.created_at),
        }
      : (null as any);

    const moderation_action = (r as any).moderationAction
      ? {
          id: (r as any).moderationAction.id,
          action_type: (r as any).moderationAction.action_type,
          action_reason: (r as any).moderationAction.action_reason ?? null,
          action_duration_days:
            (r as any).moderationAction.action_duration_days ?? null,
          target_type: (r as any).moderationAction.target_type ?? null,
          target_id: (r as any).moderationAction.target_id ?? null,
          moderator: (r as any).moderationAction.moderator
            ? {
                id: (r as any).moderationAction.moderator.id,
                username: (r as any).moderationAction.moderator.username,
                display_name:
                  (r as any).moderationAction.moderator.display_name ?? null,
                created_at: toISOStringSafe(
                  (r as any).moderationAction.moderator.created_at,
                ),
                updated_at: toISOStringSafe(
                  (r as any).moderationAction.moderator.updated_at,
                ),
                deleted_at: (r as any).moderationAction.moderator.deleted_at
                  ? toISOStringSafe(
                      (r as any).moderationAction.moderator.deleted_at,
                    )
                  : null,
              }
            : (null as any),
          created_at: toISOStringSafe((r as any).moderationAction.created_at),
          effective_from: (r as any).moderationAction.effective_from
            ? toISOStringSafe((r as any).moderationAction.effective_from)
            : null,
          effective_until: (r as any).moderationAction.effective_until
            ? toISOStringSafe((r as any).moderationAction.effective_until)
            : null,
        }
      : null;

    const report = (r as any).report
      ? {
          id: (r as any).report.id,
          reasonCategory: (r as any).report.reason_category,
          targetType: (r as any).report.target_type,
          targetId: (r as any).report.target_id,
          createdAt: toISOStringSafe((r as any).report.created_at),
          processedAt: (r as any).report.processed_at
            ? toISOStringSafe((r as any).report.processed_at)
            : null,
          closedAt: (r as any).report.closed_at
            ? toISOStringSafe((r as any).report.closed_at)
            : null,
          explanationExcerpt: (r as any).explanation
            ? (r as any).explanation.length > 500
              ? (r as any).explanation.slice(0, 500)
              : (r as any).explanation
            : null,
        }
      : null;

    return {
      id: (r as any).id,
      appellant: appellant as IDiscussionBoardMember.ISummary,
      status: (r as any).status as any,
      created_at: toISOStringSafe((r as any).created_at),
      resolved_at: (r as any).resolved_at
        ? toISOStringSafe((r as any).resolved_at)
        : null,
      moderation_action:
        moderation_action as unknown as IDiscussionBoardModerationAction.ISummary | null,
      report: report as unknown as IDiscussionBoardReport.ISummary | null,
      resolution_reason: (r as any).resolution_reason ?? null,
      explanation_excerpt: (r as any).explanation
        ? (r as any).explanation.length > 500
          ? (r as any).explanation.slice(0, 500)
          : (r as any).explanation
        : null,
    } satisfies IDiscussionBoardAppeal.ISummary;
  });

  // Audit: record the listing request
  const now = toISOStringSafe(new Date());
  const audit = await MyGlobal.prisma.discussion_board_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      event_type: "appeals.list",
      event_timestamp: now,
      actor_type: "moderator",
      actor_id: moderator.id,
      ip: null,
      user_agent: null,
      metadata: JSON.stringify({ query: body }),
      resource_type: null,
      resource_id: null,
      created_at: now,
      updated_at: now,
    },
    select: { id: true },
  });

  await MyGlobal.prisma.discussion_board_audit_log_accesses.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      discussion_board_audit_log_id: audit.id,
      accessed_at: now,
      accessor_type: "moderator",
      accessor_id: moderator.id,
      accessor_role: "moderator",
      access_purpose: "appeals.search",
      ip: null,
      user_agent: null,
      metadata: JSON.stringify({ query: body }),
      created_at: now,
    },
  });

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / Number(limit)),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardSearch } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSearch";
import { IPageIDiscussionBoardSearchResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardSearchResult";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IDiscussionBoardSearchResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSearchResult";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";

export async function patchDiscussionBoardSearchGlobal(props: {
  body: IDiscussionBoardSearch.IRequest;
}): Promise<IPageIDiscussionBoardSearchResult.ISummary> {
  const { body } = props;

  // Pagination defaults and bounds
  const page = Number(body.page ?? 1);
  const limit = Math.min(Number(body.limit ?? 20), 100);
  const skip = (page - 1) * limit;

  // Determine which resource types to query
  const typesFilter = body.filters?.types;
  const search = body.query;

  // Build promises for each type (conditionally included)
  const articlePromise =
    typesFilter === undefined || typesFilter.includes("article")
      ? MyGlobal.prisma.discussion_board_articles.findMany({
          where: {
            deleted_at: null,
            state: "published",
            ...(body.filters?.categoryId !== undefined &&
              body.filters?.categoryId !== null && {
                discussion_board_category_id: body.filters?.categoryId,
              }),
            ...(body.filters?.authorUsername !== undefined &&
              body.filters?.authorUsername !== null && {
                author: { username: body.filters?.authorUsername },
              }),
            ...(body.filters?.tagSlugs !== undefined &&
              body.filters?.tagSlugs !== null &&
              body.filters?.tagSlugs.length > 0 && {
                discussion_board_article_tags: {
                  some: {
                    tag: { slug: { in: body.filters?.tagSlugs } },
                  },
                },
              }),
            ...(search && {
              OR: [
                { title: { contains: search } },
                { content: { contains: search } },
              ],
            }),
            ...(body.filters?.createdFrom !== undefined &&
              body.filters?.createdFrom !== null && {
                published_at: { gte: body.filters?.createdFrom },
              }),
            ...(body.filters?.createdTo !== undefined &&
              body.filters?.createdTo !== null && {
                published_at: { lte: body.filters?.createdTo },
              }),
          },
          include: {
            author: true,
            category: true,
            discussion_board_article_tags: { include: { tag: true } },
          },
          orderBy:
            body.sort === "oldest"
              ? { published_at: "asc" }
              : { published_at: "desc" },
          skip,
          take: limit,
        })
      : Promise.resolve([]);

  const commentPromise =
    typesFilter === undefined || typesFilter.includes("comment")
      ? MyGlobal.prisma.discussion_board_comments.findMany({
          where: {
            deleted_at: null,
            is_hidden: false,
            ...(search && { content: { contains: search } }),
            ...(body.filters?.createdFrom !== undefined &&
              body.filters?.createdFrom !== null && {
                created_at: { gte: body.filters?.createdFrom },
              }),
            ...(body.filters?.createdTo !== undefined &&
              body.filters?.createdTo !== null && {
                created_at: { lte: body.filters?.createdTo },
              }),
            ...(body.filters?.authorUsername !== undefined &&
              body.filters?.authorUsername !== null && {
                author: { username: body.filters?.authorUsername },
              }),
          },
          include: { article: true, author: true },
          orderBy:
            body.sort === "oldest"
              ? { created_at: "asc" }
              : { created_at: "desc" },
          skip,
          take: limit,
        })
      : Promise.resolve([]);

  const attachmentPromise =
    typesFilter === undefined || typesFilter.includes("attachment")
      ? MyGlobal.prisma.discussion_board_attachments.findMany({
          where: {
            deleted_at: null,
            ...(search && { original_filename: { contains: search } }),
            ...(body.filters?.createdFrom !== undefined &&
              body.filters?.createdFrom !== null && {
                created_at: { gte: body.filters?.createdFrom },
              }),
            ...(body.filters?.createdTo !== undefined &&
              body.filters?.createdTo !== null && {
                created_at: { lte: body.filters?.createdTo },
              }),
          },
          include: { article: true },
          orderBy:
            body.sort === "oldest"
              ? { created_at: "asc" }
              : { created_at: "desc" },
          skip,
          take: limit,
        })
      : Promise.resolve([]);

  const tagPromise =
    typesFilter === undefined || typesFilter.includes("tag")
      ? MyGlobal.prisma.discussion_board_tags.findMany({
          where: {
            deleted_at: null,
            ...(search && {
              OR: [
                { name: { contains: search } },
                { slug: { contains: search } },
              ],
            }),
          },
          orderBy:
            body.sort === "oldest"
              ? { created_at: "asc" }
              : { created_at: "desc" },
          skip,
          take: limit,
        })
      : Promise.resolve([]);

  const [articles, comments, attachments, tags] = await Promise.all([
    articlePromise,
    commentPromise,
    attachmentPromise,
    tagPromise,
  ]);

  // Map DB rows to unified search summaries
  const mappedArticles = articles.map((a) => ({
    id: a.id,
    title: a.title ?? "",
    excerpt: a.content
      ? a.content.length > 300
        ? a.content.slice(0, 300) + "..."
        : a.content
      : null,
    author: a.author
      ? {
          id: a.author.id,
          username: a.author.username,
          display_name: a.author.display_name ?? null,
          created_at: toISOStringSafe(a.author.created_at),
        }
      : null,
    category: a.category
      ? {
          id: a.category.id,
          name: a.category.name,
          slug: a.category.slug,
          description: a.category.description ?? "",
          is_active: a.category.is_active,
          sort_order: a.category.sort_order ?? null,
          created_at: toISOStringSafe(a.category.created_at),
          updated_at: a.category.updated_at
            ? toISOStringSafe(a.category.updated_at)
            : null,
          deleted_at: a.category.deleted_at
            ? toISOStringSafe(a.category.deleted_at)
            : null,
        }
      : null,
    tags: (a.discussion_board_article_tags ?? []).map((t) => ({
      id: t.tag.id,
      name: t.tag.name,
      slug: t.tag.slug,
      description: t.tag.description ?? null,
      is_active: t.tag.is_active,
      created_at: toISOStringSafe(t.tag.created_at),
      updated_at: t.tag.updated_at ? toISOStringSafe(t.tag.updated_at) : null,
      deleted_at: t.tag.deleted_at ? toISOStringSafe(t.tag.deleted_at) : null,
    })),
    is_pinned: a.is_pinned,
    created_at: toISOStringSafe(a.created_at),
    published_at: a.published_at ? toISOStringSafe(a.published_at) : null,
  }));

  const mappedComments = comments.map((c) => ({
    id: c.id,
    title: c.article?.title ?? "",
    excerpt: c.content
      ? c.content.length > 300
        ? c.content.slice(0, 300) + "..."
        : c.content
      : null,
    author: c.author
      ? {
          id: c.author.id,
          username: c.author.username,
          display_name: c.author.display_name ?? null,
          created_at: toISOStringSafe(c.author.created_at),
        }
      : null,
    category:
      c.article && c.article.discussion_board_category_id
        ? {
            id: c.article.discussion_board_category_id,
            // Provide non-null defaults to satisfy ISummary's required string fields
            name: "",
            slug: "",
            description: "",
            is_active: false,
            sort_order: null,
            created_at: toISOStringSafe(c.article.created_at),
            updated_at: null,
            deleted_at: null,
          }
        : null,
    tags: [],
    is_pinned: false,
    created_at: toISOStringSafe(c.created_at),
    published_at:
      c.article && c.article.published_at
        ? toISOStringSafe(c.article.published_at)
        : null,
  }));

  const mappedAttachments = attachments.map((f) => ({
    id: f.id,
    title: f.original_filename,
    excerpt: null,
    author: null,
    category:
      f.article && f.article.discussion_board_category_id
        ? {
            id: f.article.discussion_board_category_id,
            // Provide non-null defaults to satisfy ISummary's required string fields
            name: "",
            slug: "",
            description: "",
            is_active: false,
            sort_order: null,
            created_at: toISOStringSafe(f.article.created_at),
            updated_at: null,
            deleted_at: null,
          }
        : null,
    tags: [],
    is_pinned: false,
    created_at: toISOStringSafe(f.created_at),
    published_at: null,
    thumbnail: null,
  }));

  const mappedTags = tags.map((t) => ({
    id: t.id,
    title: t.name,
    excerpt: null,
    author: null,
    category: null,
    tags: [],
    is_pinned: false,
    created_at: toISOStringSafe(t.created_at),
    published_at: null,
  }));

  // Combine results and sort according to requested sort
  const combined = [
    ...mappedArticles,
    ...mappedComments,
    ...mappedAttachments,
    ...mappedTags,
  ];

  const sorted = combined.sort((a, b) => {
    if (body.sort === "oldest") {
      const at = a.created_at;
      const bt = b.created_at;
      if (at < bt) return -1;
      if (at > bt) return 1;
      return 0;
    }
    // newest or relevance default
    const at = a.published_at ?? a.created_at;
    const bt = b.published_at ?? b.created_at;
    if (at > bt) return -1;
    if (at < bt) return 1;
    return 0;
  });

  const total = sorted.length;
  const pageRecords = sorted.slice(skip, skip + limit);

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: Number(total),
      pages: Math.ceil(total / limit),
    },
    data: pageRecords,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardAuditLogAccess } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuditLogAccess";
import { IPageIDiscussionBoardAuditLogAccess } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAuditLogAccess";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import { IDiscussionBoardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuditLog";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function patchDiscussionBoardModeratorAuditLogsAuditLogIdAccesses(props: {
  moderator: ModeratorPayload;
  auditLogId: string & tags.Format<"uuid">;
  body: IDiscussionBoardAuditLogAccess.IRequest;
}): Promise<IPageIDiscussionBoardAuditLogAccess.ISummary> {
  const { moderator, auditLogId, body } = props;

  const moderatorRecord =
    await MyGlobal.prisma.discussion_board_moderator.findUnique({
      where: { id: moderator.id },
      select: { id: true },
    });
  if (!moderatorRecord) throw new HttpException("Unauthorized", 401);

  const auditLog = await MyGlobal.prisma.discussion_board_audit_logs.findUnique(
    {
      where: { id: auditLogId },
      select: {
        id: true,
        event_type: true,
        event_timestamp: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
      },
    },
  );
  if (!auditLog) throw new HttpException("Not Found", 404);

  const page = Number(body.page ?? 1);
  const limit = Math.min(Number(body.limit ?? 20), 100);
  const skip = (page - 1) * limit;

  const where: Record<string, unknown> = {
    discussion_board_audit_log_id: auditLogId,
  };
  if (body.accessorType !== undefined) where.accessor_type = body.accessorType;
  if (body.accessorId !== undefined && body.accessorId !== null)
    where.accessor_id = body.accessorId;
  if (body.accessPurpose !== undefined && body.accessPurpose !== null)
    where.access_purpose = body.accessPurpose;

  if (
    (body.accessedFrom !== undefined && body.accessedFrom !== null) ||
    (body.accessedTo !== undefined && body.accessedTo !== null)
  ) {
    const accessedAt: Record<string, unknown> = {};
    if (body.accessedFrom !== undefined && body.accessedFrom !== null)
      accessedAt.gte = toISOStringSafe(body.accessedFrom);
    if (body.accessedTo !== undefined && body.accessedTo !== null)
      accessedAt.lte = toISOStringSafe(body.accessedTo);
    if (Object.keys(accessedAt).length > 0) where.accessed_at = accessedAt;
  }

  const orderBy = body.sortBy
    ? body.sortBy === "accessedAt" || body.sortBy === "-accessedAt"
      ? body.sortBy.startsWith("-")
        ? { accessed_at: "desc" as Prisma.SortOrder }
        : { accessed_at: "asc" as Prisma.SortOrder }
      : body.sortBy === "createdAt" || body.sortBy === "-createdAt"
        ? body.sortBy.startsWith("-")
          ? { created_at: "desc" as Prisma.SortOrder }
          : { created_at: "asc" as Prisma.SortOrder }
        : { accessed_at: "desc" as Prisma.SortOrder }
    : { accessed_at: "desc" as Prisma.SortOrder };

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_audit_log_accesses.findMany({
      where,
      orderBy,
      skip,
      take: limit,
    }),
    MyGlobal.prisma.discussion_board_audit_log_accesses.count({ where }),
  ]);

  const envAllowsUnredacted = Boolean(
    (MyGlobal.env as any)?.UNREDACTED_AUDIT === "true",
  );

  const data: IDiscussionBoardAuditLogAccess.ISummary[] = await Promise.all(
    rows.map(async (r) => {
      const canViewPII =
        envAllowsUnredacted ||
        (r.accessor_id !== null && r.accessor_id === moderator.id);

      let accessorSummary:
        | IDiscussionBoardMember.ISummary
        | IDiscussionBoardModerator.ISummary
        | null = null;
      if (r.accessor_type === "moderator" && r.accessor_id) {
        const mod = await MyGlobal.prisma.discussion_board_moderator.findUnique(
          {
            where: { id: r.accessor_id },
            select: {
              id: true,
              username: true,
              display_name: true,
              created_at: true,
              updated_at: true,
              deleted_at: true,
            },
          },
        );
        if (mod) {
          accessorSummary = {
            id: mod.id as string & tags.Format<"uuid">,
            username: mod.username,
            display_name: mod.display_name ?? null,
            created_at: toISOStringSafe(mod.created_at),
            updated_at: toISOStringSafe(mod.updated_at),
            deleted_at: mod.deleted_at ? toISOStringSafe(mod.deleted_at) : null,
          } as IDiscussionBoardModerator.ISummary;
        }
      }

      const auditSummary: IDiscussionBoardAuditLog.ISummary = {
        id: auditLog.id as string & tags.Format<"uuid">,
        event_type: auditLog.event_type,
        event_timestamp: toISOStringSafe(auditLog.event_timestamp),
        created_at: toISOStringSafe(auditLog.created_at),
        updated_at: auditLog.updated_at
          ? toISOStringSafe(auditLog.updated_at)
          : null,
        deleted_at: (auditLog as any).deleted_at
          ? toISOStringSafe((auditLog as any).deleted_at)
          : null,
      } as IDiscussionBoardAuditLog.ISummary;

      const summary: IDiscussionBoardAuditLogAccess.ISummary = {
        id: r.id as string & tags.Format<"uuid">,
        accessed_at: toISOStringSafe(r.accessed_at),
        accessor_type: r.accessor_type,
        accessor_id: canViewPII
          ? (r.accessor_id as string & tags.Format<"uuid">)
          : null,
        accessor: accessorSummary ?? undefined,
        accessor_role: r.accessor_role ?? undefined,
        access_purpose: r.access_purpose ?? undefined,
        ip: canViewPII ? (r.ip ?? null) : null,
        user_agent: canViewPII ? (r.user_agent ?? null) : null,
        audit_log: auditSummary,
        created_at: toISOStringSafe(r.created_at),
      };

      return summary;
    }),
  );

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function postAuthModeratorJoin(props: {
  moderator: ModeratorPayload;
  body: IDiscussionBoardModerator.ICreate;
}): Promise<IDiscussionBoardModerator.IAuthorized> {
  const { moderator, body } = props;

  // Authorization required because moderator payload is provided
  const caller = await MyGlobal.prisma.discussion_board_moderator.findUnique({
    where: { id: moderator.id },
  });
  if (!caller || caller.deleted_at !== null) {
    throw new HttpException("Unauthorized: caller not found or inactive", 403);
  }

  // Uniqueness checks
  const existingByUsername =
    await MyGlobal.prisma.discussion_board_moderator.findFirst({
      where: { username: body.username },
    });
  if (existingByUsername)
    throw new HttpException("Username already registered", 409);

  const existingByEmail =
    await MyGlobal.prisma.discussion_board_moderator.findFirst({
      where: { email: body.email },
    });
  if (existingByEmail) throw new HttpException("Email already registered", 409);

  // Hash password
  const password_hash = await PasswordUtil.hash(body.password);

  // Prepare ids and timestamps
  const moderatorId = v4() as string & tags.Format<"uuid">;
  const sessionId = v4() as string & tags.Format<"uuid">;
  const now = toISOStringSafe(new Date());
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

  // Create moderator and session in transaction
  const [createdModerator, createdSession] = await MyGlobal.prisma.$transaction(
    [
      MyGlobal.prisma.discussion_board_moderator.create({
        data: {
          id: moderatorId,
          username: body.username,
          email: body.email,
          password_hash,
          display_name: body.display_name ?? null,
          // role and mfa_enabled DO NOT exist on discussion_board_moderator schema - removed
          created_at: now,
          updated_at: now,
          deleted_at: null,
        },
      }),
      MyGlobal.prisma.discussion_board_moderator_sessions.create({
        data: {
          id: sessionId,
          discussion_board_moderator_id: moderatorId,
          ip: body.ip ?? "",
          href: body.href,
          referrer: body.referrer,
          created_at: now,
          expired_at: toISOStringSafe(accessExpires),
        },
      }),
    ],
  );

  // Generate tokens
  const tokenCreatedAt = toISOStringSafe(new Date());

  const access = jwt.sign(
    {
      type: "moderator",
      id: createdModerator.id,
      session_id: createdSession.id,
      created_at: tokenCreatedAt,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "1h", issuer: "autobe" },
  );

  const refresh = jwt.sign(
    {
      type: "moderator",
      id: createdModerator.id,
      session_id: createdSession.id,
      tokenType: "refresh",
      created_at: tokenCreatedAt,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );

  const token: IAuthorizationToken = {
    access,
    refresh,
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  return {
    id: createdModerator.id,
    username: createdModerator.username,
    email: createdModerator.email,
    display_name: createdModerator.display_name ?? null,
    created_at: toISOStringSafe(createdModerator.created_at),
    updated_at: toISOStringSafe(createdModerator.updated_at),
    token,
    moderator: {
      id: createdModerator.id,
      username: createdModerator.username,
      display_name: createdModerator.display_name ?? null,
      created_at: toISOStringSafe(createdModerator.created_at),
      updated_at: toISOStringSafe(createdModerator.updated_at),
      deleted_at: createdModerator.deleted_at
        ? toISOStringSafe(createdModerator.deleted_at)
        : null,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthMemberRefresh(props: {
  body: IDiscussionBoardMember.IRefresh;
}): Promise<IDiscussionBoardMember.IAuthorized> {
  const { body } = props;

  const buildResponse = (
    memberRecord: any,
    accessToken: string,
    refreshToken: string,
    accessExpiresAt: string & tags.Format<"date-time">,
    refreshExpiresAt: string & tags.Format<"date-time">,
  ): IDiscussionBoardMember.IAuthorized => {
    return {
      id: memberRecord.id as string & tags.Format<"uuid">,
      username: memberRecord.username,
      email: memberRecord.email as string & tags.Format<"email">,
      display_name: memberRecord.display_name ?? null,
      role: memberRecord.role ?? undefined,
      mfa_enabled: memberRecord.mfa_enabled ?? undefined,
      created_at: toISOStringSafe(memberRecord.created_at),
      updated_at: memberRecord.updated_at
        ? toISOStringSafe(memberRecord.updated_at)
        : undefined,
      deleted_at: memberRecord.deleted_at
        ? toISOStringSafe(memberRecord.deleted_at)
        : null,
      token: {
        access: accessToken,
        refresh: refreshToken,
        expired_at: accessExpiresAt,
        refreshable_until: refreshExpiresAt,
      },
      member: {
        id: memberRecord.id as string & tags.Format<"uuid">,
        username: memberRecord.username,
        display_name: memberRecord.display_name ?? null,
        created_at: toISOStringSafe(memberRecord.created_at),
      },
    };
  };

  // common: compute expirations
  const accessExpiryDate = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpiryDate = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const accessExpires = toISOStringSafe(accessExpiryDate);
  const refreshExpires = toISOStringSafe(refreshExpiryDate);

  // Helper for unauthorized
  const unauthorized = (
    message = "Invalid or expired refresh token",
  ): never => {
    throw new HttpException(message, 401);
  };

  try {
    if (body.type === "refresh_token") {
      let decoded: any;
      try {
        decoded = jwt.verify(body.refresh_token, MyGlobal.env.JWT_SECRET_KEY, {
          issuer: "autobe",
        });
      } catch (err) {
        unauthorized();
      }

      if (
        !decoded ||
        decoded.type !== "member" ||
        !decoded.id ||
        !decoded.session_id
      ) {
        throw new HttpException(
          "Forbidden: Invalid token type or payload",
          403,
        );
      }

      const member =
        await MyGlobal.prisma.discussion_board_member.findUniqueOrThrow({
          where: { id: decoded.id },
        });
      if (member.deleted_at !== null)
        throw new HttpException("Account has been deleted", 403);

      const session =
        await MyGlobal.prisma.discussion_board_member_sessions.findFirst({
          where: {
            id: decoded.session_id,
            discussion_board_member_id: decoded.id,
          },
        });
      if (!session) unauthorized();

      // Create a non-null typed alias so the compiler understands it's non-null
      const sessionRecord = session as NonNullable<typeof session>;

      if (
        sessionRecord.expired_at &&
        sessionRecord.expired_at.getTime() <= Date.now()
      ) {
        unauthorized("Session expired or revoked");
      }

      const newAccess = jwt.sign(
        {
          type: decoded.type,
          id: decoded.id,
          session_id: decoded.session_id,
          created_at: toISOStringSafe(new Date()),
        },
        MyGlobal.env.JWT_SECRET_KEY,
        { expiresIn: "1h", issuer: "autobe" },
      );

      const newRefresh = jwt.sign(
        {
          type: decoded.type,
          id: decoded.id,
          session_id: decoded.session_id,
          tokenType: "refresh",
          created_at: toISOStringSafe(new Date()),
        },
        MyGlobal.env.JWT_SECRET_KEY,
        { expiresIn: "7d", issuer: "autobe" },
      );

      await MyGlobal.prisma.discussion_board_member_sessions.update({
        where: { id: decoded.session_id },
        data: { expired_at: refreshExpiryDate },
      });

      return buildResponse(
        member,
        newAccess,
        newRefresh,
        accessExpires,
        refreshExpires,
      );
    }

    if (body.type === "session_id") {
      const sessionId = body.session_id;
      const session =
        await MyGlobal.prisma.discussion_board_member_sessions.findFirst({
          where: { id: sessionId },
        });
      if (!session) unauthorized();

      // Create a non-null typed alias so the compiler understands it's non-null
      const sessionRecord = session as NonNullable<typeof session>;

      const member =
        await MyGlobal.prisma.discussion_board_member.findUniqueOrThrow({
          where: { id: sessionRecord.discussion_board_member_id },
        });
      if (member.deleted_at !== null)
        throw new HttpException("Account has been deleted", 403);

      if (
        sessionRecord.expired_at &&
        sessionRecord.expired_at.getTime() <= Date.now()
      ) {
        unauthorized("Session expired or revoked");
      }

      const newAccess = jwt.sign(
        {
          type: "member",
          id: member.id,
          session_id: sessionRecord.id,
          created_at: toISOStringSafe(new Date()),
        },
        MyGlobal.env.JWT_SECRET_KEY,
        { expiresIn: "1h", issuer: "autobe" },
      );

      const newRefresh = jwt.sign(
        {
          type: "member",
          id: member.id,
          session_id: sessionRecord.id,
          tokenType: "refresh",
          created_at: toISOStringSafe(new Date()),
        },
        MyGlobal.env.JWT_SECRET_KEY,
        { expiresIn: "7d", issuer: "autobe" },
      );

      await MyGlobal.prisma.discussion_board_member_sessions.update({
        where: { id: sessionRecord.id },
        data: { expired_at: refreshExpiryDate },
      });

      return buildResponse(
        member,
        newAccess,
        newRefresh,
        accessExpires,
        refreshExpires,
      );
    }

    throw new HttpException("Bad Request: unknown refresh type", 400);
  } catch (err) {
    if (err instanceof HttpException) throw err;
    throw new HttpException("Internal Server Error", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";
import { IPageIDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardNotification";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IDiscussionBoardSubscription } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSubscription";
import { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function patchDiscussionBoardMemberMembersMemberUsernameNotifications(props: {
  member: MemberPayload;
  memberUsername: string;
  body: IDiscussionBoardNotification.IRequest;
}): Promise<IPageIDiscussionBoardNotification.ISummary> {
  const { member, memberUsername, body } = props;

  // Resolve target member and authorize ownership
  const targetMember = await MyGlobal.prisma.discussion_board_member.findUnique(
    {
      where: { username: memberUsername },
      select: {
        id: true,
        username: true,
        created_at: true,
        display_name: true,
        deleted_at: true,
      },
    },
  );

  if (!targetMember || targetMember.deleted_at)
    throw new HttpException("Not Found", 404);
  if (targetMember.id !== member.id) throw new HttpException("Forbidden", 403);

  const page = Number(body.page ?? 1);
  const limit = Math.min(Number(body.limit ?? 20), 100);
  const skip = (page - 1) * limit;

  const whereCondition: Record<string, unknown> = {
    recipient_member_id: targetMember.id,
    deleted_at: null,
  };

  if (body.status && body.status.length > 0)
    Object.assign(whereCondition, { status: { in: body.status } });
  if (body.type !== undefined && body.type !== null)
    Object.assign(whereCondition, { type: body.type });
  if (body.subscriptionId !== undefined && body.subscriptionId !== null)
    Object.assign(whereCondition, {
      discussion_board_subscription_id: body.subscriptionId,
    });
  if (body.articleId !== undefined && body.articleId !== null)
    Object.assign(whereCondition, {
      discussion_board_article_id: body.articleId,
    });
  if (body.hasPayload === true)
    Object.assign(whereCondition, { payload: { not: null } });

  if (body.scheduledBefore !== undefined && body.scheduledBefore !== null) {
    Object.assign(whereCondition, {
      scheduled_at: {
        ...(whereCondition.scheduled_at ?? {}),
        lte: toISOStringSafe(body.scheduledBefore),
      },
    });
  }
  if (body.scheduledAfter !== undefined && body.scheduledAfter !== null) {
    Object.assign(whereCondition, {
      scheduled_at: {
        ...(whereCondition.scheduled_at ?? {}),
        gte: toISOStringSafe(body.scheduledAfter),
      },
    });
  }

  // Avoid runtime validation like trim(); check for empty string explicitly
  if (body.q !== undefined && body.q !== null && body.q !== "") {
    Object.assign(whereCondition, {
      OR: [
        { payload: { contains: body.q } },
        { article: { title: { contains: body.q } } },
      ],
    });
  }

  if (body.bulkAction !== undefined && body.bulkAction !== null) {
    const now = toISOStringSafe(new Date());
    const action = (
      body.bulkAction as { action?: string; apply_to_all?: boolean }
    ).action;
    const applyAll =
      (body.bulkAction as { action?: string; apply_to_all?: boolean })
        .apply_to_all === true;

    if (applyAll) {
      await MyGlobal.prisma.discussion_board_notifications.updateMany({
        where: whereCondition,
        data: {
          updated_at: now,
          ...(action === "mark_as_read" ? { status: "sent" } : {}),
        },
      });
    } else if (
      Array.isArray(body.notificationIds) &&
      body.notificationIds.length > 0
    ) {
      await MyGlobal.prisma.discussion_board_notifications.updateMany({
        where: {
          id: { in: body.notificationIds },
          recipient_member_id: targetMember.id,
        },
        data: {
          updated_at: now,
          ...(action === "mark_as_read" ? { status: "sent" } : {}),
        },
      });
    }

    const auditNow = toISOStringSafe(new Date());
    await MyGlobal.prisma.discussion_board_moderation_audit.create({
      data: {
        id: v4(),
        event_type: "notification.bulk_action",
        event_payload: JSON.stringify({
          performed_by: member.id,
          action: action ?? null,
          apply_to_all: applyAll,
        }),
        occurred_at: auditNow,
      },
    });
  }

  const [total, rows] = await Promise.all([
    MyGlobal.prisma.discussion_board_notifications.count({
      where: whereCondition,
    }),
    MyGlobal.prisma.discussion_board_notifications.findMany({
      where: whereCondition,
      orderBy:
        body.sort === "scheduledAt"
          ? { scheduled_at: "asc" }
          : body.sort === "-scheduledAt"
            ? { scheduled_at: "desc" }
            : body.sort === "createdAt"
              ? { created_at: "asc" }
              : body.sort === "-createdAt"
                ? { created_at: "desc" }
                : { scheduled_at: "desc" },
      skip,
      take: limit,
      select: {
        id: true,
        type: true,
        status: true,
        priority: true,
        scheduled_at: true,
        sent_at: true,
        fail_reason: true,
        created_at: true,
        updated_at: true,
        delivery_attempts: true,
        last_attempted_at: true,
        next_retry_at: true,
        recipient: {
          select: {
            id: true,
            username: true,
            display_name: true,
            created_at: true,
          },
        },
        subscription: {
          select: {
            id: true,
            target_type: true,
            target_id: true,
            delivery_mode: true,
            active: true,
            last_notified_at: true,
            created_at: true,
            updated_at: true,
            deleted_at: true,
            member: {
              select: {
                id: true,
                username: true,
                display_name: true,
                created_at: true,
              },
            },
          },
        },
        article: {
          select: {
            id: true,
            title: true,
            is_pinned: true,
            published_at: true,
            created_at: true,
            updated_at: true,
            category: {
              select: {
                id: true,
                name: true,
                slug: true,
                description: true,
                is_active: true,
                sort_order: true,
                created_at: true,
                updated_at: true,
                deleted_at: true,
              },
            },
            author: {
              select: {
                id: true,
                username: true,
                display_name: true,
                created_at: true,
              },
            },
          },
        },
      },
    }),
  ]);

  const data = rows.map((r) => {
    const recipient = r.recipient
      ? {
          id: r.recipient.id,
          username: r.recipient.username,
          displayName: r.recipient.display_name ?? null,
          createdAt: toISOStringSafe(r.recipient.created_at),
        }
      : undefined;

    const subscription = r.subscription
      ? {
          id: r.subscription.id,
          member: r.subscription.member
            ? {
                id: r.subscription.member.id,
                username: r.subscription.member.username,
                displayName: r.subscription.member.display_name ?? null,
                createdAt: toISOStringSafe(r.subscription.member.created_at),
              }
            : undefined,
          targetType: r.subscription.target_type as "article" | "author",
          targetId: r.subscription.target_id,
          deliveryMode: r.subscription.delivery_mode as
            | "immediate"
            | "daily_digest",
          active: r.subscription.active,
          lastNotifiedAt: r.subscription.last_notified_at
            ? toISOStringSafe(r.subscription.last_notified_at)
            : null,
          createdAt: toISOStringSafe(r.subscription.created_at),
          updatedAt: r.subscription.updated_at
            ? toISOStringSafe(r.subscription.updated_at)
            : null,
          deletedAt: r.subscription.deleted_at
            ? toISOStringSafe(r.subscription.deleted_at)
            : null,
        }
      : undefined;

    const article = r.article
      ? {
          id: r.article.id,
          title: r.article.title,
          excerpt: undefined,
          author: r.article.author
            ? {
                id: r.article.author.id,
                username: r.article.author.username,
                displayName: r.article.author.display_name ?? null,
                createdAt: toISOStringSafe(r.article.author.created_at),
              }
            : undefined,
          isPinned: r.article.is_pinned ?? undefined,
          publishedAt: r.article.published_at
            ? toISOStringSafe(r.article.published_at)
            : null,
          createdAt: toISOStringSafe(r.article.created_at),
          updatedAt: r.article.updated_at
            ? toISOStringSafe(r.article.updated_at)
            : null,
          category: r.article.category
            ? {
                id: r.article.category.id,
                name: r.article.category.name,
                slug: r.article.category.slug,
                description: r.article.category.description ?? null,
                isActive: r.article.category.is_active,
                sortOrder: r.article.category.sort_order ?? null,
                createdAt: toISOStringSafe(r.article.category.created_at),
                updatedAt: r.article.category.updated_at
                  ? toISOStringSafe(r.article.category.updated_at)
                  : null,
                deletedAt: r.article.category.deleted_at
                  ? toISOStringSafe(r.article.category.deleted_at)
                  : null,
              }
            : undefined,
        }
      : undefined;

    return {
      id: r.id,
      type: r.type,
      status: r.status as "pending" | "sent" | "failed",
      priority: r.priority ?? undefined,
      scheduledAt: r.scheduled_at ? toISOStringSafe(r.scheduled_at) : undefined,
      sentAt: r.sent_at ? toISOStringSafe(r.sent_at) : null,
      failReason: r.fail_reason ?? null,
      createdAt: toISOStringSafe(r.created_at),
      updatedAt: r.updated_at ? toISOStringSafe(r.updated_at) : null,
      deliveryAttempts: r.delivery_attempts ?? undefined,
      lastAttemptedAt: r.last_attempted_at
        ? toISOStringSafe(r.last_attempted_at)
        : null,
      nextRetryAt: r.next_retry_at ? toISOStringSafe(r.next_retry_at) : null,
      recipient,
      subscription,
      article,
    };
  }) as unknown as IDiscussionBoardNotification.ISummary[];

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  } as unknown as IPageIDiscussionBoardNotification.ISummary;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { GuestPayload } from "../decorators/payload/GuestPayload";

export async function postAuthGuestJoin(props: {
  guest: GuestPayload;
  body: IDiscussionBoardGuest.ICreate;
}): Promise<IDiscussionBoardGuest.IAuthorized> {
  const { guest, body } = props;

  if (guest && guest.type !== "guest") {
    throw new HttpException("Unauthorized: invalid actor", 403);
  }

  const guestId = v4() as string & tags.Format<"uuid">;
  const sessionId = v4() as string & tags.Format<"uuid">;
  const now = toISOStringSafe(new Date());

  const accessExpires = new Date(Date.now() + 15 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 4 * 60 * 60 * 1000);

  let created;
  try {
    created = await MyGlobal.prisma.discussion_board_guest.create({
      data: {
        id: guestId,
        display_name: body.displayName ?? null,
        ip: body.ip ?? null,
        created_at: now,
        updated_at: now,
      },
    });
  } catch (e) {
    throw new HttpException(
      "Internal Server Error: failed to create guest",
      500,
    );
  }

  let access: string;
  let refresh: string;
  try {
    access = jwt.sign(
      {
        type: "guest",
        id: guestId,
        session_id: sessionId,
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "15m", issuer: "autobe" },
    );

    refresh = jwt.sign(
      {
        type: "guest",
        id: guestId,
        session_id: sessionId,
        tokenType: "refresh",
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "4h", issuer: "autobe" },
    );
  } catch (e) {
    throw new HttpException(
      "Internal Server Error: failed to generate tokens",
      500,
    );
  }

  const token = {
    access,
    refresh,
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  } satisfies IAuthorizationToken;

  return {
    id: created.id as string & tags.Format<"uuid">,
    displayName: created.display_name ?? undefined,
    ip: null,
    createdAt: now,
    updatedAt: now,
    deletedAt: created.deleted_at ? toISOStringSafe(created.deleted_at) : null,
    token,
    guest: {
      id: created.id as string & tags.Format<"uuid">,
      display_name: created.display_name ?? null,
      created_at: now,
      updated_at: now,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { GuestPayload } from "../decorators/payload/GuestPayload";

export async function postAuthGuestRefresh(props: {
  guest: GuestPayload;
  body: IDiscussionBoardGuest.IRefresh;
}): Promise<IDiscussionBoardGuest.IAuthorized> {
  const { body } = props;

  // Verify and decode the refresh token
  let decodedPayload: unknown;
  try {
    decodedPayload = jwt.verify(
      body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    );
  } catch (err) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  if (typeof decodedPayload !== "object" || decodedPayload === null) {
    throw new HttpException("Invalid token payload", 401);
  }

  const tokenData = decodedPayload as {
    id: string;
    session_id: string;
    type: string;
  };

  if (tokenData.type !== "guest") {
    throw new HttpException("Invalid token type", 403);
  }

  // Validate guest existence and lifecycle state
  const guestRecord = await MyGlobal.prisma.discussion_board_guest.findFirst({
    where: { id: tokenData.id },
  });

  if (!guestRecord) {
    throw new HttpException("Guest not found", 404);
  }

  if (guestRecord.deleted_at !== null) {
    throw new HttpException("Account has been deleted", 403);
  }

  // Generate new tokens reusing the same session_id from token
  const createdAtIso = toISOStringSafe(new Date());
  const accessExpiryIso = toISOStringSafe(
    new Date(Date.now() + 60 * 60 * 1000),
  );
  const refreshExpiryIso = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );

  const accessToken = jwt.sign(
    {
      type: tokenData.type,
      id: tokenData.id,
      session_id: tokenData.session_id,
      created_at: createdAtIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "1h", issuer: "autobe" },
  );

  const refreshToken = jwt.sign(
    {
      type: tokenData.type,
      id: tokenData.id,
      session_id: tokenData.session_id,
      tokenType: "refresh",
      created_at: createdAtIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );

  // Build response per IDiscussionBoardGuest.IAuthorized
  return {
    id: guestRecord.id,
    displayName: guestRecord.display_name ?? undefined,
    ip: null,
    createdAt: toISOStringSafe(guestRecord.created_at),
    updatedAt: toISOStringSafe(guestRecord.updated_at),
    deletedAt: guestRecord.deleted_at
      ? toISOStringSafe(guestRecord.deleted_at)
      : null,
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: accessExpiryIso,
      refreshable_until: refreshExpiryIso,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthMemberJoin(props: {
  body: IDiscussionBoardMember.IJoin;
}): Promise<IDiscussionBoardMember.IAuthorized> {
  const { body } = props;

  // Check uniqueness (username or email) before attempting create to provide clear conflict error
  const existing = await MyGlobal.prisma.discussion_board_member.findFirst({
    where: {
      OR: [{ username: body.username }, { email: body.email }],
    },
  });

  if (existing) {
    if (existing.username === body.username) {
      throw new HttpException("Username already registered", 409);
    }
    if (existing.email === body.email) {
      throw new HttpException("Email already registered", 409);
    }
    throw new HttpException(
      "Conflict: username or email already registered",
      409,
    );
  }

  // Hash password (MANDATORY)
  const password_hash = await PasswordUtil.hash(body.password);

  // Prepare deterministic values
  const memberId = v4() as string & tags.Format<"uuid">;
  const sessionId = v4() as string & tags.Format<"uuid">;
  const verificationId = v4() as string & tags.Format<"uuid">;
  const verificationToken = v4();

  const now = toISOStringSafe(new Date());
  const accessExpiresDate = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpiresDate = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

  const accessExpiresIso = toISOStringSafe(accessExpiresDate);
  const refreshExpiresIso = toISOStringSafe(refreshExpiresDate);
  const verificationExpiresIso = toISOStringSafe(
    new Date(Date.now() + 48 * 60 * 60 * 1000),
  );

  try {
    // Create member record
    const created = await MyGlobal.prisma.discussion_board_member.create({
      data: {
        id: memberId,
        username: body.username,
        email: body.email,
        password_hash,
        display_name: body.display_name ?? null,
        role: "USER",
        mfa_enabled: false,
        created_at: now,
        updated_at: now,
      },
    });

    // Create email verification artifact
    await MyGlobal.prisma.discussion_board_email_verifications.create({
      data: {
        id: verificationId,
        discussion_board_member_id: created.id,
        token: verificationToken,
        created_at: now,
        expires_at: verificationExpiresIso,
      },
    });

    // Create initial session
    const session =
      await MyGlobal.prisma.discussion_board_member_sessions.create({
        data: {
          id: sessionId,
          discussion_board_member_id: created.id,
          ip: body.ip ?? "",
          href: body.href,
          referrer: body.referrer,
          created_at: now,
          expired_at: accessExpiresIso,
        },
      });

    // Build JWT payloads
    const jwtCreatedAt = now;
    const accessToken = jwt.sign(
      {
        type: "member",
        id: created.id,
        session_id: session.id,
        created_at: jwtCreatedAt,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "1h", issuer: "autobe" },
    );

    const refreshToken = jwt.sign(
      {
        type: "member",
        id: created.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: jwtCreatedAt,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    );

    // Return authorized response
    return {
      id: created.id,
      username: created.username,
      email: created.email,
      display_name: created.display_name ?? null,
      role: created.role ?? "USER",
      mfa_enabled: created.mfa_enabled ?? false,
      created_at: now,
      updated_at: now,
      deleted_at: undefined,
      token: {
        access: accessToken,
        refresh: refreshToken,
        expired_at: accessExpiresIso,
        refreshable_until: refreshExpiresIso,
      },
      member: {
        id: created.id,
        username: created.username,
        display_name: created.display_name ?? null,
        created_at: now,
      },
    };
  } catch (err) {
    // Prisma unique constraint error handling
    if ((err as any)?.code === "P2002") {
      throw new HttpException("Conflict: duplicate field", 409);
    }
    throw new HttpException("Internal Server Error", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthMemberLogin(props: {
  body: IDiscussionBoardMember.ILogin;
}): Promise<IDiscussionBoardMember.IAuthorized> {
  const { body } = props;

  // Find member by username or email (no user enumeration)
  const member = await MyGlobal.prisma.discussion_board_member.findFirst({
    where: {
      OR: [{ username: body.usernameOrEmail }, { email: body.usernameOrEmail }],
    },
  });

  if (!member) throw new HttpException("Invalid credentials", 401);
  if (member.deleted_at)
    throw new HttpException("Account has been removed", 403);

  // Verify password using PasswordUtil
  const isValid = await PasswordUtil.verify(
    body.password,
    member.password_hash,
  );
  if (!isValid) {
    // Best-effort audit log for failed login
    try {
      await MyGlobal.prisma.discussion_board_audit_logs.create({
        data: {
          id: v4() as string & tags.Format<"uuid">,
          event_type: "auth.login.failed",
          event_timestamp: toISOStringSafe(new Date()),
          actor_type: "member",
          actor_id: member.id,
          ip: body.ip ?? "",
          metadata: null,
          created_at: toISOStringSafe(new Date()),
          updated_at: toISOStringSafe(new Date()),
          deleted_at: null,
        },
      });
    } catch {
      // swallow errors from audit logging
    }

    throw new HttpException("Invalid credentials", 401);
  }

  if (member.mfa_enabled) throw new HttpException("MFA required", 403);

  // Prepare timestamps (ISO strings)
  const now = toISOStringSafe(new Date());
  const accessExpires = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000));
  const refreshExpires = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );

  // Create session record
  const session = await MyGlobal.prisma.discussion_board_member_sessions.create(
    {
      data: {
        id: v4() as string & tags.Format<"uuid">,
        discussion_board_member_id: member.id,
        ip: body.ip ?? "",
        href: body.href ?? "",
        referrer: body.referrer ?? "",
        created_at: now,
        expired_at: accessExpires,
      },
    },
  );

  // Best-effort audit log for successful login
  try {
    await MyGlobal.prisma.discussion_board_audit_logs.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        event_type: "auth.login",
        event_timestamp: now,
        actor_type: "member",
        actor_id: member.id,
        ip: body.ip ?? "",
        metadata: null,
        created_at: now,
        updated_at: now,
        deleted_at: null,
      },
    });
  } catch {
    // ignore audit logging errors
  }

  // Generate JWT tokens
  const access = jwt.sign(
    {
      type: "member",
      id: member.id,
      session_id: session.id,
      created_at: now,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "1h", issuer: "autobe" },
  );

  const refresh = jwt.sign(
    {
      type: "member",
      id: member.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: now,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );

  return {
    id: member.id as string & tags.Format<"uuid">,
    username: member.username,
    email: member.email as string & tags.Format<"email">,
    display_name: member.display_name ?? undefined,
    role: member.role ?? undefined,
    mfa_enabled: member.mfa_enabled ?? undefined,
    created_at: toISOStringSafe(member.created_at),
    updated_at: member.updated_at
      ? toISOStringSafe(member.updated_at)
      : undefined,
    deleted_at: member.deleted_at ? toISOStringSafe(member.deleted_at) : null,
    token: {
      access,
      refresh,
      expired_at: accessExpires,
      refreshable_until: refreshExpires,
    },
    member: {
      id: member.id as string & tags.Format<"uuid">,
      username: member.username,
      display_name: member.display_name ?? undefined,
      created_at: toISOStringSafe(member.created_at),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

export async function postAuthMemberEmailVerify(props: {
  body: IDiscussionBoardMember.IVerifyEmail;
}): Promise<IDiscussionBoardMember> {
  const { body } = props;
  const { token } = body;

  const verification =
    await MyGlobal.prisma.discussion_board_email_verifications.findUnique({
      where: { token },
    });

  if (!verification)
    throw new HttpException("Verification token not found", 404);

  if (verification.consumed_at !== null) {
    throw new HttpException("Verification token already consumed", 409);
  }

  const now = toISOStringSafe(new Date());

  if (
    verification.expires_at &&
    toISOStringSafe(verification.expires_at) < now
  ) {
    throw new HttpException("Verification token expired", 410);
  }

  const consumed =
    await MyGlobal.prisma.discussion_board_email_verifications.updateMany({
      where: { id: verification.id, consumed_at: null },
      data: { consumed_at: now },
    });

  if (consumed.count === 0) {
    throw new HttpException("Verification token already consumed", 409);
  }

  const updatedMember = await MyGlobal.prisma.discussion_board_member.update({
    where: { id: verification.discussion_board_member_id },
    data: { updated_at: now },
  });

  return {
    id: updatedMember.id as string & tags.Format<"uuid">,
    username: updatedMember.username,
    display_name: updatedMember.display_name ?? undefined,
    role: updatedMember.role,
    mfa_enabled: updatedMember.mfa_enabled,
    created_at: toISOStringSafe(updatedMember.created_at),
    updated_at: toISOStringSafe(updatedMember.updated_at),
    deleted_at: updatedMember.deleted_at
      ? toISOStringSafe(updatedMember.deleted_at)
      : null,
  } as unknown as IDiscussionBoardMember;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

export async function postAuthMemberPasswordRequest(props: {
  body: IDiscussionBoardMember.IRequestPasswordReset;
}): Promise<void> {
  const { body } = props;

  // Extract commonly used fields (controller validated)
  const email = (body as { email?: string & tags.Format<"email"> }).email;
  const username = (body as { username?: string }).username;
  const request_ip = (body as { ip?: string | null }).ip ?? null;

  // Find member by email first, then username
  const member = email
    ? await MyGlobal.prisma.discussion_board_member.findUnique({
        where: { email },
      })
    : username
      ? await MyGlobal.prisma.discussion_board_member.findUnique({
          where: { username },
        })
      : null;

  // Non-enumeration: If no member, return success without persisting reset
  if (!member) return;

  // Rate limit: allow one request per minute (policy)
  const last = await MyGlobal.prisma.discussion_board_password_resets.findFirst(
    {
      where: { discussion_board_member_id: member.id },
      orderBy: { created_at: "desc" },
    },
  );

  if (last) {
    const elapsed = Date.now() - last.created_at.getTime();
    const windowMs = 60 * 1000; // 1 minute
    if (elapsed < windowMs) {
      throw new HttpException("Too Many Requests", 429);
    }
  }

  const now = toISOStringSafe(new Date());
  const expires = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000)); // 1 hour

  await MyGlobal.prisma.discussion_board_password_resets.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      discussion_board_member_id: member.id as string & tags.Format<"uuid">,
      token: v4(),
      request_ip: request_ip,
      created_at: now,
      expires_at: expires,
      consumed_at: null,
    },
  });

  // Note: Email dispatch is handled by other systems (background worker) based on the persisted reset record.
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

export async function postAuthMemberPasswordReset(props: {
  body: IDiscussionBoardMember.IResetPassword;
}): Promise<IDiscussionBoardMember> {
  const { body } = props;

  try {
    const reset =
      await MyGlobal.prisma.discussion_board_password_resets.findUnique({
        where: { token: body.token },
      });

    if (!reset) throw new HttpException("Invalid token", 404);
    if (reset.consumed_at)
      throw new HttpException("Token already consumed", 400);

    const now = toISOStringSafe(new Date());

    if (reset.expires_at && toISOStringSafe(reset.expires_at) <= now) {
      throw new HttpException("Token expired", 400);
    }

    // Business-rule: enforce strong password
    const password = body.password;
    const lengthOk = password.length >= 12;
    const classes = [
      /[A-Z]/.test(password),
      /[a-z]/.test(password),
      /[0-9]/.test(password),
      /[^A-Za-z0-9]/.test(password),
    ];
    const classesOk = classes.filter(Boolean).length >= 3;
    if (!lengthOk || !classesOk) throw new HttpException("Weak password", 400);

    const hashed = await PasswordUtil.hash(password);

    const memberId = reset.discussion_board_member_id;
    if (!memberId)
      throw new HttpException("Invalid token: no member linked", 404);

    await MyGlobal.prisma.$transaction([
      MyGlobal.prisma.discussion_board_password_resets.update({
        where: { id: reset.id },
        data: { consumed_at: now },
      }),

      MyGlobal.prisma.discussion_board_member.update({
        where: { id: memberId },
        data: { password_hash: hashed, updated_at: now },
      }),

      MyGlobal.prisma.discussion_board_member_sessions.updateMany({
        where: { discussion_board_member_id: memberId, expired_at: null },
        data: { expired_at: now },
      }),

      MyGlobal.prisma.discussion_board_audit_logs.create({
        data: {
          id: v4() as string & tags.Format<"uuid">,
          event_type: "auth.password_reset",
          event_timestamp: now,
          resource_type: "member",
          resource_id: memberId,
          actor_type: "member",
          actor_id: memberId,
          ip: reset.request_ip ?? null,
          metadata: JSON.stringify({ note: "password reset via token" }),
          created_at: now,
          updated_at: now,
        },
      }),
    ]);

    const member = await MyGlobal.prisma.discussion_board_member.findUnique({
      where: { id: memberId },
    });
    if (!member) throw new HttpException("Member not found", 404);

    return {
      id: member.id as string & tags.Format<"uuid">,
      username: member.username,
      display_name: member.display_name ?? undefined,
      role: member.role,
      mfa_enabled: member.mfa_enabled,
      created_at: toISOStringSafe(member.created_at),
      updated_at: toISOStringSafe(member.updated_at),
      deleted_at: member.deleted_at
        ? toISOStringSafe(member.deleted_at)
        : undefined,
    };
  } catch (e) {
    if (e instanceof HttpException) throw e;
    throw new HttpException("Internal Server Error", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function putAuthMemberPasswordChange(props: {
  member: MemberPayload;
  body: IDiscussionBoardMember.IChangePassword;
}): Promise<void> {
  const { member, body } = props;

  // Retrieve member; throws if not found
  const existing =
    await MyGlobal.prisma.discussion_board_member.findUniqueOrThrow({
      where: { id: member.id },
    });

  // If member is soft-deleted, treat as not found
  if (existing.deleted_at) {
    throw new HttpException("Not Found", 404);
  }

  // Verify current password against stored hash
  const valid = await PasswordUtil.verify(
    body.currentPassword,
    existing.password_hash,
  );
  if (!valid) {
    throw new HttpException("Invalid current password", 400);
  }

  // Hash new password
  const hashed = await PasswordUtil.hash(body.newPassword);

  // Single timestamp for consistency
  const now = toISOStringSafe(new Date());

  // Update password hash and updated_at
  await MyGlobal.prisma.discussion_board_member.update({
    where: { id: member.id },
    data: {
      password_hash: hashed,
      updated_at: now,
    },
  });

  // Optionally revoke active sessions by setting expired_at
  if (body.revokeSessions) {
    await MyGlobal.prisma.discussion_board_member_sessions.updateMany({
      where: {
        discussion_board_member_id: member.id,
        OR: [{ expired_at: null }, { expired_at: { gt: new Date() } }],
      },
      data: {
        expired_at: now,
      },
    });
  }

  // Append audit log entry for password change
  await MyGlobal.prisma.discussion_board_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      event_type: "member.password_change",
      event_timestamp: now,
      actor_type: "member",
      actor_id: member.id,
      metadata: JSON.stringify({
        revokeSessions: body.revokeSessions ?? false,
      }),
      created_at: now,
      updated_at: now,
    },
  });
}

