        key: settingKey,
        before: {
          value: existing.value,
          description: existing.description,
          is_active: existing.is_active,
        },
        after: {
          value: updated.value,
          description: updated.description,
          is_active: updated.is_active,
        },
        performed_by: moderator.id,
        occurred_at: now,
      }),
      occurred_at: now,
