      throw new HttpException("Conflict: Active appeal blocks deletion", 409);
  }

  const now = toISOStringSafe(new Date());

  await MyGlobal.prisma.discussion_board_articles.update({
    where: { id: articleId },
    data: { deleted_at: now },
