      actor_type: "member",
      actor_id: member.id,
      ip: null,
      user_agent: null,
      metadata: JSON.stringify({
        reason: "soft_delete",
        performed_by: member.id,
      }),
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  await MyGlobal.prisma.discussion_board_moderation_audit.create({
    data: {
      id: v4(),
      moderation_action_id: null,
