import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function postDiscussionBoardMemberArticlesArticleIdComments(props: {
  member: MemberPayload;
  articleId: string & tags.Format<"uuid">;
  body: IDiscussionBoardComment.ICreate;
}): Promise<IDiscussionBoardComment> {
  const { member, articleId, body } = props;

  // Ensure acting member exists and is in good standing
  const dbMember =
    await MyGlobal.prisma.discussion_board_member.findUniqueOrThrow({
      where: { id: member.id },
    });

  if (dbMember.deleted_at !== null) {
    throw new HttpException("Unauthorized: member account removed", 401);
  }
  if (dbMember.role === "suspended") {
    throw new HttpException("Forbidden: member suspended", 403);
  }

  // Validate target article
  const article =
    await MyGlobal.prisma.discussion_board_articles.findUniqueOrThrow({
      where: { id: articleId },
    });

  if (article.deleted_at !== null) throw new HttpException("Not Found", 404);
  if (article.state !== "published") throw new HttpException("Not Found", 404);

  // Parent comment validation & depth check
  const MAX_REPLY_DEPTH = 5;
  if (body.parentCommentId !== undefined && body.parentCommentId !== null) {
    const parent = await MyGlobal.prisma.discussion_board_comments.findUnique({
      where: { id: body.parentCommentId },
    });

    if (!parent) throw new HttpException("Invalid parentCommentId", 400);
    if (parent.discussion_board_article_id !== articleId) {
      throw new HttpException(
        "Parent comment belongs to a different article",
        400,
      );
    }

    // Walk ancestry to enforce depth
    let depth = 1;
    let cursor = parent;
    while (cursor.discussion_board_parent_comment_id) {
      depth++;
      if (depth >= MAX_REPLY_DEPTH) {
        throw new HttpException("Reply depth exceeds allowed maximum", 400);
      }
      const next = await MyGlobal.prisma.discussion_board_comments.findUnique({
        where: { id: cursor.discussion_board_parent_comment_id },
      });
      if (!next) break;
      cursor = next;
    }
  }

  // Rate limiting (simple heuristic)
  const oneMinuteAgo = toISOStringSafe(new Date(Date.now() - 60 * 1000));
  const recentCount = await MyGlobal.prisma.discussion_board_comments.count({
    where: {
      discussion_board_author_id: member.id,
      created_at: { gte: oneMinuteAgo },
    },
  });
  const RATE_LIMIT_PER_MINUTE = 10;
  if (recentCount >= RATE_LIMIT_PER_MINUTE) {
    throw new HttpException("Too Many Requests", 429);
  }

  // Anti-abuse heuristic (daily threshold)
  const oneDayAgo = toISOStringSafe(new Date(Date.now() - 24 * 60 * 60 * 1000));
  const dailyCount = await MyGlobal.prisma.discussion_board_comments.count({
    where: {
      discussion_board_author_id: member.id,
      created_at: { gte: oneDayAgo },
    },
  });
  const isHidden = dailyCount > 200;

  // Timestamps
  const now = toISOStringSafe(new Date());

  // Persist comment
  const created = await MyGlobal.prisma.discussion_board_comments.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      discussion_board_article_id: articleId,
      discussion_board_author_id: member.id,
      discussion_board_parent_comment_id: body.parentCommentId ?? null,
      content: body.content,
      is_hidden: isHidden,
      created_at: now,
      updated_at: now,
    },
  });

  // Build author summary
  const authorSummary = dbMember
    ? {
        id: dbMember.id as string & tags.Format<"uuid">,
        username: dbMember.username,
        display_name: dbMember.display_name ?? null,
        created_at: toISOStringSafe(dbMember.created_at),
      }
    : null;

  return {
    id: created.id as string & tags.Format<"uuid">,
    articleId: created.discussion_board_article_id as string &
      tags.Format<"uuid">,
    parentCommentId:
      created.discussion_board_parent_comment_id === null
        ? null
        : (created.discussion_board_parent_comment_id as string &
            tags.Format<"uuid">),
    author: authorSummary,
    content: created.content,
    isHidden: created.is_hidden,
    createdAt: toISOStringSafe(created.created_at),
    updatedAt: toISOStringSafe(created.updated_at),
    deletedAt: created.deleted_at ? toISOStringSafe(created.deleted_at) : null,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentAttachment";
import { IPageIDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentAttachment";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function patchDiscussionBoardMemberArticlesArticleIdCommentsCommentIdAttachments(props: {
  member: MemberPayload;
  articleId: string & tags.Format<"uuid">;
  commentId: string & tags.Format<"uuid">;
  body: IDiscussionBoardCommentAttachment.IRequest;
}): Promise<IPageIDiscussionBoardCommentAttachment.ISummary> {
  const { member, articleId, commentId, body } = props;

  // Verify article exists
  try {
    await MyGlobal.prisma.discussion_board_articles.findUniqueOrThrow({
      where: { id: articleId },
    });
  } catch {
    throw new HttpException("Not Found: article does not exist", 404);
  }

  // Verify comment exists and belongs to article
  let comment;
  try {
    comment = await MyGlobal.prisma.discussion_board_comments.findFirstOrThrow({
      where: { id: commentId, discussion_board_article_id: articleId },
    });
  } catch {
    throw new HttpException(
      "Not Found: comment does not belong to the specified article",
      404,
    );
  }

  // Authorization: the authenticated member must be the comment author
  if (comment.discussion_board_author_id !== member.id) {
    throw new HttpException(
      "Forbidden: you are not the author of this comment",
      403,
    );
  }

  // Enforce per-comment quota (MVP: max 1 attachment)
  const existingCount =
    await MyGlobal.prisma.discussion_board_comment_attachments.count({
      where: { discussion_board_comment_id: commentId },
    });
  const incomingCount = Array.isArray(body.attachments)
    ? body.attachments.length
    : 0;
  const MAX_PER_COMMENT = 1;
  if (existingCount + incomingCount > MAX_PER_COMMENT) {
    throw new HttpException(
      "Bad Request: attachment quota exceeded for this comment",
      400,
    );
  }

  // Validation
  const MAX_SIZE = 26214400; // 25 MB
  const ALLOWED_MIME = new Set([
    "image/png",
    "image/jpeg",
    "image/webp",
    "image/gif",
    "application/pdf",
    "text/plain",
  ]);

  if (!Array.isArray(body.attachments) || body.attachments.length === 0) {
    throw new HttpException(
      "Bad Request: attachments array is required and must contain at least one item",
      400,
    );
  }

  // Prepare timestamp once
  const now = toISOStringSafe(new Date());

  // Create attachments sequentially to preserve ordering and quota logic
  for (const item of body.attachments) {
    if (
      !item ||
      typeof item.storage_key !== "string" ||
      item.storage_key.length === 0
    ) {
      throw new HttpException(
        "Bad Request: storage_key is required for each attachment",
        400,
      );
    }
    if (
      typeof item.original_filename !== "string" ||
      item.original_filename.length === 0
    ) {
      throw new HttpException(
        "Bad Request: original_filename is required for each attachment",
        400,
      );
    }
    if (
      typeof item.mime_type !== "string" ||
      !ALLOWED_MIME.has(item.mime_type)
    ) {
      throw new HttpException("Bad Request: unsupported mime_type", 400);
    }
    if (
      typeof item.size !== "number" ||
      item.size < 0 ||
      item.size > MAX_SIZE
    ) {
      throw new HttpException(
        "Bad Request: invalid or too large size for attachment",
        400,
      );
    }

    // Storage existence & scanning integration placeholder
    // NOTE: A storage existence check and malware/abuse scanning integration
    // should run here. If storage cannot be verified, the correct behavior is
    // to return 422. This environment lacks a storage service API, so we
    // optimistically proceed while marking quarantined=false. Integrate
    // MyGlobal.storage or a scanning service for production.

    await MyGlobal.prisma.discussion_board_comment_attachments.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        discussion_board_comment_id: commentId,
        discussion_board_uploaded_by_id: member.id,
        original_filename: item.original_filename,
        storage_key: item.storage_key,
        mime_type: item.mime_type,
        size: item.size,
        is_image: item.is_image ?? item.mime_type.startsWith("image/"),
        quarantined: false,
        created_at: now,
      },
    });
  }

  // Fetch attachments to return a summary page
  const rows =
    await MyGlobal.prisma.discussion_board_comment_attachments.findMany({
      where: { discussion_board_comment_id: commentId },
      include: {
        uploadedBy: {
          select: {
            id: true,
            username: true,
            display_name: true,
            created_at: true,
          },
        },
      },
      orderBy: { created_at: "desc" },
    });

  const mapped = rows.map((r) => ({
    id: r.id as string & tags.Format<"uuid">,
    commentId: r.discussion_board_comment_id as string & tags.Format<"uuid">,
    originalFilename: r.original_filename,
    mimeType: r.mime_type,
    size: Number(r.size),
    isImage: r.is_image,
    quarantined: r.quarantined,
    createdAt: r.created_at ? toISOStringSafe(r.created_at) : now,
    downloadUrl: null,
    cdnUrl: null,
    uploader: r.uploadedBy
      ? {
          id: r.uploadedBy.id as string & tags.Format<"uuid">,
          username: r.uploadedBy.username,
          display_name: r.uploadedBy.display_name ?? null,
          created_at: toISOStringSafe(r.uploadedBy.created_at),
        }
      : null,
  }));

  const records = mapped.length;
  const limit = records === 0 ? 10 : records;

  return {
    pagination: {
      current: Number(1),
      limit: Number(limit),
      records: Number(records),
      pages: Number(Math.ceil(records / limit)),
    },
    data: mapped,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentAttachment";
import { IPageIDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentAttachment";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function postDiscussionBoardMemberArticlesArticleIdCommentsCommentIdAttachments(props: {
  member: MemberPayload;
  articleId: string & tags.Format<"uuid">;
  commentId: string & tags.Format<"uuid">;
  body: IDiscussionBoardCommentAttachment.ICreate;
}): Promise<IPageIDiscussionBoardCommentAttachment.ISummary> {
  const { member, articleId, commentId, body } = props;

  // Validate comment existence and association with article
  const comment = await MyGlobal.prisma.discussion_board_comments.findFirst({
    where: {
      id: commentId,
      discussion_board_article_id: articleId,
    },
  });

  if (!comment) throw new HttpException("Not Found", 404);

  // Authorization: only the comment author may add attachments
  if (comment.discussion_board_author_id !== member.id) {
    throw new HttpException(
      "Unauthorized: Only comment author can add attachments",
      403,
    );
  }

  // Prepare timestamp once for consistency
  const now = toISOStringSafe(new Date());

  // Atomic operation: enforce quota and create attachments
  await MyGlobal.prisma.$transaction(async (tx) => {
    const existing = await tx.discussion_board_comment_attachments.count({
      where: { discussion_board_comment_id: commentId },
    });

    if (existing + body.attachments.length > 1) {
      throw new HttpException(
        "Bad Request: attachment quota exceeded for this comment",
        400,
      );
    }

    // Create each attachment record
    const creations = body.attachments.map((item) =>
      tx.discussion_board_comment_attachments.create({
        data: {
          id: v4() as string & tags.Format<"uuid">,
          discussion_board_comment_id: commentId,
          discussion_board_uploaded_by_id: member.id,
          original_filename: item.original_filename,
          storage_key: item.storage_key,
          mime_type: item.mime_type,
          size: item.size,
          is_image: item.is_image ?? false,
          // Basic quarantine heuristic; real scanning integration should replace this
          quarantined:
            /application\/(x-msdownload|x-msdos-program)/i.test(
              item.mime_type,
            ) || item.size > 26214400,
          created_at: now,
        },
      }),
    );

    await Promise.all(creations);
  });

  // Retrieve current attachments for the comment (server-only storage_key kept internal)
  const attachments =
    await MyGlobal.prisma.discussion_board_comment_attachments.findMany({
      where: { discussion_board_comment_id: commentId },
      orderBy: { created_at: "desc" },
      select: {
        id: true,
        discussion_board_comment_id: true,
        original_filename: true,
        mime_type: true,
        size: true,
        is_image: true,
        quarantined: true,
        created_at: true,
        discussion_board_uploaded_by_id: true,
        storage_key: true,
      },
    });

  // Build summaries without exposing storage_key; generate placeholder signed URLs
  const summaryPromises = attachments.map(async (r) => {
    const createdAt = r.created_at ? toISOStringSafe(r.created_at) : now;

    // If quarantined, do not provide a download URL.
    const downloadUrl = r.quarantined
      ? null
      : typia.random<string & tags.Format<"uri">>();

    let uploader: IDiscussionBoardMember.ISummary | null = null;
    if (r.discussion_board_uploaded_by_id) {
      const u = await MyGlobal.prisma.discussion_board_member.findUnique({
        where: { id: r.discussion_board_uploaded_by_id },
        select: {
          id: true,
          username: true,
          display_name: true,
          created_at: true,
        },
      });
      if (u) {
        uploader = {
          id: u.id as string & tags.Format<"uuid">,
          username: u.username,
          display_name: u.display_name ?? null,
          created_at: toISOStringSafe(u.created_at),
        };
      }
    }

    const summary: IDiscussionBoardCommentAttachment.ISummary = {
      id: r.id as string & tags.Format<"uuid">,
      commentId: r.discussion_board_comment_id as string & tags.Format<"uuid">,
      originalFilename: r.original_filename,
      mimeType: r.mime_type,
      size: r.size,
      isImage: r.is_image,
      quarantined: r.quarantined,
      createdAt,
      downloadUrl,
      cdnUrl: null,
      uploader,
    };

    return summary;
  });

  const data = await Promise.all(summaryPromises);

  const total =
    await MyGlobal.prisma.discussion_board_comment_attachments.count({
      where: { discussion_board_comment_id: commentId },
    });

  const limit = Number(body.attachments.length);

  return {
    pagination: {
      current: Number(1),
      limit: Number(limit),
      records: Number(total),
      pages: Number(Math.ceil(total / Math.max(1, limit))),
    },
    data,
  };
}

