import { IDiscussionBoardArticleTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleTag";
import { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function postDiscussionBoardMemberArticlesArticleIdTags(props: {
  member: MemberPayload;
  articleId: string & tags.Format<"uuid">;
  body: IDiscussionBoardArticleTag.ICreate;
}): Promise<IDiscussionBoardArticleTag> {
  const { member, articleId, body } = props;

  // Verify target article exists and is not soft-deleted
  const article =
    await MyGlobal.prisma.discussion_board_articles.findFirstOrThrow({
      where: { id: articleId, deleted_at: null },
      select: {
        id: true,
        title: true,
        discussion_board_member_id: true,
        created_at: true,
      },
    });

  // Authorization: only the article author may assign tags
  if (article.discussion_board_member_id !== member.id) {
    throw new HttpException(
      "Unauthorized: Only the article author can assign tags",
      403,
    );
  }

  // Resolve tag by slug
  const tag = await MyGlobal.prisma.discussion_board_tags.findUnique({
    where: { slug: body.tagSlug },
    select: {
      id: true,
      name: true,
      slug: true,
      description: true,
      is_active: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
    },
  });

  if (!tag) {
    throw new HttpException("Tag not found", 404);
  }

  // Prepare values
  const id = v4() as string & tags.Format<"uuid">;
  const now = toISOStringSafe(new Date());

  // Attempt to create junction row; handle unique-constraint race with try/catch
  try {
    await MyGlobal.prisma.discussion_board_article_tags.create({
      data: {
        id,
        discussion_board_article_id: articleId,
        discussion_board_tag_id: tag.id,
        created_at: now,
        created_by_member_id: member.id,
      },
    });
  } catch (e) {
    // Prisma unique constraint or other DB error
    if (
      e instanceof Prisma.PrismaClientKnownRequestError &&
      e.code === "P2002"
    ) {
      // Unique violation on (discussion_board_article_id, discussion_board_tag_id)
      throw new HttpException("Tag already assigned to article", 409);
    }
    throw new HttpException("Internal Server Error", 500);
  }

  // Fetch creator summary (member) for response
  const creator =
    await MyGlobal.prisma.discussion_board_member.findUniqueOrThrow({
      where: { id: member.id },
      select: {
        id: true,
        username: true,
        display_name: true,
        created_at: true,
      },
    });

  // Build response matching IDiscussionBoardArticleTag
  return {
    id: id as string & tags.Format<"uuid">,
    article: {
      id: article.id as string & tags.Format<"uuid">,
      title: article.title,
      createdAt: toISOStringSafe(article.created_at),
    },
    tag: {
      id: tag.id as string & tags.Format<"uuid">,
      name: tag.name,
      slug: tag.slug,
      description: tag.description ?? null,
      is_active: tag.is_active,
      created_at: toISOStringSafe(tag.created_at),
      updated_at: tag.updated_at ? toISOStringSafe(tag.updated_at) : null,
      deleted_at: tag.deleted_at ? toISOStringSafe(tag.deleted_at) : null,
    },
    createdAt: now,
    createdBy: {
      id: creator.id as string & tags.Format<"uuid">,
      username: creator.username,
      display_name: creator.display_name ?? null,
      created_at: toISOStringSafe(creator.created_at),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function deleteDiscussionBoardMemberArticlesArticleIdTagsTagSlug(props: {
  member: MemberPayload;
  articleId: string & tags.Format<"uuid">;
  tagSlug: string;
}): Promise<void> {
  const { member, articleId, tagSlug } = props;

  // Resolve tag by slug (ensure not soft-deleted)
  const tag = await MyGlobal.prisma.discussion_board_tags.findFirst({
    where: { slug: tagSlug, deleted_at: null },
  });
  if (!tag) throw new HttpException("Not Found", 404);

  // Validate article exists and is not soft-deleted
  const article = await MyGlobal.prisma.discussion_board_articles.findUnique({
    where: { id: articleId },
  });
  if (!article || article.deleted_at !== null)
    throw new HttpException("Not Found", 404);

  // Load member record to check role
  const memberRecord = await MyGlobal.prisma.discussion_board_member.findUnique(
    {
      where: { id: member.id },
    },
  );
  if (!memberRecord) throw new HttpException("Unauthorized", 401);

  const isOwner = article.discussion_board_member_id === member.id;
  const isPrivileged =
    memberRecord.role === "admin" || memberRecord.role === "moderator";

  if (!isOwner && !isPrivileged) {
    throw new HttpException(
      "Unauthorized: You can only remove tags from your own articles",
      403,
    );
  }

  // Verify association exists
  const association =
    await MyGlobal.prisma.discussion_board_article_tags.findFirst({
      where: {
        discussion_board_article_id: articleId,
        discussion_board_tag_id: tag.id,
      },
    });
  if (!association) throw new HttpException("Not Found", 404);

  // Perform hard delete of the association
  await MyGlobal.prisma.discussion_board_article_tags.delete({
    where: { id: association.id },
  });

  // If removal performed by privileged actor (not the owner), record audit
  if (!isOwner && isPrivileged) {
    await MyGlobal.prisma.discussion_board_moderation_audit.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        moderation_action_id: null,
        report_id: null,
        actor_moderator_id: null,
        event_type: "article.tag.removal",
        event_payload: JSON.stringify({
          actor_member_id: member.id,
          article_id: articleId,
          tag_id: tag.id,
          tag_slug: tag.slug,
          association_id: association.id,
        }),
        occurred_at: toISOStringSafe(new Date()),
      },
    });
  }

  return;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import { IDiscussionBoardReportReasonCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportReasonCategory";
import { IDiscussionBoardReportStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportStatus";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function postDiscussionBoardMemberReports(props: {
  member: MemberPayload;
  body: IDiscussionBoardReport.ICreate;
}): Promise<IDiscussionBoardReport> {
  const { member, body } = props;

  // Business validation: supported target types
  const supportedTargets = ["article", "comment", "attachment"];
  if (!supportedTargets.includes(body.target_type)) {
    throw new HttpException("Bad Request: unsupported target_type", 400);
  }

  // Verify target existence according to target_type
  if (body.target_type === "article") {
    const article = await MyGlobal.prisma.discussion_board_articles.findUnique({
      where: { id: body.target_id },
      select: { id: true },
    });
    if (!article) throw new HttpException("Not Found", 404);
  } else if (body.target_type === "comment") {
    const comment = await MyGlobal.prisma.discussion_board_comments.findUnique({
      where: { id: body.target_id },
      select: { id: true },
    });
    if (!comment) throw new HttpException("Not Found", 404);
  } else {
    const attachment =
      await MyGlobal.prisma.discussion_board_attachments.findUnique({
        where: { id: body.target_id },
        select: { id: true },
      });
    if (!attachment) throw new HttpException("Not Found", 404);
  }

  const now = toISOStringSafe(new Date());

  try {
    const created = await MyGlobal.prisma.discussion_board_reports.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        reporter_member_id: member.id,
        reporter_session_id: member.session_id ?? null,
        target_type: body.target_type,
        target_id: body.target_id,
        reason_category: body.reason_category,
        explanation: body.explanation ?? null,
        status: "pending",
        created_at: now,
      },
    });

    return {
      id: created.id as string & tags.Format<"uuid">,
      reporter_member_id: created.reporter_member_id as string &
        tags.Format<"uuid">,
      reporter_session_id: created.reporter_session_id ?? undefined,
      target_type: created.target_type,
      target_id: created.target_id as string & tags.Format<"uuid">,
      reason_category:
        created.reason_category as IDiscussionBoardReportReasonCategory,
      explanation: created.explanation ?? undefined,
      status: created.status as IDiscussionBoardReportStatus,
      created_at: now,
      processed_at: created.processed_at
        ? toISOStringSafe(created.processed_at)
        : null,
      closed_at: created.closed_at ? toISOStringSafe(created.closed_at) : null,
    };
  } catch (err) {
    if (
      err instanceof Prisma.PrismaClientKnownRequestError &&
      err.code === "P2002"
    ) {
      throw new HttpException("Conflict: Report already exists", 409);
    }

    const cid = v4() as string & tags.Format<"uuid">;
    throw new HttpException(`Internal Server Error: ${cid}`, 500);
  }
}

