export async function patchDiscussionBoardModeratorArticlesArticleIdReports(props: {
  moderator: ModeratorPayload;
  articleId: string & tags.Format<"uuid">;
  body: IDiscussionBoardReport.IRequest;
}): Promise<IPageIDiscussionBoardReport.ISummary> {
  const { moderator, articleId, body } = props;

  // Verify article exists
  try {
    await MyGlobal.prisma.discussion_board_articles.findUniqueOrThrow({
      where: { id: articleId },
    });
  } catch (err) {
    throw new HttpException("Not Found", 404);
  }

  const page = Number(body.page ?? 1);
  const limit = Math.min(Number(body.limit ?? 20), 100);
  const skip = (page - 1) * limit;

  // Record moderator access for audit purposes
  try {
    const occurred_at = toISOStringSafe(new Date());
    await MyGlobal.prisma.discussion_board_moderation_audit.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        moderation_action_id: null,
        report_id: null,
        actor_moderator_id: moderator.id,
        event_type: "report.search",
        event_payload: JSON.stringify({ articleId, filters: body }),
        occurred_at: occurred_at,
      },
    });
  } catch (err) {
    // Audit failure should not block the main operation; log if available
    // Continue execution
  }

  try {
    const [rows, total] = await Promise.all([
      MyGlobal.prisma.discussion_board_reports.findMany({
        where: {
          target_type: "article",
          target_id: articleId,
          ...(body.status !== undefined && { status: body.status }),
          ...(body.reasonCategory !== undefined &&
            body.reasonCategory !== null && {
              reason_category: body.reasonCategory,
            }),
          ...(body.reporterMemberId !== undefined &&
            body.reporterMemberId !== null && {
              reporter_member_id: body.reporterMemberId,
            }),
          ...((body.createdFrom !== undefined && body.createdFrom !== null) ||
          (body.createdTo !== undefined && body.createdTo !== null)
            ? {
                created_at: {
                  ...(body.createdFrom !== undefined &&
                    body.createdFrom !== null && { gte: body.createdFrom }),
                  ...(body.createdTo !== undefined &&
                    body.createdTo !== null && { lte: body.createdTo }),
                },
              }
            : {}),
          ...((body.processedFrom !== undefined &&
            body.processedFrom !== null) ||
          (body.processedTo !== undefined && body.processedTo !== null)
            ? {
                processed_at: {
                  ...(body.processedFrom !== undefined &&
                    body.processedFrom !== null && { gte: body.processedFrom }),
                  ...(body.processedTo !== undefined &&
                    body.processedTo !== null && { lte: body.processedTo }),
                },
              }
            : {}),
          ...(body.search !== undefined &&
            body.search !== null && { explanation: { contains: body.search } }),
          ...(body.includeProcessed !== true && { processed_at: null }),
          ...(body.includeClosed !== true && { closed_at: null }),
        },
        orderBy:
          body.sortBy === "createdAt"
            ? { created_at: "asc" }
            : body.sortBy === "-createdAt"
              ? { created_at: "desc" }
              : body.sortBy === "processedAt"
                ? { processed_at: "asc" }
                : body.sortBy === "-processedAt"
                  ? { processed_at: "desc" }
                  : { created_at: "desc" },
        skip,
        take: limit,
        select: {
          id: true,
          reporter_member_id: true,
          reason_category: true,
          target_id: true,
          status: true,
          created_at: true,
          processed_at: true,
          closed_at: true,
          explanation: true,
          ...(body.includeReporterContext
            ? {
                reporterMember: {
                  select: {
                    id: true,
                    username: true,
                    display_name: true,
                    created_at: true,
                  },
                },
              }
            : {}),
        },
      }),

      MyGlobal.prisma.discussion_board_reports.count({
        where: {
          target_type: "article",
          target_id: articleId,
          ...(body.status !== undefined && { status: body.status }),
          ...(body.reasonCategory !== undefined &&
            body.reasonCategory !== null && {
              reason_category: body.reasonCategory,
            }),
          ...(body.reporterMemberId !== undefined &&
            body.reporterMemberId !== null && {
              reporter_member_id: body.reporterMemberId,
            }),
          ...((body.createdFrom !== undefined && body.createdFrom !== null) ||
          (body.createdTo !== undefined && body.createdTo !== null)
            ? {
                created_at: {
                  ...(body.createdFrom !== undefined &&
                    body.createdFrom !== null && { gte: body.createdFrom }),
                  ...(body.createdTo !== undefined &&
                    body.createdTo !== null && { lte: body.createdTo }),
                },
              }
            : {}),
          ...((body.processedFrom !== undefined &&
            body.processedFrom !== null) ||
          (body.processedTo !== undefined && body.processedTo !== null)
            ? {
                processed_at: {
                  ...(body.processedFrom !== undefined &&
                    body.processedFrom !== null && { gte: body.processedFrom }),
                  ...(body.processedTo !== undefined &&
                    body.processedTo !== null && { lte: body.processedTo }),
                },
              }
            : {}),
          ...(body.search !== undefined &&
            body.search !== null && { explanation: { contains: body.search } }),
          ...(body.includeProcessed !== true && { processed_at: null }),
          ...(body.includeClosed !== true && { closed_at: null }),
        },
      }),
    ]);

    const data = rows.map((r) => {
      const excerpt = r.explanation
        ? r.explanation.length > 500
          ? r.explanation.slice(0, 500)
          : r.explanation
        : null;

      return {
        id: r.id as string & tags.Format<"uuid">,
        reporterMemberId:
          r.reporter_member_id === null
            ? null
            : (r.reporter_member_id as string & tags.Format<"uuid">),
        reporter:
          body.includeReporterContext && r.reporterMember
            ? {
                id: r.reporterMember.id as string & tags.Format<"uuid">,
                username: r.reporterMember.username,
                display_name: r.reporterMember.display_name ?? null,
                created_at: toISOStringSafe(r.reporterMember.created_at),
              }
            : undefined,
        reasonCategory:
          r.reason_category as IDiscussionBoardReportReasonCategory,
        targetType: "article",
        targetId: r.target_id as string & tags.Format<"uuid">,
        status: r.status as IDiscussionBoardReportStatus,
        createdAt: toISOStringSafe(r.created_at),
        processedAt: r.processed_at ? toISOStringSafe(r.processed_at) : null,
        closedAt: r.closed_at ? toISOStringSafe(r.closed_at) : null,
        explanationExcerpt: excerpt,
      };
    });

    return {
      pagination: {
        current: Number(page),
        limit: Number(limit),
        records: total,
        pages: Math.ceil(total / limit),
      },
      data,
    };
  } catch (error) {
    throw new HttpException("Internal Server Error", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";
import { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IDiscussionBoardReportReasonCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportReasonCategory";
import { IDiscussionBoardReportStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportStatus";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function postDiscussionBoardModeratorModerationActions(props: {
  moderator: ModeratorPayload;
  body: IDiscussionBoardModerationAction.ICreate;
}): Promise<IDiscussionBoardModerationAction> {
  const { moderator, body } = props;

  // Verify moderator exists and is active
  const moderatorRecord =
    await MyGlobal.prisma.discussion_board_moderator.findUnique({
      where: { id: moderator.id },
    });
  if (!moderatorRecord || moderatorRecord.deleted_at) {
    throw new HttpException(
      "Unauthorized: moderator not found or deleted",
      403,
    );
  }

  // Verify referenced report if provided
  let reportRecord = null;
  if (
    body.discussion_board_report_id !== undefined &&
    body.discussion_board_report_id !== null
  ) {
    reportRecord = await MyGlobal.prisma.discussion_board_reports.findUnique({
      where: { id: body.discussion_board_report_id },
    });
    if (!reportRecord) throw new HttpException("Report not found", 404);
  }

  // Validate target existence when provided
  if (
    body.target_type !== undefined &&
    body.target_type !== null &&
    body.target_id !== undefined &&
    body.target_id !== null
  ) {
    switch (body.target_type) {
      case "article": {
        const article =
          await MyGlobal.prisma.discussion_board_articles.findUnique({
            where: { id: body.target_id },
          });
        if (!article) throw new HttpException("Target article not found", 404);
        break;
      }
      case "comment": {
        const comment =
          await MyGlobal.prisma.discussion_board_comments.findUnique({
            where: { id: body.target_id },
          });
        if (!comment) throw new HttpException("Target comment not found", 404);
        break;
      }
      case "attachment": {
        const attachment =
          await MyGlobal.prisma.discussion_board_attachments.findUnique({
            where: { id: body.target_id },
          });
        if (!attachment)
          throw new HttpException("Target attachment not found", 404);
        break;
      }
      case "member": {
        const member = await MyGlobal.prisma.discussion_board_member.findUnique(
          { where: { id: body.target_id } },
        );
        if (!member) throw new HttpException("Target member not found", 404);
        break;
      }
      default: {
        throw new HttpException("Unsupported target type", 400);
      }
    }
  }

  // Prepare timestamps once for consistency
  const now = toISOStringSafe(new Date());
  const effectiveFrom = body.effective_from
    ? toISOStringSafe(body.effective_from)
    : now;
  const effectiveUntil = body.action_duration_days
    ? toISOStringSafe(
        new Date(
          Date.parse(effectiveFrom) +
            body.action_duration_days * 24 * 60 * 60 * 1000,
        ),
      )
    : null;

  // Persist moderation action and audit entry transactionally
  const created = await MyGlobal.prisma.$transaction(async (tx) => {
    const createdAction = await tx.discussion_board_moderation_actions.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        moderator_id: moderator.id,
        discussion_board_report_id: body.discussion_board_report_id ?? null,
        action_type: body.action_type,
        action_reason: body.action_reason ?? null,
        action_duration_days: body.action_duration_days ?? null,
        target_type: body.target_type ?? null,
        target_id: body.target_id ?? null,
        created_at: now,
        effective_from: effectiveFrom ?? null,
        effective_until: effectiveUntil ?? null,
      },
    });

    await tx.discussion_board_moderation_audit.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        moderation_action_id: createdAction.id,
        report_id: body.discussion_board_report_id ?? null,
        actor_moderator_id: moderator.id,
        event_type: "moderation.action",
        event_payload: JSON.stringify({
          action_type: body.action_type,
          action_reason: body.action_reason ?? null,
          action_duration_days: body.action_duration_days ?? null,
          target_type: body.target_type ?? null,
          target_id: body.target_id ?? null,
        }),
        occurred_at: now,
      },
    });

    return createdAction;
  });

  // Build moderator summary (convert dates)
  const moderatorSummary: IDiscussionBoardModerator.ISummary = {
    id: moderatorRecord.id as string & tags.Format<"uuid">,
    username: moderatorRecord.username,
    display_name: moderatorRecord.display_name ?? null,
    created_at: toISOStringSafe(moderatorRecord.created_at),
    updated_at: toISOStringSafe(moderatorRecord.updated_at),
    deleted_at: moderatorRecord.deleted_at
      ? toISOStringSafe(moderatorRecord.deleted_at)
      : null,
  };

  // Build optional report summary
  const reportSummary: IDiscussionBoardReport.ISummary | undefined =
    reportRecord
      ? {
          id: reportRecord.id as string & tags.Format<"uuid">,
          reporterMemberId: reportRecord.reporter_member_id ?? null,
          reporter: undefined,
          reasonCategory:
            reportRecord.reason_category as IDiscussionBoardReportReasonCategory,
          targetType: reportRecord.target_type,
          targetId: reportRecord.target_id as string & tags.Format<"uuid">,
          status: reportRecord.status as IDiscussionBoardReportStatus,
          createdAt: toISOStringSafe(reportRecord.created_at),
          processedAt: reportRecord.processed_at
            ? toISOStringSafe(reportRecord.processed_at)
            : null,
          closedAt: reportRecord.closed_at
            ? toISOStringSafe(reportRecord.closed_at)
            : null,
          explanationExcerpt: reportRecord.explanation
            ? reportRecord.explanation.slice(0, 500)
            : null,
          reportCount: null,
          uniqueReporterCount: null,
        }
      : undefined;

  // Map DB record to API DTO return shape
  const response: IDiscussionBoardModerationAction = {
    id: created.id as string & tags.Format<"uuid">,
    actionType: created.action_type as
      | "hide"
      | "remove"
      | "warn"
      | "suspend"
      | "ban",
    actionReason: created.action_reason ?? null,
    actionDurationDays: created.action_duration_days ?? null,
    targetType: created.target_type ?? null,
    targetId: created.target_id ?? null,
    createdAt: toISOStringSafe(created.created_at),
    effectiveFrom: created.effective_from
      ? toISOStringSafe(created.effective_from)
      : null,
    effectiveUntil: created.effective_until
      ? toISOStringSafe(created.effective_until)
      : null,
    moderator: moderatorSummary,
    report: reportSummary ?? undefined,
  };

  return response;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";
import { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IDiscussionBoardReportReasonCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportReasonCategory";
import { IDiscussionBoardReportStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportStatus";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function getDiscussionBoardModeratorModerationActionsActionId(props: {
  moderator: ModeratorPayload;
  actionId: string & tags.Format<"uuid">;
}): Promise<IDiscussionBoardModerationAction> {
  const { moderator, actionId } = props;

  // Verify requesting moderator exists and is active
  const requestingModerator =
    await MyGlobal.prisma.discussion_board_moderator.findUnique({
      where: { id: moderator.id },
      select: {
        id: true,
        deleted_at: true,
      },
    });

  if (!requestingModerator) throw new HttpException("Unauthorized", 401);
  if (requestingModerator.deleted_at) throw new HttpException("Forbidden", 403);

  // Fetch moderation action
  const action =
    await MyGlobal.prisma.discussion_board_moderation_actions.findUnique({
      where: { id: actionId },
    });
  if (!action) throw new HttpException("Not Found", 404);

  // Fetch acting moderator summary
  const actingModeratorRecord =
    await MyGlobal.prisma.discussion_board_moderator.findUnique({
      where: { id: action.moderator_id },
      select: {
        id: true,
        username: true,
        display_name: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
      },
    });

  if (!actingModeratorRecord) throw new HttpException("Not Found", 404);

  const moderatorSummary: IDiscussionBoardModerator.ISummary = {
    id: actingModeratorRecord.id as string & tags.Format<"uuid">,
    username: actingModeratorRecord.username,
    display_name: actingModeratorRecord.display_name ?? null,
    created_at: toISOStringSafe(actingModeratorRecord.created_at),
    updated_at: toISOStringSafe(actingModeratorRecord.updated_at),
    deleted_at: actingModeratorRecord.deleted_at
      ? toISOStringSafe(actingModeratorRecord.deleted_at)
      : null,
  };

  // Optionally fetch report summary if present
  let reportSummary: IDiscussionBoardReport.ISummary | null = null;
  if (
    action.discussion_board_report_id !== null &&
    action.discussion_board_report_id !== undefined
  ) {
    const report = await MyGlobal.prisma.discussion_board_reports.findUnique({
      where: { id: action.discussion_board_report_id },
    });

    if (report) {
      const excerpt = report.explanation
        ? report.explanation.slice(0, 500)
        : null;
      reportSummary = {
        id: report.id as string & tags.Format<"uuid">,
        reporterMemberId:
          report.reporter_member_id === null
            ? null
            : (report.reporter_member_id as string & tags.Format<"uuid">),
        reporter: undefined,
        reasonCategory:
          report.reason_category as IDiscussionBoardReportReasonCategory,
        targetType: report.target_type,
        targetId: report.target_id as string & tags.Format<"uuid">,
        status: report.status as IDiscussionBoardReportStatus,
        createdAt: toISOStringSafe(report.created_at),
        processedAt: report.processed_at
          ? toISOStringSafe(report.processed_at)
          : null,
        closedAt: report.closed_at ? toISOStringSafe(report.closed_at) : null,
        explanationExcerpt:
          excerpt === null ? null : (excerpt as string & tags.MaxLength<500>),
        reportCount: null,
        uniqueReporterCount: null,
      };
    } else {
      reportSummary = null;
    }
  }

  const result: IDiscussionBoardModerationAction = {
    id: action.id as string & tags.Format<"uuid">,
    actionType: action.action_type as
      | "hide"
      | "remove"
      | "warn"
      | "suspend"
      | "ban",
    actionReason: action.action_reason ?? null,
    actionDurationDays: action.action_duration_days ?? null,
    targetType: action.target_type ?? null,
    targetId:
      action.target_id === null
        ? null
        : (action.target_id as string & tags.Format<"uuid">),
    createdAt: toISOStringSafe(action.created_at),
    effectiveFrom: action.effective_from
      ? toISOStringSafe(action.effective_from)
      : null,
    effectiveUntil: action.effective_until
      ? toISOStringSafe(action.effective_until)
      : null,
    moderator: moderatorSummary,
    report: reportSummary,
  };

  return result;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
