    member: MemberPayload,
    @TypedBody()
    body: IDiscussionBoardReport.ICreate,
  ): Promise<IDiscussionBoardReport> {
    try {
      return await postDiscussionBoardMemberReports({
        member,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

